INSERT INTO `flashcards` VALUES (1,13,'GEOGRAPHY','General','What is the capital of France?','Paris','2025-12-29 06:29:26'),(2,13,'GEOGRAPHY','General','Define Photosynthesis','Process used by plants to convert light into energy','2025-12-29 06:29:26'),(3,13,'GEOGRAPHY','General','What is the capital of France?','Paris','2025-12-29 06:46:55'),(4,13,'GEOGRAPHY','General','Define Photosynthesis','Process used by plants to convert light into energy','2025-12-29 06:46:55'),(5,13,'GEOGRAPHY','General','how many planets in our solar system are','8','2025-12-29 06:47:41'),(6,14,'SCIENCE','General','What is the capital of France?','Paris','2025-12-29 06:57:47'),(7,14,'SCIENCE','General','Define Photosynthesis','Process used by plants to convert light into energy','2025-12-29 06:57:47'),(11,15,'SOCIAL STUDIES','General','Who were early humans?','The first people who lived long ago.','2026-01-04 08:30:31'),(12,15,'SOCIAL STUDIES','General','What type of life did early humans lead?','Nomadic life.','2026-01-04 08:30:31'),(13,15,'SOCIAL STUDIES','General','Where did early humans live?','In caves and on tree branches.','2026-01-04 08:30:31'),(14,15,'SOCIAL STUDIES','General','What tools did early humans mostly use?','Stone tools.','2026-01-04 08:30:31'),(15,15,'SOCIAL STUDIES','General','What were early humans called?','Hunters and gatherers.','2026-01-04 08:30:31'),(16,15,'SOCIAL STUDIES','General','What did early humans hunt?','Animals and birds.','2026-01-04 08:30:31'),(17,15,'SOCIAL STUDIES','General','What did early humans gather?','Fruits, roots, and eggs.','2026-01-04 08:30:31'),(18,15,'SOCIAL STUDIES','General','What material was used to make early tools?','Stone.','2026-01-04 08:30:31'),(19,15,'SOCIAL STUDIES','General','What discovery helped humans cook food?','Fire.','2026-01-04 08:30:31'),(20,15,'SOCIAL STUDIES','General','What discovery helped humans stay warm?','Fire.','2026-01-04 08:30:31'),(21,15,'SOCIAL STUDIES','General','What did early humans eat?','Meat, frui