INSERT INTO `mcqs` VALUES (1,1,'Which of the following is a rational number?','???2','??','0.5','???3','c','0.5 can be expressed as 1/2, which is a ratio of integers',NULL,'easy','english','2025-11-29 07:17:04'),(2,1,'The decimal expansion of 22/7 is:','Terminating','Non-terminating and repeating','Non-terminating and non-repeating','None of these','b','22/7 is a rational number with non-terminating repeating decimal',NULL,'medium','english','2025-11-29 07:17:04'),(3,1,'Which is an irrational number?','0.333...','???16','???5','7/3','c','???5 cannot be expressed as a ratio of integers',NULL,'easy','english','2025-11-29 07:17:04'),(4,1,'The product of a non-zero rational and an irrational number is:','Always rational','Always irrational','Can be rational or irrational','Always zero','b','Product of rational and irrational is always irrational',NULL,'medium','english','2025-11-29 07:17:04'),(5,1,'HCF of 26 and 91 is:','13','26','91','1','a','26 = 2 ?? 13, 91 = 7 ?? 13, so HCF is 13',NULL,'easy','english','2025-11-29 07:17:04'),(6,2,'The degree of polynomial 5x?? + 4x?? + 7x is:','1','2','3','7','c','The highest power of x is 3',NULL,'easy','english','2025-11-29 07:17:04'),(7,2,'A polynomial of degree 2 is called:','Linear','Quadratic','Cubic','Biquadratic','b','Degree 2 polynomial is quadratic',NULL,'easy','english','2025-11-29 07:17:04'),(8,2,'Zero of polynomial p(x) = 2x + 5 is:','-5/2','5/2','-2/5','2/5','a','Set 2x + 5 = 0, then x = -5/2',NULL,'medium','english','2025-11-29 07:17:04'),(9,9,'Which word is a noun?','Run','Apple','Quickly','Blue','b','',NULL,'medium','english','2025-11-29 21:02:26'),(10,9,'A noun is a ___','Name of a person, place, or thing','Describing word','Action word','Sound word','a','',NULL,'medium','english','2025-11-29 21:02:26'),(11,9,'Which of these is a place noun?','Dog','Park','Jump','Red','b','',NULL,'medium','english','2025-11-29 21:02:26'),(12,9,'Which word is a person noun?','Teacher','Running','Happy','Slowly','a','',NULL,'medium',