INSERT INTO `quick_revision` VALUES (1,13,'Geography Quick Revision','[{\"q\":\"What is the capital of France?\",\"a\":\"Paris\",\"e\":\"Detailed explanation: Paris is the correct answer because it fits the context of What is the capital of France?\"},{\"q\":\"What process converts light to energy?\",\"a\":\"Photosynthesis\",\"e\":\"Detailed explanation: Photosynthesis is the correct answer because it fits the context of What process converts light to energy?\"},{\"q\":\"How many planets are in the solar system?\",\"a\":\"8 planets\",\"e\":\"Detailed explanation: 8 planets is the correct answer because it fits the context of How many planets are in the solar system?\"},{\"q\":\"How much of Earth surface is water?\",\"a\":\"71%\",\"e\":\"Detailed explanation: 71% is the correct answer because it fits the context of How much of Earth surface is water?\"},{\"q\":\"What is the highest peak on Earth?\",\"a\":\"Mount Everest\",\"e\":\"Detailed explanation: Mount Everest is the correct answer because it fits the context of What is the highest peak on Earth?\"}]','This chapter covers basic geography concepts including capitals, natural processes, and planetary facts.','2025-12-30 08:29:35'),(13,15,'EARLY HUMANS','[{\"q\":\"\\ufeffQuestion\",\"a\":\"Answer\",\"e\":\"Detailed explanation: Answer is the correct answer because it fits the context of \\ufeffQuestion\"},{\"q\":\"Who were early humans?\",\"a\":\"Early humans were the first people who lived long ago. They depended on nature for food, shelter, and protection.\",\"e\":\"Detailed explanation: Early humans were the first people who lived long ago. They depended on nature for food, shelter, and protection. is the correct answer because it fits the context of Who were early humans?\"},{\"q\":\"What kind of life did early humans lead?\",\"a\":\"Early humans led a nomadic life. They moved from place to place in search of food, water, and shelter.\",\"e\":\"Detailed explanation: Early humans led a nomadic life. They moved from place to place in search of food, water, and shelter. is the correct answer because it fits the context of What kind of life did early humans lead?\"},{\"q\":\"Why did early humans live a nomadic life?\",\"a\":\"Early humans did not know farming. They moved to find food, water, and safe shelter.\",\"e\":\"Detailed explanation: Early humans did not know farming. They moved to find food, water, and safe shelter. is the correct answer because it fits the context of Why did early humans live a nomadic life?\"},{\"q\":\"Where did early humans live?\",\"a\":\"Early humans lived in caves and on branches of trees to protect themselves from wild animals and bad weather.\",\"e\":\"Detailed explanation: Early humans lived in caves and on branches of trees to protect themselves from wild animals and bad weather. is the correct answer because it fits the context of Where did early humans live?\"},{\"q\":\"What were early humans called and why?\",\"a\":\"Early humans were called hunters and gatherers because they hunted animals and gathered fruits, roots, and eggs.\",\"e\":\"Detailed explanation: Early humans were called hunters and gatherers because they hunted animals and gathered fruits, roots, and eggs. is the correct answer because it fits the context of What were early humans called and why?\"},{\"q\":\"What food did early humans eat?\",\"a\":\"Early humans ate meat of animals and birds, fruits, roots, and eggs collected from nature.\",\"e\":\"Detailed explanation: Early humans ate meat of animals and birds, fruits, roots, and eggs collected from nature. is the correct answer because it fits the context of What food did early humans eat?\"},{\"q\":\"What clothes did early humans wear?\",\"a\":\"Early humans did not wear stitched clothes. They used leaves, tree bark, and animal skin to cover their bodies.\",\"e\":\"Detailed explanation: Early humans did not wear stitched clothes. They used leaves, tree bark, and animal skin to cover their bodies. is the correct answer because it fits the context of What clothes did early humans wear?\"},{\"q\":\"What tools did early humans use?\",\"a\":\"Early humans mostly used stone tools. Sometimes tools were also made from animal bones and horns.\",\"e\":\"Detailed explanation: Early humans mostly used stone tools. Sometimes tools were also made from animal bones and horns. is the correct answer because it fits the context of What tools did early humans use?\"},{\"q\":\"Why were stone tools important?\",\"a\":\"Stone tools helped early humans hunt animals, cut meat, and dig roots from the ground.\",\"e\":\"Detailed explanation: Stone tools helped early humans hunt animals, cut meat, and dig roots from the ground. is the correct answer because it fits the context of Why were stone tools important?\"},{\"q\":\"How did early humans improve their tools?\",\"a\":\"They tied sharp stones to wooden sticks. This helped them hunt animals from a distance.\",\"e\":\"Detailed explanation: They tied sharp stones to wooden sticks. This helped them hunt animals from a distance. is the correct answer because it fits the context of How did early humans improve their tools?\"},{\"q\":\"How was fire discovered?\",\"a\":\"Fire was discovered when early humans rubbed two stones together and produced sparks.\",\"e\":\"Detailed explanation: Fire was discovered when early humans rubbed two stones together and produced sparks. is the correct answer because it fits the context of How was fire discovered?\"},{\"q\":\"What were the uses of fire?\",\"a\":\"Fire was used for cooking food, keeping warm, giving light, and protecting from wild animals.\",\"e\":\"Detailed explanation: Fire was used for cooking food, keeping warm, giving light, and protecting from wild animals. is the correct answer because it fits the context of What were the uses of fire?\"},{\"q\":\"Why was the discovery of fire important?\",\"a\":\"Fire improved daily life and played a major role in the development of human civilisation.\",\"e\":\"Detailed explanation: Fire improved daily life and played a major role in the development of human civilisation. is the correct answer because it fits the context of Why was the discovery of fire important?\"},{\"q\":\"How did early humans begin farming?\",\"a\":\"Early humans noticed that seeds thrown on the ground grew into plants. This led to farming.\",\"e\":\"Detailed explanation: Early humans noticed that seeds thrown on the ground grew into plants. This led to farming. is the correct answer because it fits the context of How did early humans begin farming?\"},{\"q\":\"What is farming?\",\"a\":\"Farming means growing crops for food. It helped humans produce their own food.\",\"e\":\"Detailed explanation: Farming means growing crops for food. It helped humans produce their own food. is the correct answer because it fits the context of What is farming?\"},{\"q\":\"How did farming change human life?\",\"a\":\"Farming allowed humans to stay in one place and start a settled life.\",\"e\":\"Detailed explanation: Farming allowed humans to stay in one place and start a settled life. is the correct answer because it fits the context of How did farming change human life?\"},{\"q\":\"How was the wheel invented?\",\"a\":\"Early humans saw a log rolling down a hill. This gave them the idea of the wheel.\",\"e\":\"Detailed explanation: Early humans saw a log rolling down a hill. This gave them the idea of the wheel. is the correct answer because it fits the context of How was the wheel invented?\"},{\"q\":\"What were the uses of the wheel?\",\"a\":\"The wheel helped in carrying heavy loads, making carts, pottery, and weaving clothes.\",\"e\":\"Detailed explanation: The wheel helped in carrying heavy loads, making carts, pottery, and weaving clothes. is the correct answer because it fits the context of What were the uses of the wheel?\"},{\"q\":\"Why was the wheel an important invention?\",\"a\":\"The wheel made work easier and improved transport and daily life.\",\"e\":\"Detailed explanation: The wheel made work easier and improved transport and daily life. is the correct answer because it fits the context of Why was the wheel an important invention?\"},{\"q\":\"What is pottery?\",\"a\":\"Pottery is the art of making pots. Early humans used the wheel to make pots.\",\"e\":\"Detailed explanation: Pottery is the art of making pots. Early humans used the wheel to make pots. is the correct answer because it fits the context of What is pottery?\"},{\"q\":\"What is a settled life?\",\"a\":\"A settled life means living in one place permanently instead of moving from place to place.\",\"e\":\"Detailed explanation: A settled life means living in one place permanently instead of moving from place to place. is the correct answer because it fits the context of What is a settled life?\"},{\"q\":\"How did farming and the wheel help humans live a settled life?\",\"a\":\"Farming provided regular food and the wheel made daily work easier.\",\"e\":\"Detailed explanation: Farming provided regular food and the wheel made daily work easier. is the correct answer because it fits the context of How did farming and the wheel help humans live a settled life?\"},{\"q\":\"Which discoveries helped in the development of civilisation?\",\"a\":\"The discovery of fire, farming, and the invention of the wheel helped develop civilisation.\",\"e\":\"Detailed explanation: The discovery of fire, farming, and the invention of the wheel helped develop civilisation. is the correct answer because it fits the context of Which discoveries helped in the development of civilisation?\"},{\"q\":\"Why are early humans associated with the Stone Age?\",\"a\":\"Early humans mainly used stone tools. Therefore, this period is called the Stone Age.\",\"e\":\"Detailed explanation: Early humans mainly used stone tools. Therefore, this period is called the Stone Age. is the correct answer because it fits the context of Why are early humans associated with the Stone Age?\"},{\"q\":\"How did caves help early humans?\",\"a\":\"Caves gave shelter and protected early humans from wild animals and harsh weather.\",\"e\":\"Detailed explanation: Caves gave shelter and protected early humans from wild animals and harsh weather. is the correct answer because it fits the context of How did caves help early humans?\"},{\"q\":\"How did early humans protect themselves from wild animals?\",\"a\":\"Early humans used fire and lived in safe places like caves.\",\"e\":\"Detailed explanation: Early humans used fire and lived in safe places like caves. is the correct answer because it fits the context of How did early humans protect themselves from wild animals?\"},{\"q\":\"What changes occurred in human life over time?\",\"a\":\"Humans discovered fire, farming, and the wheel which improved their lifestyle.\",\"e\":\"Detailed explanation: Humans discovered fire, farming, and the wheel which improved their lifestyle. is the correct answer because it fits the context of What changes occurred in human life over time?\"},{\"q\":\"Why is it important to study early human life?\",\"a\":\"It helps us understand how human civilisation developed step by step.\",\"e\":\"Detailed explanation: It helps us understand how human civilisation developed step by step. is the correct answer because it fits the context of Why is it important to study early human life?\"}]','EARLY HUMANS','2026-01-04 08:42:38'),(21,16,'थेंब','[{\"q\":\"\\ufeffQuestion\",\"a\":\"Answer\",\"e\":\"Detailed explanation: Answer is the correct answer because it fits the context of \\ufeffQuestion\"},{\"q\":\"\\u0925\\u0947\\u0902\\u092c \\u0915\\u094b\\u0923\\u0924\\u094d\\u092f\\u093e \\u0920\\u093f\\u0915\\u093e\\u0923\\u0940 \\u092c\\u0938\\u0932\\u0947 \\u0939\\u094b\\u0924\\u0947 \\u0924\\u0947 \\u0938\\u0935\\u093f\\u0938\\u094d\\u0924\\u0930 \\u0938\\u093e\\u0902\\u0917\\u093e.\",\"a\":\"\\u0925\\u0947\\u0902\\u092c \\u0906\\u0915\\u093e\\u0936\\u093e\\u0924\\u0942\\u0928 \\u092f\\u0947\\u090a\\u0928 \\u091b\\u094b\\u0