932\\u094d\\u092f\\u093e\\u0932\\u093e \\u0928\\u093f\\u0938\\u0930\\u094d\\u0917\\u093e\\u092c\\u0926\\u094d\\u0926\\u0932 \\u0915\\u093e\\u092f \\u0936\\u093f\\u0915\\u093e\\u092f\\u0932\\u093e \\u092e\\u093f\\u0933\\u0924\\u0947?\",\"a\":\"\\u0939\\u0940 \\u0915\\u0935\\u093f\\u0924\\u093e \\u0906\\u092a\\u0932\\u094d\\u092f\\u093e\\u0932\\u093e \\u0928\\u093f\\u0938\\u0930\\u094d\\u0917\\u093e\\u091a\\u0947 \\u0938\\u094c\\u0902\\u0926\\u0930\\u094d\\u092f \\u0913\\u0933\\u0916\\u093e\\u092f\\u0932\\u093e \\u0936\\u093f\\u0915\\u0935\\u0924\\u0947. \\u0932\\u0939\\u093e\\u0928 \\u0932\\u0939\\u093e\\u0928 \\u0925\\u0947\\u0902\\u092c\\u0939\\u0940 \\u0928\\u093f\\u0938\\u0930\\u094d\\u0917\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0915\\u093f\\u0924\\u0940 \\u092e\\u0939\\u0924\\u094d\\u0924\\u094d\\u0935\\u093e\\u091a\\u0947 \\u0905\\u0938\\u0924\\u093e\\u0924 \\u0939\\u0947 \\u0938\\u092e\\u091c\\u0924\\u0947.\",\"e\":\"Detailed explanation: \\u0939\\u0940 \\u0915\\u0935\\u093f\\u0924\\u093e \\u0906\\u092a\\u0932\\u094d\\u092f\\u093e\\u0932\\u093e \\u0928\\u093f\\u0938\\u0930\\u094d\\u0917\\u093e\\u091a\\u0947 \\u0938\\u094c\\u0902\\u0926\\u0930\\u094d\\u092f \\u0913\\u0933\\u0916\\u093e\\u092f\\u0932\\u093e \\u0936\\u093f\\u0915\\u0935\\u0924\\u0947. \\u0932\\u0939\\u093e\\u0928 \\u0932\\u0939\\u093e\\u0928 \\u0925\\u0947\\u0902\\u092c\\u0939\\u0940 \\u0928\\u093f\\u0938\\u0930\\u094d\\u0917\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0915\\u093f\\u0924\\u0940 \\u092e\\u0939\\u0924\\u094d\\u0924\\u094d\\u0935\\u093e\\u091a\\u0947 \\u0905\\u0938\\u0924\\u093e\\u0924 \\u0939\\u0947 \\u0938\\u092e\\u091c\\u0924\\u0947. is the correct answer because it fits the context of \\u0925\\u0947\\u0902\\u092c \\u0915\\u0935\\u093f\\u0924\\u0947\\u092e\\u0941\\u0933\\u0947 \\u0906\\u092a\\u0932\\u094d\\u092f\\u093e\\u0932\\u093e \\u0928\\u093f\\u0938\\u0930\\u094d\\u0917\\u093e\\u092c\\u0926\\u094d\\u0926\\u0932 \\u0915\\u093e\\u092f \\u0936\\u093f\\u0915\\u093e\\u092f\\u0932\\u093e \\u092e\\u093f\\u0933\\u0924\\u0947?\"}]','थेंब','2026-01-10 03:36:09'),(22,77,'INDUS VALLEY CIVILSATION','[{\"q\":\"\\ufeffQuestion\",\"a\":\"Answer\",\"e\":\"Explanation\"},{\"q\":\"What is the Indus Valley Civilisation?\",\"a\":\"It was the earliest civilisation in the Indian subcontinent.\",\"e\":\"\\u0938\\u093f\\u0902\\u0927\\u0942 \\u0916\\u094b\\u0930\\u0947 \\u0938\\u0902\\u0938\\u094d\\u0915\\u0943\\u0924\\u0940 \\u0939\\u0940 \\u092d\\u093e\\u0930\\u0924\\u0940\\u092f \\u0909\\u092a\\u0916\\u0902\\u0921\\u093e\\u0924\\u0940\\u0932 \\u0938\\u0930\\u094d\\u0935\\u093e\\u0924 \\u092a\\u094d\\u0930\\u093e\\u091a\\u0940\\u0928 \\u0938\\u0902\\u0938\\u094d\\u0915\\u0943\\u0924\\u0940 \\u0939\\u094b\\u0924\\u0940. \\u092f\\u0947\\u0925\\u0947 \\u0932\\u094b\\u0915 \\u090f\\u0915\\u0924\\u094d\\u0930 \\u0930\\u093e\\u0939\\u0942\\u0928 \\u0928\\u093f\\u092f\\u094b\\u091c\\u0928\\u092c\\u0926\\u094d\\u0927 \\u091c\\u0940\\u0935\\u0928 \\u091c\\u0917\\u0924 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"When did the Indus Valley Civilisation flourish?\",\"a\":\"It flourished between 2500 and 1500 BCE.\",\"e\":\"\\u0939\\u0940 \\u0938\\u0902\\u0938\\u094d\\u0915\\u0943\\u0924\\u0940 \\u0907.\\u0938.\\u092a\\u0942. \\u0968\\u096b\\u0966\\u0966 \\u0924\\u0947 \\u0967\\u096b\\u0966\\u0966 \\u092f\\u093e \\u0915\\u093e\\u0933\\u093e\\u0924 \\u0935\\u093f\\u0915\\u0938\\u093f\\u0924 \\u091d\\u093e\\u0932\\u0940.\"},{\"q\":\"Where was the Indus Valley Civilisation located?\",\"a\":\"It was located around the Indus river and its tributaries.\",\"e\":\"\\u0939\\u0940 \\u0938\\u0902\\u0938\\u094d\\u0915\\u0943\\u0924\\u0940 \\u0938\\u093f\\u0902\\u0927\\u0942 \\u0928\\u0926\\u0940 \\u0935 \\u0924\\u093f\\u091a\\u094d\\u092f\\u093e \\u0909\\u092a\\u0928\\u0926\\u094d\\u092f\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u0906\\u0938\\u092a\\u093e\\u0938 \\u0935\\u0938\\u0932\\u0947\\u0932\\u0940 \\u0939\\u094b\\u0924\\u0940.\"},{\"q\":\"Name any two cities of the Indus Valley Civilisation.\",\"a\":\"Harappa and Mohenjo-daro.\",\"e\":\"\\u0939\\u0930\\u092a\\u094d\\u092a\\u093e \\u0906\\u0923\\u093f \\u092e\\u094b\\u0939\\u0928\\u091c\\u094b\\u0926\\u0921\\u094b \\u0939\\u0940 \\u0938\\u093f\\u0902\\u0927\\u0942 \\u0938\\u0902\\u0938\\u094d\\u0915\\u0943\\u0924\\u0940\\u0924\\u0940\\u0932 \\u092a\\u094d\\u0930\\u092e\\u0941\\u0916 \\u0936\\u0939\\u0930\\u0947 \\u0939\\u094b\\u0924\\u0940.\"},{\"q\":\"What were the houses made of?\",\"a\":\"They were made of baked bricks.\",\"e\":\"\\u0918\\u0930\\u0947 \\u092d\\u093e\\u091c\\u0932\\u0947\\u0932\\u094d\\u092f\\u093e \\u0935\\u093f\\u091f\\u093e\\u0902\\u0928\\u0940 \\u092c\\u093e\\u0902\\u0927\\u0932\\u0947\\u0932\\u0940 \\u0939\\u094b\\u0924\\u0940, \\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0924\\u0940 \\u092e\\u091c\\u092c\\u0942\\u0924 \\u0939\\u094b\\u0924\\u0940.\"},{\"q\":\"Which building was used to store grains?\",\"a\":\"The Great Granary.\",\"e\":\"\\u092e\\u0939\\u093e\\u0928 \\u0927\\u093e\\u0928\\u094d\\u092f\\u0915\\u094b\\u0920\\u093e\\u0930\\u093e\\u0924 \\u0905\\u0928\\u094d\\u0928\\u0927\\u093e\\u0928\\u094d\\u092f \\u0938\\u093e\\u0920\\u0935\\u0932\\u0947 \\u091c\\u093e\\u0924 \\u0905\\u0938\\u0947.\"},{\"q\":\"What crops did the people grow?\",\"a\":\"Wheat, rice and barley.\",\"e\":\"\\u0936\\u0947\\u0924\\u0940 \\u0939\\u093e \\u092e\\u0941\\u0916\\u094d\\u092f \\u0935\\u094d\\u092f\\u0935\\u0938\\u093e\\u092f \\u0905\\u0938\\u0942\\u0928 \\u0917\\u0939\\u0942, \\u0924\\u093e\\u0902\\u0926\\u0942\\u0933 \\u0906\\u0923\\u093f \\u092c\\u093e\\u0930\\u094d\\u0932\\u0940 \\u092a\\u093f\\u0915\\u0947 \\u0918\\u0947\\u0924\\u0932\\u0940 \\u091c\\u093e\\u0924.\"},{\"q\":\"What did the Indus people worship?\",\"a\":\"They worshipped nature.\",\"e\":\"\\u0938\\u093f\\u0902\\u0927\\u0942 \\u0938\\u0902\\u0938\\u094d\\u0915\\u0943\\u0924\\u0940\\u0924\\u0940\\u0932 \\u0932\\u094b\\u0915 \\u0928\\u093f\\u0938\\u0930\\u094d\\u0917\\u092a\\u0942\\u091c\\u0915 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Describe the town planning of Indus cities.\",\"a\":\"Cities had straight roads and proper drainage.\",\"e\":\"\\u0936\\u0939\\u0930\\u0947 \\u0928\\u093f\\u092f\\u094b\\u091c\\u0928\\u092c\\u0926\\u094d\\u0927 \\u0939\\u094b\\u0924\\u0940. \\u0930\\u0938\\u094d\\u0924\\u0947 \\u0938\\u0930\\u0933 \\u0935 \\u0930\\u0941\\u0902\\u0926 \\u0939\\u094b\\u0924\\u0947 \\u0924\\u0938\\u0947\\u091a \\u091d\\u093e\\u0915\\u0932\\u0947\\u0932\\u0940 \\u0928\\u093f\\u091a\\u0930\\u093e \\u0935\\u094d\\u092f\\u0935\\u0938\\u094d\\u0925\\u093e \\u0939\\u094b\\u0924\\u0940.\"},{\"q\":\"Explain the importance of the Great Bath.\",\"a\":\"It was a large water tank for special occasions.\",\"e\":\"\\u092e\\u0939\\u093e\\u0928 \\u0938\\u094d\\u0928\\u093e\\u0928\\u0917\\u0943\\u0939 \\u0927\\u093e\\u0930\\u094d\\u092e\\u093f\\u0915 \\u0915\\u093f\\u0902\\u0935\\u093e \\u0935\\u093f\\u0936\\u0947\\u0937 \\u092a\\u094d\\u0930\\u0938\\u0902\\u0917\\u0940 \\u0935\\u093e\\u092a\\u0930\\u0932\\u0947 \\u091c\\u093e\\u0924 \\u0905\\u0938\\u093e\\u0935\\u0947 \\u0905\\u0938\\u0947 \\u092e\\u093e\\u0928\\u0932\\u0947 \\u091c\\u093e\\u0924\\u0947.\"},{\"q\":\"What occupations did the people follow?\",\"a\":\"Farming, crafts, trade and building.\",\"e\":\"\\u0932\\u094b\\u0915 \\u0936\\u0947\\u0924\\u0940, \\u0915\\u093e\\u0930\\u093e\\u0917\\u093f\\u0930\\u0940, \\u0935\\u094d\\u092f\\u093e\\u092a\\u093e\\u0930 \\u0935 \\u092c\\u093e\\u0902\\u0927\\u0915\\u093e\\u092e \\u0905\\u0936\\u0940 \\u0915\\u093e\\u092e\\u0947 \\u0915\\u0930\\u0924.\"},{\"q\":\"Describe the lifestyle of Indus people.\",\"a\":\"They lived an organised life.\",\"e\":\"\\u0932\\u094b\\u0915\\u093e\\u0902\\u091a\\u0947 \\u091c\\u0940\\u0935\\u0928 \\u0936\\u093f\\u0938\\u094d\\u0924\\u092c\\u0926\\u094d\\u0927 \\u0935 \\u0938\\u0941\\u0935\\u094d\\u092f\\u0935\\u0938\\u094d\\u0925\\u093f\\u0924 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"How did people communicate?\",\"a\":\"Through picture symbols.\",\"e\":\"\\u0932\\u094b\\u0915 \\u091a\\u093f\\u0924\\u094d\\u0930\\u0947 \\u0935 \\u091a\\u093f\\u0928\\u094d\\u0939\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u092e\\u093e\\u0927\\u094d\\u092f\\u092e\\u093e\\u0924\\u0942\\u0928 \\u0938\\u0902\\u0935\\u093e\\u0926 \\u0938\\u093e\\u0927\\u0924.\"},{\"q\":\"What were the possible reasons for decline?\",\"a\":\"Floods, diseases and earthquakes.\",\"e\":\"\\u092a\\u0942\\u0930, \\u0930\\u094b\\u0917\\u0930\\u093e\\u0908 \\u0935 \\u092d\\u0942\\u0915\\u0902\\u092a \\u0939\\u0940 \\u0931\\u094d\\u0939\\u093e\\u0938\\u093e\\u091a\\u0940 \\u0915\\u093e\\u0930\\u0923\\u0947 \\u0905\\u0938\\u093e\\u0935\\u0940\\u0924 \\u0905\\u0938\\u0947 \\u092e\\u093e\\u0928\\u0932\\u0947 \\u091c\\u093e\\u0924\\u0947.\"},{\"q\":\"Why is the Indus Valley Civilisation important?\",\"a\":\"It shows early planned urban life.\",\"e\":\"\\u0939\\u0940 \\u0938\\u0902\\u0938\\u094d\\u0915\\u0943\\u0924\\u0940 \\u0928\\u093f\\u092f\\u094b\\u091c\\u0928\\u092c\\u0926\\u094d\\u0927 \\u0936\\u0939\\u0930\\u0940 \\u091c\\u0940\\u0935\\u0928\\u093e\\u091a\\u0940 \\u0938\\u0941\\u0930\\u0941\\u0935\\u093e\\u0924 \\u0926\\u0930\\u094d\\u0936\\u0935\\u0924\\u0947.\"}]','INDUS VALLEY CIVILISATION','2026-01-14 14:26:25'),(23,78,'OUR GOVERNMENT','[{\"q\":\"What is government? (Short Answer)\",\"a\":\"A group of elected members who run the country.\",\"e\":\"\\u0936\\u093e\\u0938\\u0928 \\u092e\\u094d\\u0939\\u0923\\u091c\\u0947 \\u0926\\u0947\\u0936\\u093e\\u0924\\u0940\\u0932 \\u091c\\u0928\\u0924\\u0947\\u0928\\u0947 \\u0928\\u093f\\u0935\\u0921\\u0942\\u0928 \\u0926\\u093f\\u0932\\u0947\\u0932\\u094d\\u092f\\u093e \\u092a\\u094d\\u0930\\u0924\\u093f\\u0928\\u093f\\u0927\\u0940\\u0902\\u091a\\u093e \\u0938\\u092e\\u0942\\u0939 \\u0939\\u094b\\u092f. \\u0939\\u0947 \\u092a\\u094d\\u0930\\u0924\\u093f\\u0928\\u093f\\u0927\\u0940 \\u0926\\u0947\\u0936\\u093e\\u091a\\u0947 \\u0935\\u094d\\u092f\\u0935\\u0938\\u094d\\u0925\\u093e\\u092a\\u0928 \\u0935 \\u091c\\u0928\\u0915\\u0932\\u094d\\u092f\\u093e\\u0923\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0928\\u093f\\u0930\\u094d\\u0923\\u092f \\u0918\\u0947\\u0924\\u093e\\u0924.\"},{\"q\":\"Where is the Central Government of India based? (Short Answer)\",\"a\":\"New Delhi.\",\"e\":\"\\u092d\\u093e\\u0930\\u0924\\u093e\\u091a\\u0947 \\u0915\\u0947\\u0902\\u0926\\u094d\\u0930\\u0940\\u092f \\u0936\\u093e\\u0938\\u0928 \\u0928\\u0935\\u0940 \\u0926\\u093f\\u0932\\u094d\\u0932\\u0940 \\u092f\\u0947\\u0925\\u0947 \\u0906\\u0939\\u0947. \\u0928\\u0935\\u0940 \\u0926\\u093f\\u0932\\u094d\\u0932\\u0940 \\u0939\\u0940 \\u092d\\u093e\\u0930\\u0924\\u093e\\u091a\\u0940 \\u0930\\u093e\\u091c\\u0927\\u093e\\u0928\\u0940 \\u0906\\u0939\\u0947.\"},{\"q\":\"How many levels of government are there in India? (Short Answer)\",\"a\":\"Three levels.\",\"e\":\"\\u092d\\u093e\\u0930\\u0924\\u093e\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0936\\u093e\\u0938\\u0928 \\u0924\\u0940\\u0928 \\u0938\\u094d\\u0924\\u0930\\u093e\\u0902\\u0935\\u0930 \\u0915\\u093e\\u0930\\u094d\\u092f \\u0915\\u0930\\u0924\\u0947 \\u2013 \\u0915\\u0947\\u0902\\u0926\\u094d\\u0930\\u0940\\u092f \\u0936\\u093e\\u0938\\u0928, \\u0930\\u093e\\u091c\\u094d\\u092f \\u0936\\u093e\\u0938\\u0928 \\u0906\\u0923\\u093f \\u0938\\u094d\\u0925\\u093e\\u0928\\u093f\\u0915 \\u0936\\u093e\\u0938\\u0928.\"},{\"q\":\"Name the three levels of government in India. (Long Answer)\",\"a\":\"Central, State and Local Government.\",\"e\":\"\\u092d\\u093e\\u0930\\u0924\\u093e\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0936\\u093e\\u0938\\u0928\\u093e\\u091a\\u0940 \\u0924\\u0940\\u0928 \\u092a\\u093e\\u0924\\u0933\\u0940 \\u0906\\u0939\\u0947\\u0924. \\u0915\\u0947\\u0902\\u0926\\u094d\\u0930\\u0940\\u092f \\u0936\\u093e\\u0938\\u0928 \\u0938\\u0902\\u092a\\u0942\\u0930\\u094d\\u0923 \\u0926\\u0947\\u0936\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0927\\u094b\\u0930\\u0923\\u0947 \\u0920\\u0930\\u0935\\u0924\\u0947, \\u0930\\u093e\\u091c\\u094d\\u092f \\u0936\\u093e\\u0938\\u0928 \\u0930\\u093e\\u091c\\u094d\\u092f\\u093e\\u091a\\u0947 \\u092a\\u094d\\u0930\\u0936\\u093e\\u0938\\u0928 \\u092a\\u093e\\u0939\\u0924\\u0947 \\u0906\\u0923\\u093f \\u0938\\u094d\\u0925\\u093e\\u0928\\u093f\\u0915 \\u0936\\u093e\\u0938\\u0928 \\u0932\\u094b\\u0915\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u092e\\u0942\\u0932\\u092d\\u0942\\u0924 \\u0917\\u0930\\u091c\\u093e\\u0902\\u091a\\u0940 \\u0915\\u093e\\u0933\\u091c\\u0940 \\u0918\\u0947\\u0924\\u0947.\"},{\"q\":\"What are the main functions of the Central Government? (Long Answer)\",\"a\":\"Defence, foreign trade, railways and national welfare.\",\"e\":\"\\u0915\\u0947\\u0902\\u0926\\u094d\\u0930\\u0940\\u092f \\u0936\\u093e\\u0938\\u0928 \\u0926\\u0947\\u0936\\u093e\\u091a\\u0947 \\u0938\\u0902\\u0930\\u0915\\u094d\\u0937\\u0923 \\u0915\\u0930\\u0923\\u0947, \\u092a\\u0930\\u0915\\u0940\\u092f \\u0935\\u094d\\u092f\\u093e\\u092a\\u093e\\u0930 \\u0935 \\u0906\\u0902\\u0924\\u0930\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u0938\\u0902\\u092c\\u0902\\u0927 \\u0938\\u093e\\u0902\\u092d\\u093e\\u0933\\u0923\\u0947, \\u0930\\u0947\\u0932\\u094d\\u0935\\u0947 \\u0935 \\u092a\\u094d\\u0930\\u092e\\u0941\\u0916 \\u0930\\u0938\\u094d\\u0924\\u094d\\u092f\\u093e\\u0902\\u091a\\u0940 \\u0926\\u0947\\u0916\\u092d\\u093e\\u0932 \\u0915\\u0930\\u0923\\u0947 \\u0924\\u0938\\u0947\\u091a \\u0938\\u0902\\u092a\\u0942\\u0930\\u094d\\u0923 \\u0926\\u0947\\u0936\\u093e\\u091a\\u094d\\u092f\\u093e \\u0915\\u0932\\u094d\\u092f\\u093e\\u0923\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0928\\u093f\\u0930\\u094d\\u0923\\u092f \\u0918\\u0947\\u0924\\u0947.\"},{\"q\":\"Who are part of the Central Government? (Short Answer)\",\"a\":\"President, Prime Minister and Ministers.\",\"e\":\"\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u092a\\u0924\\u0940, \\u092a\\u0902\\u0924\\u092a\\u094d\\u0930\\u0927\\u093e\\u0928 \\u0906\\u0923\\u093f \\u0907\\u0924\\u0930 \\u092e\\u0902\\u0924\\u094d\\u0930\\u0940 \\u0939\\u0947 \\u0915\\u0947\\u0902\\u0926\\u094d\\u0930\\u0940\\u092f \\u0936\\u093e\\u0938\\u0928\\u093e\\u091a\\u0947 \\u0918\\u091f\\u0915 \\u0906\\u0939\\u0947\\u0924.\"},{\"q\":\"How many states are there in India? (Short Answer)\",\"a\":\"28 states.\",\"e\":\"\\u092d\\u093e\\u0930\\u0924\\u093e\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0938\\u0927\\u094d\\u092f\\u093e \\u090f\\u0915\\u0942\\u0923 \\u0968\\u096e \\u0930\\u093e\\u091c\\u094d\\u092f\\u0947 \\u0906\\u0939\\u0947\\u0924.\"},{\"q\":\"What does the State Government look after? (Long Answer)\",\"a\":\"Education, healthcare, transport and law &amp; order.\",\"e\":\"\\u0930\\u093e\\u091c\\u094d\\u092f \\u0936\\u093e\\u0938\\u0928 \\u0936\\u093f\\u0915\\u094d\\u0937\\u0923, \\u0906\\u0930\\u094b\\u0917\\u094d\\u092f \\u0938\\u0947\\u0935\\u093e, \\u0935\\u093e\\u0939\\u0924\\u0942\\u0915 \\u0935\\u094d\\u092f\\u0935\\u0938\\u094d\\u0925\\u093e \\u0906\\u0923\\u093f \\u0930\\u093e\\u091c\\u094d\\u092f\\u093e\\u0924\\u0940\\u0932 \\u0915\\u093e\\u092f\\u0926\\u093e \\u0935 \\u0938\\u0941\\u0935\\u094d\\u092f\\u0935\\u0938\\u094d\\u0925\\u093e \\u092f\\u093e\\u0902\\u091a\\u0940 \\u091c\\u092c\\u093e\\u092c\\u0926\\u093e\\u0930\\u0940 \\u0938\\u093e\\u0902\\u092d\\u093e\\u0933\\u0924\\u0947.\"},{\"q\":\"Who is the head of the State Government? (Short Answer)\",\"a\":\"Chief Minister.\",\"e\":\"\\u092e\\u0941\\u0916\\u094d\\u092f\\u092e\\u0902\\u0924\\u094d\\u0930\\u0940 \\u0939\\u093e \\u0930\\u093e\\u091c\\u094d\\u092f \\u0936\\u093e\\u0938\\u0928\\u093e\\u091a\\u093e \\u092a\\u094d\\u0930\\u092e\\u0941\\u0916 \\u0905\\u0938\\u0924\\u094b.\"},{\"q\":\"Who is the constitutional head of a state? (Short Answer)\",\"a\":\"Governor.\",\"e\":\"\\u0930\\u093e\\u091c\\u094d\\u092f\\u093e\\u091a\\u093e \\u0918\\u091f\\u0928\\u093e\\u0924\\u094d\\u092e\\u0915 \\u092a\\u094d\\u0930\\u092e\\u0941\\u0916 \\u0930\\u093e\\u091c\\u094d\\u092f\\u092a\\u093e\\u0932 \\u0905\\u0938\\u0924\\u094b.\"},{\"q\":\"How many Union Territories are there in India? (Short Answer)\",\"a\":\"Eight.\",\"e\":\"\\u092d\\u093e\\u0930\\u0924\\u093e\\u092e\\u0927\\u094d\\u092f\\u0947 \\u090f\\u0915\\u0942\\u0923 \\u096e \\u0915\\u0947\\u0902\\u0926\\u094d\\u0930\\u0936\\u093e\\u0938\\u093f\\u0924 \\u092a\\u094d\\u0930\\u0926\\u0947\\u0936 \\u0906\\u0939\\u0947\\u0924.\"},{\"q\":\"Who governs the Union Territories? (Short Answer)\",\"a\":\"Central Government.\",\"e\":\"\\u0915\\u0947\\u0902\\u0926\\u094d\\u0930\\u0936\\u093e\\u0938\\u093f\\u0924 \\u092a\\u094d\\u0930\\u0926\\u0947\\u0936\\u093e\\u0902\\u091a\\u0947 \\u0936\\u093e\\u0938\\u0928 \\u0938\\u0902\\u092a\\u0942\\u0930\\u094d\\u0923\\u092a\\u0923\\u0947 \\u0915\\u093f\\u0902\\u0935\\u093e \\u0905\\u0902\\u0936\\u0924\\u0903 \\u0915\\u0947\\u0902\\u0926\\u094d\\u0930\\u0940\\u092f \\u0936\\u093e\\u0938\\u0928\\u093e\\u0915\\u0921\\u0942\\u0928 \\u0915\\u0947\\u0932\\u0947 \\u091c\\u093e\\u0924\\u0947.\"},{\"q\":\"What is Local Level Government? (Long Answer)\",\"a\":\"Government for cities, towns and villages.\",\"e\":\"\\u0938\\u094d\\u0925\\u093e\\u0928\\u093f\\u0915 \\u0936\\u093e\\u0938\\u0928 \\u0936\\u0939\\u0930, \\u0928\\u0917\\u0930 \\u0906\\u0923\\u093f \\u0917\\u093e\\u0935\\u093e\\u0902\\u092e\\u0927\\u0940\\u0932 \\u0932\\u094b\\u0915\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u0926\\u0948\\u0928\\u0902\\u0926\\u093f\\u0928 \\u0935 \\u092e\\u0942\\u0932\\u092d\\u0942\\u0924 \\u0917\\u0930\\u091c\\u093e \\u091c\\u0938\\u0947 \\u092a\\u093e\\u0923\\u0940\\u092a\\u0941\\u0930\\u0935\\u0920\\u093e, \\u0938\\u094d\\u0935\\u091a\\u094d\\u091b\\u0924\\u093e, \\u0930\\u0938\\u094d\\u0924\\u0947 \\u0935 \\u0909\\u0926\\u094d\\u092f\\u093e\\u0928\\u0947 \\u092f\\u093e\\u0902\\u091a\\u0940 \\u0935\\u094d\\u092f\\u0935\\u0938\\u094d\\u0925\\u093e \\u0915\\u0930\\u0924\\u0947.\"},{\"q\":\"Name the local government body in villages. (Short Answer)\",\"a\":\"Gram Panchayat.\",\"e\":\"\\u0917\\u094d\\u0930\\u093e\\u092e\\u0940\\u0923 \\u092d\\u093e\\u0917\\u093e\\u0924 \\u0917\\u094d\\u0930\\u093e\\u092e\\u092a\\u0902\\u091a\\u093e\\u092f\\u0924 \\u0939\\u0940 \\u0938\\u094d\\u0925\\u093e\\u0928\\u093f\\u0915 \\u0936\\u093e\\u0938\\u0928\\u093e\\u091a\\u0940 \\u092e\\u0941\\u0916\\u094d\\u092f \\u0938\\u0902\\u0938\\u094d\\u0925\\u093e \\u0905\\u0938\\u0924\\u0947.\"},{\"q\":\"Why is local government important? (Long Answer)\",\"a\":\"It manages daily needs of people.\",\"e\":\"\\u0938\\u094d\\u0925\\u093e\\u0928\\u093f\\u0915 \\u0936\\u093e\\u0938\\u0928 \\u0932\\u094b\\u0915\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u0926\\u0948\\u0928\\u0902\\u0926\\u093f\\u0928 \\u0917\\u0930\\u091c\\u093e \\u092a\\u0942\\u0930\\u094d\\u0923 \\u0915\\u0930\\u0924\\u0947. \\u0924\\u094d\\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u092a\\u094d\\u0930\\u0936\\u093e\\u0938\\u0928 \\u0925\\u0947\\u091f \\u091c\\u0928\\u0924\\u0947\\u092a\\u0930\\u094d\\u092f\\u0902\\u0924 \\u092a\\u094b\\u0939\\u094b\\u091a\\u0924\\u0947 \\u0935 \\u091c\\u0940\\u0935\\u0928\\u092e\\u093e\\u0928 \\u0938\\u0941\\u0927\\u093e\\u0930\\u0924\\u0947.\"}]','OUR GOVERNMENT','2026-01-14 14:27:01'),(24,78,'OUR GOVERNMENT','[{\"q\":\"\\ufeffQuestion\",\"a\":\"Answer\",\"e\":\"Explaination in Marathi language\"},{\"q\":\"Explain the meaning of government and describe why it is important for a country.\",\"a\":\"A government is a group of elected members responsible for making decisions and working for the safety, welfare, and development of a country.\",\"e\":\"\\u0938\\u0930\\u0915\\u093e\\u0930 \\u092e\\u094d\\u0939\\u0923\\u091c\\u0947 \\u0926\\u0947\\u0936\\u093e\\u0924\\u0940\\u0932 \\u0932\\u094b\\u0915\\u093e\\u0902\\u0928\\u0940 \\u0928\\u093f\\u0935\\u0921\\u0942\\u0928 \\u0926\\u093f\\u0932\\u0947\\u0932\\u094d\\u092f\\u093e \\u092a\\u094d\\u0930\\u0924\\u093f\\u0928\\u093f\\u0927\\u0940\\u0902\\u091a\\u093e \\u0938\\u092e\\u0942\\u0939 \\u0939\\u094b\\u092f. \\u0938\\u0930\\u0915\\u093e\\u0930 \\u0926\\u0947\\u0936\\u093e\\u0924\\u0940\\u0932 \\u0936\\u093e\\u0902\\u0924\\u0924\\u093e, \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e, \\u0935\\u093f\\u0915\\u093e\\u0938 \\u0906\\u0923\\u093f \\u0932\\u094b\\u0915\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u092e\\u0942\\u0932\\u092d\\u0942\\u0924 \\u0917\\u0930\\u091c\\u093e\\u0902\\u091a\\u0940 \\u092a\\u0942\\u0930\\u094d\\u0924\\u0924\\u093e \\u0915\\u0930\\u0923\\u094d\\u092f\\u093e\\u0938\\u093e\\u0920\\u0940 \\u092e\\u0939\\u0924\\u094d\\u0924\\u094d\\u0935\\u093e\\u091a\\u0947 \\u0928\\u093f\\u0930\\u094d\\u0923\\u092f \\u0918\\u0947\\u0924 \\u0905\\u0938\\u0924\\u0947.\"},{\"q\":\"Describe the levels at which the government works in India.\",\"a\":\"The government in India works at three levels: Central Government, State Government, and Local Level Government.\",\"e\":\"\\u092d\\u093e\\u0930\\u0924\\u093e\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0938\\u0930\\u0915\\u093e\\u0930 \\u0924\\u0940\\u0928 \\u0938\\u094d\\u0924\\u0930\\u093e\\u0902\\u0935\\u0930 \\u0915\\u093e\\u0930\\u094d\\u092f \\u0915\\u0930\\u0924\\u0947. \\u0915\\u0947\\u0902\\u0926\\u094d\\u0930 \\u0938\\u0930\\u0915\\u093e\\u0930 \\u0938\\u0902\\u092a\\u0942\\u0930\\u094d\\u0923 \\u0926\\u0947\\u0936\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0928\\u093f\\u0930\\u094d\\u0923\\u092f \\u0918\\u0947\\u0924\\u0947, \\u0930\\u093e\\u091c\\u094d\\u092f \\u0938\\u0930\\u0915\\u093e\\u0930 \\u0930\\u093e\\u091c\\u094d\\u092f\\u093e\\u091a\\u094d\\u092f\\u093e \\u0915\\u093e\\u0930\\u092d\\u093e\\u0930\\u093e\\u0938\\u093e\\u0920\\u0940 \\u091c\\u092c\\u093e\\u092c\\u0926\\u093e\\u0930 \\u0905\\u0938\\u0924\\u0947 \\u0906\\u0923\\u093f \\u0938\\u094d\\u0925\\u093e\\u0928\\u093f\\u0915 \\u0938\\u0930\\u0915\\u093e\\u0930 \\u0917\\u093e\\u0935, \\u0936\\u0939\\u0930 \\u0935 \\u0928\\u0917\\u0930\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u0917\\u0930\\u091c\\u093e\\u0902\\u091a\\u0940 \\u092a\\u0942\\u0930\\u094d\\u0924\\u0924\\u093e \\u0915\\u0930\\u0924\\u0947.\"},{\"q\":\"Explain the role and functions of the Central Government of India.\",\"a\":\"The Central Government takes decisions for the welfare of the entire country, including defence, foreign trade, and national infrastructure.\",\"e\":\"\\u0915\\u0947\\u0902\\u0926\\u094d\\u0930 \\u0938\\u0930\\u0915\\u093e\\u0930 \\u0938\\u0902\\u092a\\u0942\\u0930\\u094d\\u0923 \\u0926\\u0947\\u0936\\u093e\\u091a\\u094d\\u092f\\u093e \\u0939\\u093f\\u0924\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0928\\u093f\\u0930\\u094d\\u0923\\u092f \\u0918\\u0947\\u0924\\u0947. \\u092a\\u0930\\u0926\\u0947\\u0936\\u0940 \\u0906\\u0915\\u094d\\u0930\\u092e\\u0923\\u093e\\u092a\\u093e\\u0938\\u0942\\u0928 \\u0938\\u0902\\u0930\\u0915\\u094d\\u0937\\u0923, \\u092a\\u0930\\u0926\\u0947\\u0936\\u093e\\u0902\\u0936\\u0940 \\u0935\\u094d\\u092f\\u093e\\u092a\\u093e\\u0930, \\u0938\\u0902\\u0930\\u0915\\u094d\\u0937\\u0923 \\u0926\\u0932\\u093e\\u0902\\u091a\\u0947 \\u0935\\u094d\\u092f\\u0935\\u0938\\u094d\\u0925\\u093e\\u092a\\u0928 \\u0924\\u0938\\u0947\\u091a \\u0930\\u0947\\u0932\\u094d\\u0935\\u0947 \\u0906\\u0923\\u093f \\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u092e\\u0939\\u093e\\u092e\\u093e\\u0930\\u094d\\u0917\\u093e\\u0902\\u091a\\u0940 \\u0909\\u092d\\u093e\\u0930\\u0923\\u0940 \\u0939\\u0940 \\u0924\\u094d\\u092f\\u093e\\u091a\\u0940 \\u092a\\u094d\\u0930\\u092e\\u0941\\u0916 \\u0915\\u093e\\u092e\\u0947 \\u0906\\u0939\\u0947\\u0924.\"},{\"q\":\"Who are the main members of the Central Government?\",\"a\":\"The President, the Prime Minister, and other ministers are members of the Central Government.\",\"e\":\"\\u0915\\u0947\\u0902\\u0926\\u094d\\u0930 \\u0938\\u0930\\u0915\\u093e\\u0930\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u092a\\u0924\\u0940, \\u092a\\u0902\\u0924\\u092a\\u094d\\u0930\\u0927\\u093e\\u0928 \\u0906\\u0923\\u093f \\u0907\\u0924\\u0930 \\u092e\\u0902\\u0924\\u094d\\u0930\\u0940 \\u092f\\u093e\\u0902\\u091a\\u093e \\u0938\\u092e\\u093e\\u0935\\u0947\\u0936 \\u0905\\u0938\\u0924\\u094b. \\u0939\\u0947 \\u0938\\u0930\\u094d\\u0935\\u091c\\u0923 \\u0926\\u0947\\u0936\\u093e\\u091a\\u094d\\u092f\\u093e \\u092a\\u094d\\u0930\\u0936\\u093e\\u0938\\u0928\\u093e\\u0924 \\u092e\\u0939\\u0924\\u094d\\u0924\\u094d\\u0935\\u093e\\u091a\\u0940 \\u092d\\u0942\\u092e\\u093f\\u0915\\u093e \\u092c\\u091c\\u093e\\u0935\\u0924\\u093e\\u0924.\"},{\"q\":\"Explain how the State Government is formed and what its responsibilities are.\",\"a\":\"Each state has its own government, elected by the people of the state, and it manages state-level issues like education and healthcare.\",\"e\":\"\\u092a\\u094d\\u0930\\u0924\\u094d\\u092f\\u0947\\u0915 \\u0930\\u093e\\u091c\\u094d\\u092f\\u093e\\u091a\\u0947 \\u0938\\u094d\\u0935\\u0924\\u0903\\u091a\\u0947 \\u0938\\u0930\\u0915\\u093e\\u0930 \\u0905\\u0938\\u0924\\u0947. \\u0930\\u093e\\u091c\\u094d\\u092f\\u093e\\u0924\\u0940\\u0932 \\u0932\\u094b\\u0915 \\u092a\\u094d\\u0930\\u0924\\u093f\\u0928\\u093f\\u0927\\u0940 \\u0928\\u093f\\u0935\\u0921\\u0924\\u093e\\u0924. \\u0936\\u093f\\u0915\\u094d\\u0937\\u0923, \\u0906\\u0930\\u094b\\u0917\\u094d\\u092f\\u0938\\u0947\\u0935\\u093e, \\u0935\\u093e\\u0939\\u0924\\u0942\\u0915 \\u0906\\u0923\\u093f \\u0915\\u093e\\u092f\\u0926\\u093e-\\u0938\\u0941\\u0935\\u094d\\u092f\\u0935\\u0938\\u094d\\u0925\\u093e \\u092f\\u093e \\u0930\\u093e\\u091c\\u094d\\u092f \\u0938\\u0930\\u0915\\u093e\\u0930\\u091a\\u094d\\u092f\\u093e \\u091c\\u092c\\u093e\\u092c\\u0926\\u093e\\u0931\\u094d\\u092f\\u093e \\u0905\\u0938\\u0924\\u093e\\u0924.\"},{\"q\":\"Name the main members of the State Government and explain their roles briefly.\",\"a\":\"The Governor, Chief Minister, and other ministers form the State Government.\",\"e\":\"\\u0930\\u093e\\u091c\\u094d\\u092f\\u092a\\u093e\\u0932, \\u092e\\u0941\\u0916\\u094d\\u092f\\u092e\\u0902\\u0924\\u094d\\u0930\\u0940 \\u0906\\u0923\\u093f \\u0907\\u0924\\u0930 \\u092e\\u0902\\u0924\\u094d\\u0930\\u0940 \\u0939\\u0947 \\u0930\\u093e\\u091c\\u094d\\u092f \\u0938\\u0930\\u0915\\u093e\\u0930\\u091a\\u0947 \\u092a\\u094d\\u0930\\u092e\\u0941\\u0916 \\u0938\\u0926\\u0938\\u094d\\u092f \\u0905\\u0938\\u0924\\u093e\\u0924. \\u092e\\u0941\\u0916\\u094d\\u092f\\u092e\\u0902\\u0924\\u094d\\u0930\\u0940 \\u0930\\u093e\\u091c\\u094d\\u092f\\u093e\\u091a\\u094d\\u092f\\u093e \\u0915\\u093e\\u0930\\u092d\\u093e\\u0930\\u093e\\u091a\\u0947 \\u0928\\u0947\\u0924\\u0943\\u0924\\u094d\\u0935 \\u0915\\u0930\\u0924\\u093e\\u0924.\"},{\"q\":\"What are Union Territories and how are they governed in India?\",\"a\":\"Union Territories are regions governed partly or fully by the Central Government.\",\"e\":\"\\u0915\\u0947\\u0902\\u0926\\u094d\\u0930\\u0936\\u093e\\u0938\\u093f\\u0924 \\u092a\\u094d\\u0930\\u0926\\u0947\\u0936\\u093e\\u0902\\u0928\\u093e \\u0938\\u0902\\u0918 \\u092a\\u094d\\u0930\\u0926\\u0947\\u0936 \\u0905\\u0938\\u0947 \\u092e\\u094d\\u0939\\u0923\\u0924\\u093e\\u0924. \\u0939\\u0947 \\u092a\\u094d\\u0930\\u0926\\u0947\\u0936 \\u0905\\u0902\\u0936\\u0924\\u0903 \\u0915\\u093f\\u0902\\u0935\\u093e \\u092a\\u0942\\u0930\\u094d\\u0923\\u092a\\u0923\\u0947 \\u0915\\u0947\\u0902\\u0926\\u094d\\u0930 \\u0938\\u0930\\u0915\\u093e\\u0930\\u0926\\u094d\\u0935\\u093e\\u0930\\u0947 \\u092a\\u094d\\u0930\\u0936\\u093e\\u0938\\u093f\\u0924 \\u0915\\u0947\\u0932\\u0947 \\u091c\\u093e\\u0924\\u093e\\u0924.\"},{\"q\":\"Explain the difference between State Governments and Union Territory Governments.\",\"a\":\"States have their own governments, while Union Territories are governed by the Central Government.\",\"e\":\"\\u0930\\u093e\\u091c\\u094d\\u092f\\u093e\\u0902\\u0928\\u093e \\u0938\\u094d\\u0935\\u0924\\u0903\\u091a\\u0947 \\u0938\\u0930\\u0915\\u093e\\u0930 \\u0905\\u0938\\u0924\\u0947, \\u0924\\u0930 \\u0915\\u0947\\u0902\\u0926\\u094d\\u0930\\u0936\\u093e\\u0938\\u093f\\u0924 \\u092a\\u094d\\u0930\\u0926\\u0947\\u0936\\u093e\\u0902\\u0935\\u0930 \\u0915\\u0947\\u0902\\u0926\\u094d\\u0930 \\u0938\\u0930\\u0915\\u093e\\u0930\\u091a\\u093e \\u0925\\u0947\\u091f \\u0915\\u093f\\u0902\\u0935\\u093e \\u0905\\u0902\\u0936\\u0924\\u0903 \\u0928\\u093f\\u092f\\u0902\\u0924\\u094d\\u0930\\u0923 \\u0905\\u0938\\u0924\\u0947.\"},{\"q\":\"What is Local Level Government and why is it important?\",\"a\":\"Local Level Government looks after the needs of villages, towns, and cities.\",\"e\":\"\\u0938\\u094d\\u0925\\u093e\\u0928\\u093f\\u0915 \\u0938\\u0930\\u0915\\u093e\\u0930 \\u0917\\u093e\\u0935, \\u0936\\u0939\\u0930 \\u0906\\u0923\\u093f \\u0928\\u0917\\u0930\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u0926\\u0948\\u0928\\u0902\\u0926\\u093f\\u0928 \\u0917\\u0930\\u091c\\u093e\\u0902\\u091a\\u0940 \\u0915\\u093e\\u0933\\u091c\\u0940 \\u0918\\u0947\\u0924\\u0947. \\u092a\\u093e\\u0923\\u0940\\u092a\\u0941\\u0930\\u0935\\u0920\\u093e, \\u0938\\u094d\\u0935\\u091a\\u094d\\u091b\\u0924\\u093e, \\u0930\\u0938\\u094d\\u0924\\u0947 \\u0906\\u0923\\u093f \\u0909\\u0926\\u094d\\u092f\\u093e\\u0928\\u0947 \\u092f\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0939\\u0947 \\u0938\\u0930\\u0915\\u093e\\u0930 \\u092e\\u0939\\u0924\\u094d\\u0924\\u094d\\u0935\\u093e\\u091a\\u0947 \\u0906\\u0939\\u0947.\"},{\"q\":\"Name the local government bodies in urban areas.\",\"a\":\"Municipal Corporations and Municipal Committees are local government bodies in cities and towns.\",\"e\":\"\\u092e\\u0939\\u093e\\u0928\\u0917\\u0930\\u092a\\u093e\\u0932\\u093f\\u0915\\u093e \\u0906\\u0923\\u093f \\u0928\\u0917\\u0930\\u092a\\u093e\\u0932\\u093f\\u0915\\u093e \\u092f\\u093e \\u0936\\u0939\\u0930\\u0940 \\u092d\\u093e\\u0917\\u093e\\u0924\\u0940\\u0932 \\u0938\\u094d\\u0925\\u093e\\u0928\\u093f\\u0915 \\u0938\\u094d\\u0935\\u0930\\u093e\\u091c\\u094d\\u092f \\u0938\\u0902\\u0938\\u094d\\u0925\\u093e \\u0906\\u0939\\u0947\\u0924. \\u0924\\u094d\\u092f\\u093e \\u0936\\u0939\\u0930\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u0935\\u093f\\u0915\\u093e\\u0938\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0915\\u093e\\u0930\\u094d\\u092f \\u0915\\u0930\\u0924\\u093e\\u0924.\"},{\"q\":\"Explain the local government system in rural areas.\",\"a\":\"In villages, local governance is managed by the Gram Panchayat.\",\"e\":\"\\u0917\\u094d\\u0930\\u093e\\u092e\\u0940\\u0923 \\u092d\\u093e\\u0917\\u093e\\u0924 \\u0917\\u094d\\u0930\\u093e\\u092e\\u092a\\u0902\\u091a\\u093e\\u092f\\u0924 \\u0939\\u0940 \\u0938\\u094d\\u0925\\u093e\\u0928\\u093f\\u0915 \\u0938\\u094d\\u0935\\u0930\\u093e\\u091c\\u094d\\u092f \\u0938\\u0902\\u0938\\u094d\\u0925\\u093e \\u0905\\u0938\\u0924\\u0947. \\u0924\\u0940 \\u0917\\u093e\\u0935\\u093e\\u0924\\u0940\\u0932 \\u0935\\u093f\\u0915\\u093e\\u0938\\u0915\\u093e\\u092e\\u0947 \\u0906\\u0923\\u093f \\u0928\\u093e\\u0917\\u0930\\u093f\\u0915\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u0917\\u0930\\u091c\\u093e \\u092a\\u0942\\u0930\\u094d\\u0923 \\u0915\\u0930\\u0924\\u0947.\"},{\"q\":\"Why are elections important in a democracy?\",\"a\":\"Elections allow people to choose their representatives and form a government.\",\"e\":\"\\u0928\\u093f\\u0935\\u0921\\u0923\\u0941\\u0915\\u093e \\u0932\\u094b\\u0915\\u0936\\u093e\\u0939\\u0940\\u0924\\u0940\\u0932 \\u092e\\u0939\\u0924\\u094d\\u0924\\u094d\\u0935\\u093e\\u091a\\u093e \\u092d\\u093e\\u0917 \\u0906\\u0939\\u0947\\u0924. \\u0924\\u094d\\u092f\\u093e\\u0926\\u094d\\u0935\\u093e\\u0930\\u0947 \\u0932\\u094b\\u0915 \\u0906\\u092a\\u0932\\u094d\\u092f\\u093e \\u092a\\u0938\\u0902\\u0924\\u0940\\u091a\\u0947 \\u092a\\u094d\\u0930\\u0924\\u093f\\u0928\\u093f\\u0927\\u0940 \\u0928\\u093f\\u0935\\u0921\\u0924\\u093e\\u0924 \\u0906\\u0923\\u093f \\u0938\\u0930\\u0915\\u093e\\u0930 \\u0938\\u094d\\u0925\\u093e\\u092a\\u0928 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Explain how government works for the welfare of the people.\",\"a\":\"The government ensures safety, development, and basic facilities for citizens.\",\"e\":\"\\u0938\\u0930\\u0915\\u093e\\u0930 \\u0928\\u093e\\u0917\\u0930\\u093f\\u0915\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924\\u0924\\u0947\\u0938\\u093e\\u0920\\u0940, \\u0935\\u093f\\u0915\\u093e\\u0938\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0906\\u0923\\u093f \\u092e\\u0942\\u0932\\u092d\\u0942\\u0924 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e \\u0909\\u092a\\u0932\\u092c\\u094d\\u0927 \\u0915\\u0930\\u0942\\u0928 \\u0926\\u0947\\u0923\\u094d\\u092f\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0915\\u093e\\u0930\\u094d\\u092f \\u0915\\u0930\\u0924\\u0947.\"},{\"q\":\"Describe the role of government in maintaining law and order.\",\"a\":\"The government makes laws and ensures they are followed to maintain peace.\",\"e\":\"\\u0915\\u093e\\u092f\\u0926\\u093e \\u0906\\u0923\\u093f \\u0938\\u0941\\u0935\\u094d\\u092f\\u0935\\u0938\\u094d\\u0925\\u093e \\u0930\\u093e\\u0916\\u0923\\u094d\\u092f\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0938\\u0930\\u0915\\u093e\\u0930 \\u0915\\u093e\\u092f\\u0926\\u0947 \\u092c\\u0928\\u0935\\u0924\\u0947 \\u0906\\u0923\\u093f \\u0924\\u094d\\u092f\\u093e\\u0902\\u091a\\u0940 \\u0905\\u0902\\u092e\\u0932\\u092c\\u091c\\u093e\\u0935\\u0923\\u0940 \\u0915\\u0930\\u0924\\u0947.\"},{\"q\":\"Summarise the importance of having different levels of government in India.\",\"a\":\"Different levels of government ensure effective administration from national to local level.\",\"e\":\"\\u0938\\u0930\\u0915\\u093e\\u0930\\u091a\\u0947 \\u0935\\u093f\\u0935\\u093f\\u0927 \\u0938\\u094d\\u0924\\u0930 \\u0905\\u0938\\u0932\\u094d\\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0926\\u0947\\u0936\\u092a\\u093e\\u0924\\u0933\\u0940\\u092a\\u093e\\u0938\\u0942\\u0928 \\u0938\\u094d\\u0925\\u093e\\u0928\\u093f\\u0915 \\u092a\\u093e\\u0924\\u0933\\u0940\\u092a\\u0930\\u094d\\u092f\\u0902\\u0924 \\u092a\\u094d\\u0930\\u0936\\u093e\\u0938\\u0928 \\u092a\\u094d\\u0930\\u092d\\u093e\\u0935\\u0940\\u092a\\u0923\\u0947 \\u0930\\u093e\\u092c\\u0935\\u0924\\u093e \\u092f\\u0947\\u0924\\u0947.\"}]','OUR GOVERNMENT','2026-01-16 11:54:13'),(25,79,'NATIONAL SYMBOLS','[{\"q\":\"\\ufeffQuestion\",\"a\":\"Answer\",\"e\":\"Explaination in Marathi language\"},{\"q\":\"Explain why a country needs national symbols and what they represent.\",\"a\":\"A country needs national symbols to express its identity, values, culture, and unity.\",\"e\":\"\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u091a\\u093f\\u0928\\u094d\\u0939\\u0947 \\u0926\\u0947\\u0936\\u093e\\u091a\\u0940 \\u0913\\u0933\\u0916 \\u0926\\u0930\\u094d\\u0936\\u0935\\u0924\\u093e\\u0924. \\u0924\\u0940 \\u0926\\u0947\\u0936\\u093e\\u091a\\u0940 \\u0938\\u0902\\u0938\\u094d\\u0915\\u0943\\u0924\\u0940, \\u092e\\u0942\\u0932\\u094d\\u092f\\u0947, \\u090f\\u0915\\u0924\\u093e \\u0906\\u0923\\u093f \\u0905\\u092d\\u093f\\u092e\\u093e\\u0928 \\u0935\\u094d\\u092f\\u0915\\u094d\\u0924 \\u0915\\u0930\\u0924\\u093e\\u0924.\"},{\"q\":\"Describe the national flag of India and explain the meaning of its colours.\",\"a\":\"The national flag of India has three horizontal colours that symbolise strength, peace, and growth.\",\"e\":\"\\u092d\\u093e\\u0930\\u0924\\u093e\\u091a\\u094d\\u092f\\u093e \\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u0927\\u094d\\u0935\\u091c\\u093e\\u0924 \\u0915\\u0947\\u0936\\u0930\\u0940, \\u092a\\u093e\\u0902\\u0922\\u0930\\u093e \\u0935 \\u0939\\u093f\\u0930\\u0935\\u093e \\u0930\\u0902\\u0917 \\u0906\\u0939\\u0947\\u0924. \\u0915\\u0947\\u0936\\u0930\\u0940 \\u0927\\u0948\\u0930\\u094d\\u092f, \\u092a\\u093e\\u0902\\u0922\\u0930\\u093e \\u0936\\u093e\\u0902\\u0924\\u0924\\u093e \\u0935 \\u0938\\u0924\\u094d\\u092f, \\u0924\\u0930 \\u0939\\u093f\\u0930\\u0935\\u093e \\u0935\\u093f\\u0915\\u093e\\u0938 \\u0935 \\u0938\\u092e\\u0943\\u0926\\u094d\\u0927\\u0940 \\u0926\\u0930\\u094d\\u0936\\u0935\\u0924\\u094b.\"},{\"q\":\"Explain the importance of the Ashoka Chakra in the national flag.\",\"a\":\"The Ashoka Chakra symbolises motion, progress, and righteousness.\",\"e\":\"\\u0905\\u0936\\u094b\\u0915 \\u091a\\u0915\\u094d\\u0930 \\u092a\\u094d\\u0930\\u0917\\u0924\\u0940, \\u0917\\u0924\\u093f\\u092e\\u093e\\u0928\\u0924\\u093e \\u0906\\u0923\\u093f \\u0927\\u0930\\u094d\\u092e\\u093e\\u091a\\u0947 \\u092a\\u094d\\u0930\\u0924\\u0940\\u0915 \\u0906\\u0939\\u0947. \\u0924\\u094d\\u092f\\u093e\\u091a\\u094d\\u092f\\u093e \\u091a\\u094b\\u0935\\u0940\\u0938 \\u0906\\u0931\\u094d\\u092f\\u093e \\u0938\\u0924\\u0924 \\u092a\\u0941\\u0922\\u0947 \\u091c\\u093e\\u0923\\u094d\\u092f\\u093e\\u091a\\u093e \\u0938\\u0902\\u0926\\u0947\\u0936 \\u0926\\u0947\\u0924\\u093e\\u0924.\"},{\"q\":\"Explain the rules that must be followed while hoisting the national flag.\",\"a\":\"The flag should be respected, never allowed to touch the ground, and hoisted properly.\",\"e\":\"\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u0927\\u094d\\u0935\\u091c\\u093e\\u091a\\u093e \\u0938\\u0928\\u094d\\u092e\\u093e\\u0928 \\u0930\\u093e\\u0916\\u0923\\u094d\\u092f\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0924\\u094b \\u091c\\u092e\\u093f\\u0928\\u0940\\u0932\\u093e \\u0932\\u093e\\u0917\\u0942 \\u0926\\u0947\\u090a \\u0928\\u092f\\u0947, \\u092b\\u093e\\u091f\\u0932\\u0947\\u0932\\u093e \\u0915\\u093f\\u0902\\u0935\\u093e \\u092e\\u0933\\u0932\\u0947\\u0932\\u093e \\u0927\\u094d\\u0935\\u091c \\u0935\\u093e\\u092a\\u0930\\u0942 \\u0928\\u092f\\u0947.\"},{\"q\":\"Describe the national emblem of India and its importance.\",\"a\":\"The national emblem is the official seal of India used by the Government.\",\"e\":\"\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u091a\\u093f\\u0928\\u094d\\u0939 \\u0939\\u0947 \\u092d\\u093e\\u0930\\u0924 \\u0938\\u0930\\u0915\\u093e\\u0930\\u091a\\u0947 \\u0905\\u0927\\u093f\\u0915\\u0943\\u0924 \\u092a\\u094d\\u0930\\u0924\\u0940\\u0915 \\u0905\\u0938\\u0942\\u0928 \\u0924\\u0947 \\u0936\\u093e\\u0938\\u0915\\u0940\\u092f \\u0915\\u093e\\u0917\\u0926\\u092a\\u0924\\u094d\\u0930\\u0947 \\u0935 \\u091a\\u0932\\u0928\\u093e\\u0935\\u0930 \\u0935\\u093e\\u092a\\u0930\\u0932\\u0947 \\u091c\\u093e\\u0924\\u0947.\"},{\"q\":\"Explain the features of the Indian national emblem.\",\"a\":\"It is adapted from the Lion Capital of Ashoka and includes the motto &#039;Satyameva Jayate&#039;.\",\"e\":\"\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u091a\\u093f\\u0928\\u094d\\u0939 \\u0905\\u0936\\u094b\\u0915 \\u0938\\u094d\\u0924\\u0902\\u092d\\u093e\\u091a\\u094d\\u092f\\u093e \\u0938\\u093f\\u0902\\u0939\\u092e\\u0941\\u0916\\u093e\\u0935\\u0930 \\u0906\\u0927\\u093e\\u0930\\u093f\\u0924 \\u0906\\u0939\\u0947 \\u0906\\u0923\\u093f \\u0924\\u094d\\u092f\\u093e\\u0935\\u0930 \\u2018\\u0938\\u0924\\u094d\\u092f\\u092e\\u0947\\u0935 \\u091c\\u092f\\u0924\\u0947\\u2019 \\u0939\\u093e \\u092c\\u094b\\u0927\\u0935\\u093e\\u0915\\u094d\\u092f \\u0906\\u0939\\u0947.\"},{\"q\":\"Explain the meaning of the motto &#039;Satyameva Jayate&#039;.\",\"a\":\"&#039;Satyameva Jayate&#039; means truth alone triumphs.\",\"e\":\"\\u2018\\u0938\\u0924\\u094d\\u092f\\u092e\\u0947\\u0935 \\u091c\\u092f\\u0924\\u0947\\u2019 \\u092f\\u093e\\u091a\\u093e \\u0905\\u0930\\u094d\\u0925 \\u0938\\u0924\\u094d\\u092f\\u093e\\u091a\\u093e \\u0928\\u0947\\u0939\\u092e\\u0940 \\u0935\\u093f\\u091c\\u092f \\u0939\\u094b\\u0924\\u094b \\u0905\\u0938\\u093e \\u0906\\u0939\\u0947.\"},{\"q\":\"Describe the national anthem of India.\",\"a\":\"&#039;Jana Gana Mana&#039; is the national anthem that praises the nation.\",\"e\":\"\\u2018\\u091c\\u0928 \\u0917\\u0923 \\u092e\\u0928\\u2019 \\u0939\\u0947 \\u092d\\u093e\\u0930\\u0924\\u093e\\u091a\\u0947 \\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0917\\u0940\\u0924 \\u0905\\u0938\\u0942\\u0928 \\u0924\\u0947 \\u0926\\u0947\\u0936\\u093e\\u091a\\u094d\\u092f\\u093e \\u0917\\u094c\\u0930\\u0935\\u093e\\u091a\\u0947 \\u092a\\u094d\\u0930\\u0924\\u0940\\u0915 \\u0906\\u0939\\u0947.\"},{\"q\":\"Explain the discipline required during the national anthem.\",\"a\":\"People must stand at attention and show respect during the anthem.\",\"e\":\"\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0917\\u0940\\u0924 \\u0938\\u0941\\u0930\\u0942 \\u0905\\u0938\\u0924\\u093e\\u0928\\u093e \\u0938\\u093e\\u0935\\u0927\\u093e\\u0928 \\u0938\\u094d\\u0925\\u093f\\u0924\\u0940\\u0924 \\u0909\\u092d\\u0947 \\u0930\\u093e\\u0939\\u0942\\u0928 \\u0906\\u0926\\u0930 \\u0926\\u0930\\u094d\\u0936\\u0935\\u0923\\u0947 \\u0906\\u0935\\u0936\\u094d\\u092f\\u0915 \\u0906\\u0939\\u0947.\"},{\"q\":\"Describe the national song of India and its role in history.\",\"a\":\"&#039;Vande Mataram&#039; inspired freedom fighters during the independence movement.\",\"e\":\"\\u2018\\u0935\\u0902\\u0926\\u0947 \\u092e\\u093e\\u0924\\u0930\\u092e\\u094d\\u2019 \\u092f\\u093e \\u0917\\u0940\\u0924\\u093e\\u0928\\u0947 \\u0938\\u094d\\u0935\\u093e\\u0924\\u0902\\u0924\\u094d\\u0930\\u094d\\u092f\\u0932\\u0922\\u094d\\u092f\\u093e\\u0924 \\u0938\\u094d\\u0935\\u093e\\u0924\\u0902\\u0924\\u094d\\u0930\\u094d\\u092f\\u0938\\u0948\\u0928\\u093f\\u0915\\u093e\\u0902\\u0928\\u093e \\u092a\\u094d\\u0930\\u0947\\u0930\\u0923\\u093e \\u0926\\u093f\\u0932\\u0940.\"},{\"q\":\"Explain why the Royal Bengal Tiger is the national animal of India.\",\"a\":\"It represents strength, courage, and India&#039;s rich wildlife.\",\"e\":\"\\u0930\\u0949\\u092f\\u0932 \\u092c\\u0902\\u0917\\u093e\\u0932 \\u0935\\u093e\\u0918 \\u0936\\u0915\\u094d\\u0924\\u0940, \\u0927\\u0948\\u0930\\u094d\\u092f \\u0906\\u0923\\u093f \\u092d\\u093e\\u0930\\u0924\\u093e\\u091a\\u094d\\u092f\\u093e \\u0935\\u0928\\u094d\\u092f\\u091c\\u0940\\u0935\\u0928\\u093e\\u091a\\u0947 \\u092a\\u094d\\u0930\\u0924\\u0940\\u0915 \\u0906\\u0939\\u0947.\"},{\"q\":\"Describe the national bird of India.\",\"a\":\"The peacock is the national bird and symbolises beauty and grace.\",\"e\":\"\\u092e\\u094b\\u0930 \\u0939\\u093e \\u092d\\u093e\\u0930\\u0924\\u093e\\u091a\\u093e \\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u092a\\u0915\\u094d\\u0937\\u0940 \\u0905\\u0938\\u0942\\u0928 \\u0924\\u094b \\u0938\\u094c\\u0902\\u0926\\u0930\\u094d\\u092f \\u0935 \\u0938\\u0941\\u0938\\u0902\\u0938\\u094d\\u0915\\u0943\\u0924\\u0924\\u0947\\u091a\\u0947 \\u092a\\u094d\\u0930\\u0924\\u0940\\u0915 \\u0906\\u0939\\u0947.\"},{\"q\":\"Explain the significance of the national flower of India.\",\"a\":\"The lotus symbolises purity, knowledge, and beauty.\",\"e\":\"\\u0915\\u092e\\u0933 \\u0939\\u0947 \\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u092b\\u0942\\u0932 \\u0905\\u0938\\u0942\\u0928 \\u0924\\u0947 \\u092a\\u0935\\u093f\\u0924\\u094d\\u0930\\u0924\\u093e, \\u091c\\u094d\\u091e\\u093e\\u0928 \\u0906\\u0923\\u093f \\u0938\\u094c\\u0902\\u0926\\u0930\\u094d\\u092f\\u093e\\u091a\\u0947 \\u092a\\u094d\\u0930\\u0924\\u0940\\u0915 \\u0906\\u0939\\u0947.\"},{\"q\":\"Explain how national symbols unite citizens.\",\"a\":\"They create a sense of unity and national pride.\",\"e\":\"\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u091a\\u093f\\u0928\\u094d\\u0939\\u0947 \\u0928\\u093e\\u0917\\u0930\\u093f\\u0915\\u093e\\u0902\\u092e\\u0927\\u094d\\u092f\\u0947 \\u090f\\u0915\\u0924\\u093e \\u0906\\u0923\\u093f \\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u093e\\u092d\\u093f\\u092e\\u093e\\u0928\\u093e\\u091a\\u0940 \\u092d\\u093e\\u0935\\u0928\\u093e \\u0928\\u093f\\u0930\\u094d\\u092e\\u093e\\u0923 \\u0915\\u0930\\u0924\\u093e\\u0924.\"},{\"q\":\"Summarise why respecting national symbols is important.\",\"a\":\"Respecting national symbols shows responsibility and love for the nation.\",\"e\":\"\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u091a\\u093f\\u0928\\u094d\\u0939\\u093e\\u0902\\u091a\\u093e \\u0938\\u0928\\u094d\\u092e\\u093e\\u0928 \\u0915\\u0930\\u0923\\u0947 \\u092e\\u094d\\u0939\\u0923\\u091c\\u0947 \\u0926\\u0947\\u0936\\u093e\\u092c\\u0926\\u094d\\u0926\\u0932 \\u092a\\u094d\\u0930\\u0947\\u092e \\u0935 \\u091c\\u092c\\u093e\\u092c\\u0926\\u093e\\u0930\\u0940 \\u0926\\u0930\\u094d\\u0936\\u0935\\u0923\\u0947 \\u0939\\u094b\\u092f.\"}]','NATIONAL SYMBOLS','2026-01-16 12:02:19'),(26,80,'OUR GREAT LEADERS','[{\"q\":\"\\ufeffQuestion\",\"a\":\"Answer\",\"e\":\"Explaination in Marathi language\"},{\"q\":\"Describe the early life and education of Mahatma Gandhi.\",\"a\":\"Mahatma Gandhi was born on 2 October 1869 at Porbandar in Gujarat. He studied law in England and later worked as a lawyer.\",\"e\":\"\\u092e\\u0939\\u093e\\u0924\\u094d\\u092e\\u093e \\u0917\\u093e\\u0902\\u0927\\u0940 \\u092f\\u093e\\u0902\\u091a\\u093e \\u091c\\u0928\\u094d\\u092e \\u0968 \\u0911\\u0915\\u094d\\u091f\\u094b\\u092c\\u0930 \\u0967\\u096e\\u096c\\u096f \\u0930\\u094b\\u091c\\u0940 \\u0917\\u0941\\u091c\\u0930\\u093e\\u0924\\u092e\\u0927\\u0940\\u0932 \\u092a\\u094b\\u0930\\u092c\\u0902\\u0926\\u0930 \\u092f\\u0947\\u0925\\u0947 \\u091d\\u093e\\u0932\\u093e. \\u0924\\u094d\\u092f\\u093e\\u0902\\u0928\\u0940 \\u0907\\u0902\\u0917\\u094d\\u0932\\u0902\\u0921\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0915\\u093e\\u092f\\u0926\\u094d\\u092f\\u093e\\u091a\\u0947 \\u0936\\u093f\\u0915\\u094d\\u0937\\u0923 \\u0918\\u0947\\u0924\\u0932\\u0947 \\u0906\\u0923\\u093f \\u0935\\u0915\\u0940\\u0932 \\u092e\\u094d\\u0939\\u0923\\u0942\\u0928 \\u0915\\u093e\\u092e \\u0915\\u0947\\u0932\\u0947.\"},{\"q\":\"Explain the role of Mahatma Gandhi in India\\u2019s freedom struggle.\",\"a\":\"Mahatma Gandhi led the freedom struggle using the principles of truth, non-violence, and non-cooperation.\",\"e\":\"\\u092e\\u0939\\u093e\\u0924\\u094d\\u092e\\u093e \\u0917\\u093e\\u0902\\u0927\\u0940\\u0902\\u0928\\u0940 \\u0938\\u0924\\u094d\\u092f, \\u0905\\u0939\\u093f\\u0902\\u0938\\u093e \\u0906\\u0923\\u093f \\u0905\\u0938\\u0939\\u0915\\u093e\\u0930 \\u092f\\u093e \\u0924\\u0924\\u094d\\u0924\\u094d\\u0935\\u093e\\u0902\\u0935\\u0930 \\u0906\\u0927\\u093e\\u0930\\u093f\\u0924 \\u0938\\u094d\\u0935\\u093e\\u0924\\u0902\\u0924\\u094d\\u0930\\u094d\\u092f\\u0932\\u0922\\u094d\\u092f\\u093e\\u091a\\u0947 \\u0928\\u0947\\u0924\\u0943\\u0924\\u094d\\u0935 \\u0915\\u0947\\u0932\\u0947.\"},{\"q\":\"Describe the concept of Satyagraha and its importance.\",\"a\":\"Satyagraha was a method of non-violent protest used by Mahatma Gandhi to fight injustice.\",\"e\":\"\\u0938\\u0924\\u094d\\u092f\\u093e\\u0917\\u094d\\u0930\\u0939 \\u0939\\u0940 \\u0905\\u0928\\u094d\\u092f\\u093e\\u092f\\u093e\\u0935\\u093f\\u0930\\u0941\\u0926\\u094d\\u0927 \\u0905\\u0939\\u093f\\u0902\\u0938\\u0915 \\u092e\\u093e\\u0930\\u094d\\u0917\\u093e\\u0928\\u0947 \\u0932\\u0922\\u0923\\u094d\\u092f\\u093e\\u091a\\u0940 \\u092a\\u0926\\u094d\\u0927\\u0924 \\u0939\\u094b\\u0924\\u0940. \\u092f\\u093e \\u091a\\u0933\\u0935\\u0933\\u0940\\u092e\\u0941\\u0933\\u0947 \\u0938\\u093e\\u092e\\u093e\\u0928\\u094d\\u092f \\u0932\\u094b\\u0915 \\u092e\\u094b\\u0920\\u094d\\u092f\\u093e \\u0938\\u0902\\u0916\\u094d\\u092f\\u0947\\u0928\\u0947 \\u0938\\u094d\\u0935\\u093e\\u0924\\u0902\\u0924\\u094d\\u0930\\u094d\\u092f\\u0932\\u0922\\u094d\\u092f\\u093e\\u0924 \\u0938\\u0939\\u092d\\u093e\\u0917\\u0940 \\u091d\\u093e\\u0932\\u0947.\"},{\"q\":\"Explain why Mahatma Gandhi was given the title \\u2018Mahatma\\u2019.\",\"a\":\"The title \\u2018Mahatma\\u2019 was given to Gandhi for his simplicity, moral values, and dedication to the nation.\",\"e\":\"\\u092e\\u0939\\u093e\\u0924\\u094d\\u092e\\u093e \\u0917\\u093e\\u0902\\u0927\\u0940\\u0902\\u091a\\u0940 \\u0938\\u093e\\u0927\\u0940 \\u091c\\u0940\\u0935\\u0928\\u0936\\u0948\\u0932\\u0940, \\u0909\\u091a\\u094d\\u091a \\u0928\\u0948\\u0924\\u093f\\u0915 \\u092e\\u0942\\u0932\\u094d\\u092f\\u0947 \\u0906\\u0923\\u093f \\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u093e\\u0938\\u093e\\u0920\\u0940\\u091a\\u0947 \\u092f\\u094b\\u0917\\u0926\\u093e\\u0928 \\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0924\\u094d\\u092f\\u093e\\u0902\\u0928\\u093e \\u2018\\u092e\\u0939\\u093e\\u0924\\u094d\\u092e\\u093e\\u2019 \\u0939\\u0940 \\u092a\\u0926\\u0935\\u0940 \\u0926\\u0947\\u0923\\u094d\\u092f\\u093e\\u0924 \\u0906\\u0932\\u0940.\"},{\"q\":\"Describe the early life of Pandit Jawaharlal Nehru.\",\"a\":\"Pandit Jawaharlal Nehru was born on 14 November 1889 in Allahabad and studied law.\",\"e\":\"\\u092a\\u0902\\u0921\\u093f\\u0924 \\u091c\\u0935\\u093e\\u0939\\u0930\\u0932\\u093e\\u0932 \\u0928\\u0947\\u0939\\u0930\\u0942 \\u092f\\u093e\\u0902\\u091a\\u093e \\u091c\\u0928\\u094d\\u092e \\u0967\\u096a \\u0928\\u094b\\u0935\\u094d\\u0939\\u0947\\u0902\\u092c\\u0930 \\u0967\\u096e\\u096e\\u096f \\u0930\\u094b\\u091c\\u0940 \\u0905\\u0932\\u093e\\u0939\\u093e\\u092c\\u093e\\u0926 (\\u092a\\u094d\\u0930\\u092f\\u093e\\u0917\\u0930\\u093e\\u091c) \\u092f\\u0947\\u0925\\u0947 \\u091d\\u093e\\u0932\\u093e. \\u0924\\u094d\\u092f\\u093e\\u0902\\u0928\\u0940 \\u0915\\u093e\\u092f\\u0926\\u094d\\u092f\\u093e\\u091a\\u0947 \\u0936\\u093f\\u0915\\u094d\\u0937\\u0923 \\u0918\\u0947\\u0924\\u0932\\u0947.\"},{\"q\":\"Explain the contribution of Jawaharlal Nehru to independent India.\",\"a\":\"Jawaharlal Nehru became the first Prime Minister of independent India and worked for nation-building.\",\"e\":\"\\u0938\\u094d\\u0935\\u0924\\u0902\\u0924\\u094d\\u0930 \\u092d\\u093e\\u0930\\u0924\\u093e\\u091a\\u0947 \\u092a\\u0939\\u093f\\u0932\\u0947 \\u092a\\u0902\\u0924\\u092a\\u094d\\u0930\\u0927\\u093e\\u0928 \\u092e\\u094d\\u0939\\u0923\\u0942\\u0928 \\u092a\\u0902\\u0921\\u093f\\u0924 \\u0928\\u0947\\u0939\\u0930\\u0942 \\u092f\\u093e\\u0902\\u0928\\u0940 \\u0926\\u0947\\u0936\\u093e\\u091a\\u094d\\u092f\\u093e \\u0935\\u093f\\u0915\\u093e\\u0938\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0906\\u0923\\u093f \\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0928\\u093f\\u0930\\u094d\\u092e\\u093e\\u0923\\u093e\\u0938\\u093e\\u0920\\u0940 \\u092e\\u0939\\u0924\\u094d\\u0924\\u094d\\u0935\\u092a\\u0942\\u0930\\u094d\\u0923 \\u0915\\u093e\\u0930\\u094d\\u092f \\u0915\\u0947\\u0932\\u0947.\"},{\"q\":\"Why is Jawaharlal Nehru remembered as \\u2018Chacha Nehru\\u2019?\",\"a\":\"He loved children deeply, and children affectionately called him \\u2018Chacha Nehru\\u2019.\",\"e\":\"\\u092a\\u0902\\u0921\\u093f\\u0924 \\u0928\\u0947\\u0939\\u0930\\u0942 \\u092e\\u0941\\u0932\\u093e\\u0902\\u0935\\u0930 \\u0916\\u0942\\u092a \\u092a\\u094d\\u0930\\u0947\\u092e \\u0915\\u0930\\u0924 \\u0905\\u0938\\u0924, \\u0924\\u094d\\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u092e\\u0941\\u0932\\u0947 \\u0924\\u094d\\u092f\\u093e\\u0902\\u0928\\u093e \\u092a\\u094d\\u0930\\u0947\\u092e\\u093e\\u0928\\u0947 \\u2018\\u091a\\u093e\\u091a\\u093e \\u0928\\u0947\\u0939\\u0930\\u0942\\u2019 \\u092e\\u094d\\u0939\\u0923\\u0924.\"},{\"q\":\"Explain the significance of Children\\u2019s Day in India.\",\"a\":\"Children\\u2019s Day is celebrated on Jawaharlal Nehru\\u2019s birthday to honour his love for children.\",\"e\":\"\\u092a\\u0902\\u0921\\u093f\\u0924 \\u0928\\u0947\\u0939\\u0930\\u0942\\u0902\\u091a\\u094d\\u092f\\u093e \\u091c\\u0928\\u094d\\u092e\\u0926\\u093f\\u0928\\u0940 \\u092e\\u094d\\u0939\\u0923\\u091c\\u0947\\u091a \\u0967\\u096a \\u0928\\u094b\\u0935\\u094d\\u0939\\u0947\\u0902\\u092c\\u0930 \\u0930\\u094b\\u091c\\u0940 \\u092c\\u093e\\u0932\\u0926\\u093f\\u0928 \\u0938\\u093e\\u091c\\u0930\\u093e \\u0915\\u0947\\u0932\\u093e \\u091c\\u093e\\u0924\\u094b, \\u0915\\u093e\\u0930\\u0923 \\u0924\\u094d\\u092f\\u093e\\u0902\\u091a\\u0947 \\u092e\\u0941\\u0932\\u093e\\u0902\\u0935\\u0930\\u0940\\u0932 \\u092a\\u094d\\u0930\\u0947\\u092e \\u092a\\u094d\\u0930\\u0938\\u093f\\u0926\\u094d\\u0927 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Describe the early life and education of Sardar Vallabhbhai Patel.\",\"a\":\"Sardar Vallabhbhai Patel was born on 31 October 1875 in Nadiad and later became a lawyer.\",\"e\":\"\\u0938\\u0930\\u0926\\u093e\\u0930 \\u0935\\u0932\\u094d\\u0932\\u092d\\u092d\\u093e\\u0908 \\u092a\\u091f\\u0947\\u0932 \\u092f\\u093e\\u0902\\u091a\\u093e \\u091c\\u0928\\u094d\\u092e \\u0969\\u0967 \\u0911\\u0915\\u094d\\u091f\\u094b\\u092c\\u0930 \\u0967\\u096e\\u096d\\u096b \\u0930\\u094b\\u091c\\u0940 \\u0917\\u0941\\u091c\\u0930\\u093e\\u0924\\u092e\\u0927\\u0940\\u0932 \\u0928\\u0921\\u093f\\u092f\\u093e\\u0926 \\u092f\\u0947\\u0925\\u0947 \\u091d\\u093e\\u0932\\u093e. \\u0924\\u094d\\u092f\\u093e\\u0902\\u0928\\u0940 \\u0915\\u093e\\u092f\\u0926\\u094d\\u092f\\u093e\\u091a\\u0947 \\u0936\\u093f\\u0915\\u094d\\u0937\\u0923 \\u0918\\u0947\\u0924\\u0932\\u0947.\"},{\"q\":\"Explain the role of Sardar Vallabhbhai Patel in India\\u2019s freedom movement.\",\"a\":\"Sardar Patel actively participated in the freedom struggle inspired by Gandhi\\u2019s Satyagraha.\",\"e\":\"\\u092e\\u0939\\u093e\\u0924\\u094d\\u092e\\u093e \\u0917\\u093e\\u0902\\u0927\\u0940\\u0902\\u091a\\u094d\\u092f\\u093e \\u0938\\u0924\\u094d\\u092f\\u093e\\u0917\\u094d\\u0930\\u0939\\u093e\\u0928\\u0947 \\u092a\\u094d\\u0930\\u0947\\u0930\\u093f\\u0924 \\u0939\\u094b\\u090a\\u0928 \\u0938\\u0930\\u0926\\u093e\\u0930 \\u092a\\u091f\\u0947\\u0932 \\u092f\\u093e\\u0902\\u0928\\u0940 \\u0938\\u094d\\u0935\\u093e\\u0924\\u0902\\u0924\\u094d\\u0930\\u094d\\u092f\\u0932\\u0922\\u094d\\u092f\\u093e\\u0924 \\u0938\\u0915\\u094d\\u0930\\u093f\\u092f \\u0938\\u0939\\u092d\\u093e\\u0917 \\u0918\\u0947\\u0924\\u0932\\u093e.\"},{\"q\":\"Why is Sardar Vallabhbhai Patel known as the \\u2018Iron Man of India\\u2019?\",\"a\":\"He played a key role in uniting the princely states of India into one nation.\",\"e\":\"\\u092d\\u093e\\u0930\\u0924\\u093e\\u091a\\u0940 \\u0938\\u0930\\u094d\\u0935 \\u0938\\u0902\\u0938\\u094d\\u0925\\u093e\\u0928\\u0947 \\u090f\\u0915\\u0924\\u094d\\u0930 \\u0906\\u0923\\u0942\\u0928 \\u090f\\u0915\\u0938\\u0902\\u0918 \\u0926\\u0947\\u0936 \\u0928\\u093f\\u0930\\u094d\\u092e\\u093e\\u0923 \\u0915\\u0930\\u0923\\u094d\\u092f\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0924\\u094d\\u092f\\u093e\\u0902\\u0928\\u0940 \\u092e\\u094b\\u0932\\u093e\\u091a\\u0940 \\u092d\\u0942\\u092e\\u093f\\u0915\\u093e \\u092c\\u091c\\u093e\\u0935\\u0932\\u0940, \\u092e\\u094d\\u0939\\u0923\\u0942\\u0928 \\u0924\\u094d\\u092f\\u093e\\u0902\\u0928\\u093e \\u2018\\u0932\\u094c\\u0939\\u092a\\u0941\\u0930\\u0941\\u0937\\u2019 \\u092e\\u094d\\u0939\\u091f\\u0932\\u0947 \\u091c\\u093e\\u0924\\u0947.\"},{\"q\":\"Describe the political positions held by Sardar Vallabhbhai Patel after independence.\",\"a\":\"He became the first Deputy Prime Minister and Home Minister of independent India.\",\"e\":\"\\u0938\\u094d\\u0935\\u0924\\u0902\\u0924\\u094d\\u0930 \\u092d\\u093e\\u0930\\u0924\\u093e\\u091a\\u0947 \\u092a\\u0939\\u093f\\u0932\\u0947 \\u0909\\u092a\\u092a\\u0902\\u0924\\u092a\\u094d\\u0930\\u0927\\u093e\\u0928 \\u0906\\u0923\\u093f \\u0917\\u0943\\u0939\\u092e\\u0902\\u0924\\u094d\\u0930\\u0940 \\u092e\\u094d\\u0939\\u0923\\u0942\\u0928 \\u0938\\u0930\\u0926\\u093e\\u0930 \\u092a\\u091f\\u0947\\u0932 \\u092f\\u093e\\u0902\\u0928\\u0940 \\u0915\\u093e\\u092e \\u0915\\u0947\\u0932\\u0947.\"},{\"q\":\"Explain the importance of the Statue of Unity.\",\"a\":\"The Statue of Unity was built to honour Sardar Vallabhbhai Patel and his contribution to India.\",\"e\":\"\\u0938\\u0930\\u0926\\u093e\\u0930 \\u0935\\u0932\\u094d\\u0932\\u092d\\u092d\\u093e\\u0908 \\u092a\\u091f\\u0947\\u0932 \\u092f\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u0915\\u093e\\u0930\\u094d\\u092f\\u093e\\u091a\\u093e \\u0917\\u094c\\u0930\\u0935 \\u0915\\u0930\\u0923\\u094d\\u092f\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0917\\u0941\\u091c\\u0930\\u093e\\u0924\\u092e\\u0927\\u0940\\u0932 \\u0915\\u0947\\u0935\\u0921\\u093f\\u092f\\u093e \\u092f\\u0947\\u0925\\u0947 \\u2018\\u0938\\u094d\\u091f\\u0945\\u091a\\u094d\\u092f\\u0942 \\u0911\\u092b \\u092f\\u0941\\u0928\\u093f\\u091f\\u0940\\u2019 \\u0909\\u092d\\u093e\\u0930\\u0923\\u094d\\u092f\\u093e\\u0924 \\u0906\\u0932\\u0940 \\u0906\\u0939\\u0947.\"},{\"q\":\"How did the ideals of Mahatma Gandhi influence other national leaders?\",\"a\":\"Gandhi\\u2019s principles inspired leaders like Nehru and Patel to serve the nation selflessly.\",\"e\":\"\\u092e\\u0939\\u093e\\u0924\\u094d\\u092e\\u093e \\u0917\\u093e\\u0902\\u0927\\u0940\\u0902\\u091a\\u094d\\u092f\\u093e \\u0935\\u093f\\u091a\\u093e\\u0930\\u093e\\u0902\\u0928\\u0940 \\u0928\\u0947\\u0939\\u0930\\u0942 \\u0906\\u0923\\u093f \\u092a\\u091f\\u0947\\u0932 \\u092f\\u093e\\u0902\\u0938\\u093e\\u0930\\u0916\\u094d\\u092f\\u093e \\u0928\\u0947\\u0924\\u094d\\u092f\\u093e\\u0902\\u0928\\u093e \\u0926\\u0947\\u0936\\u0938\\u0947\\u0935\\u0947\\u0938\\u093e\\u0920\\u0940 \\u092a\\u094d\\u0930\\u0947\\u0930\\u0923\\u093e \\u0926\\u093f\\u0932\\u0940.\"},{\"q\":\"Summarise the collective contribution of these great leaders to India.\",\"a\":\"Gandhi, Nehru, and Patel contributed immensely to India\\u2019s freedom, unity, and development.\",\"e\":\"\\u092e\\u0939\\u093e\\u0924\\u094d\\u092e\\u093e \\u0917\\u093e\\u0902\\u0927\\u0940, \\u092a\\u0902\\u0921\\u093f\\u0924 \\u0928\\u0947\\u0939\\u0930\\u0942 \\u0906\\u0923\\u093f \\u0938\\u0930\\u0926\\u093e\\u0930 \\u092a\\u091f\\u0947\\u0932 \\u092f\\u093e\\u0902\\u0928\\u0940 \\u092d\\u093e\\u0930\\u0924\\u093e\\u091a\\u094d\\u092f\\u093e \\u0938\\u094d\\u0935\\u093e\\u0924\\u0902\\u0924\\u094d\\u0930\\u094d\\u092f, \\u090f\\u0915\\u0924\\u093e \\u0906\\u0923\\u093f \\u0935\\u093f\\u0915\\u093e\\u0938\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0905\\u092e\\u0942\\u0932\\u094d\\u092f \\u092f\\u094b\\u0917\\u0926\\u093e\\u0928 \\u0926\\u093f\\u0932\\u0947.\"}]','OUR GREAT LEADERS','2026-01-16 12:04:50'),(27,81,'TRANSPORT AND COMMUNICATION','[{\"q\":\"\\ufeffQuestion\",\"a\":\"Answer\",\"e\":\"Explaination in Marathi language\"},{\"q\":\"Explain what is meant by means of transport and why they are important in daily life.\",\"a\":\"Means of transport are vehicles used to travel from one place to another and they help people and goods move easily.\",\"e\":\"\\u0935\\u093e\\u0939\\u0924\\u0941\\u0915\\u0940\\u091a\\u0940 \\u0938\\u093e\\u0927\\u0928\\u0947 \\u092e\\u094d\\u0939\\u0923\\u091c\\u0947 \\u090f\\u0915\\u093e \\u0920\\u093f\\u0915\\u093e\\u0923\\u093e\\u0939\\u0942\\u0928 \\u0926\\u0941\\u0938\\u0931\\u094d\\u092f\\u093e \\u0920\\u093f\\u0915\\u093e\\u0923\\u0940 \\u091c\\u093e\\u0923\\u094d\\u092f\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0935\\u093e\\u092a\\u0930\\u0932\\u0940 \\u091c\\u093e\\u0923\\u093e\\u0930\\u0940 \\u0935\\u093e\\u0939\\u0928\\u0947 \\u0939\\u094b\\u0924. \\u0932\\u094b\\u0915\\u093e\\u0902\\u091a\\u0940 \\u0935 \\u0935\\u0938\\u094d\\u0924\\u0942\\u0902\\u091a\\u0940 \\u0939\\u093e\\u0932\\u091a\\u093e\\u0932 \\u0938\\u0941\\u0932\\u092d \\u0915\\u0930\\u0923\\u094d\\u092f\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0939\\u0940 \\u0938\\u093e\\u0927\\u0928\\u0947 \\u092e\\u0939\\u0924\\u094d\\u0924\\u094d\\u0935\\u093e\\u091a\\u0940 \\u0906\\u0939\\u0947\\u0924.\"},{\"q\":\"Describe land transport and explain its different forms.\",\"a\":\"Land transport includes vehicles that move on land and has two forms: road transport and rail transport.\",\"e\":\"\\u092d\\u0942\\u092e\\u0940 \\u0935\\u093e\\u0939\\u0924\\u0942\\u0915 \\u092e\\u094d\\u0939\\u0923\\u091c\\u0947 \\u091c\\u092e\\u093f\\u0928\\u0940\\u0935\\u0930 \\u091a\\u093e\\u0932\\u0923\\u093e\\u0930\\u0940 \\u0935\\u093e\\u0939\\u0928\\u0947. \\u0930\\u0938\\u094d\\u0924\\u0947 \\u0935\\u093e\\u0939\\u0924\\u0942\\u0915 \\u0935 \\u0930\\u0947\\u0932\\u094d\\u0935\\u0947 \\u0935\\u093e\\u0939\\u0924\\u0942\\u0915 \\u0939\\u0947 \\u092d\\u0942\\u092e\\u0940 \\u0935\\u093e\\u0939\\u0924\\u0941\\u0915\\u0940\\u091a\\u0947 \\u0926\\u094b\\u0928 \\u092a\\u094d\\u0930\\u0915\\u093e\\u0930 \\u0906\\u0939\\u0947\\u0924.\"},{\"q\":\"Explain the importance of road transport in daily life.\",\"a\":\"Road transport is commonly used for short distances and for carrying people and goods within cities and villages.\",\"e\":\"\\u0930\\u0938\\u094d\\u0924\\u0947 \\u0935\\u093e\\u0939\\u0924\\u0942\\u0915 \\u0939\\u0940 \\u0926\\u0948\\u0928\\u0902\\u0926\\u093f\\u0928 \\u091c\\u0940\\u0935\\u0928\\u093e\\u0924 \\u0938\\u0930\\u094d\\u0935\\u093e\\u0927\\u093f\\u0915 \\u0935\\u093e\\u092a\\u0930\\u0932\\u0940 \\u091c\\u093e\\u0923\\u093e\\u0930\\u0940 \\u0935\\u093e\\u0939\\u0924\\u0942\\u0915 \\u0906\\u0939\\u0947. \\u0905\\u0932\\u094d\\u092a \\u0905\\u0902\\u0924\\u0930\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0924\\u0938\\u0947\\u091a \\u0917\\u093e\\u0935\\u0947 \\u0935 \\u0936\\u0939\\u0930\\u093e\\u0902\\u0924 \\u0938\\u093e\\u092e\\u093e\\u0928 \\u0935 \\u0932\\u094b\\u0915\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u0935\\u093e\\u0939\\u0924\\u0941\\u0915\\u0940\\u0938\\u093e\\u0920\\u0940 \\u0924\\u0940 \\u092e\\u0939\\u0924\\u094d\\u0924\\u094d\\u0935\\u093e\\u091a\\u0940 \\u0906\\u0939\\u0947.\"},{\"q\":\"Describe the role of rail transport in a country.\",\"a\":\"Rail transport is used to travel long distances and to transport goods across different regions.\",\"e\":\"\\u0930\\u0947\\u0932\\u094d\\u0935\\u0947 \\u0935\\u093e\\u0939\\u0924\\u0942\\u0915 \\u0932\\u093e\\u0902\\u092c \\u0905\\u0902\\u0924\\u0930\\u093e\\u091a\\u094d\\u092f\\u093e \\u092a\\u094d\\u0930\\u0935\\u093e\\u0938\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0924\\u0938\\u0947\\u091a \\u092e\\u094b\\u0920\\u094d\\u092f\\u093e \\u092a\\u094d\\u0930\\u092e\\u093e\\u0923\\u093e\\u0935\\u0930 \\u092e\\u093e\\u0932\\u0935\\u093e\\u0939\\u0924\\u0941\\u0915\\u0940\\u0938\\u093e\\u0920\\u0940 \\u0909\\u092a\\u092f\\u094b\\u0917\\u0940 \\u0920\\u0930\\u0924\\u0947.\"},{\"q\":\"Explain why land transport is considered the cheapest means of transport.\",\"a\":\"Land transport requires less cost compared to air and water transport and is easily available.\",\"e\":\"\\u0907\\u0924\\u0930 \\u0935\\u093e\\u0939\\u0924\\u0941\\u0915\\u0940\\u091a\\u094d\\u092f\\u093e \\u0938\\u093e\\u0927\\u0928\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u0924\\u0941\\u0932\\u0928\\u0947\\u0924 \\u092d\\u0942\\u092e\\u0940 \\u0935\\u093e\\u0939\\u0924\\u0942\\u0915 \\u0915\\u092e\\u0940 \\u0916\\u0930\\u094d\\u091a\\u093f\\u0915 \\u0935 \\u0938\\u0930\\u094d\\u0935\\u0938\\u0941\\u0932\\u092d \\u0905\\u0938\\u0932\\u094d\\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0924\\u0940 \\u0938\\u0930\\u094d\\u0935\\u093e\\u0924 \\u0938\\u094d\\u0935\\u0938\\u094d\\u0924 \\u092e\\u093e\\u0928\\u0932\\u0940 \\u091c\\u093e\\u0924\\u0947.\"},{\"q\":\"Describe water transport and its uses.\",\"a\":\"Water transport includes boats, ships, and steamers used for travelling and carrying goods over water.\",\"e\":\"\\u092a\\u093e\\u0923\\u094d\\u092f\\u093e\\u0935\\u0930\\u0942\\u0928 \\u092a\\u094d\\u0930\\u0935\\u093e\\u0938\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0935 \\u092e\\u093e\\u0932\\u0935\\u093e\\u0939\\u0924\\u0941\\u0915\\u0940\\u0938\\u093e\\u0920\\u0940 \\u0935\\u093e\\u092a\\u0930\\u0932\\u0940 \\u091c\\u093e\\u0923\\u093e\\u0930\\u0940 \\u0935\\u093e\\u0939\\u0928\\u0947 \\u092e\\u094d\\u0939\\u0923\\u091c\\u0947 \\u091c\\u0932\\u0935\\u093e\\u0939\\u0924\\u0942\\u0915. \\u0928\\u094c\\u0915\\u093e, \\u091c\\u0939\\u093e\\u091c\\u0947 \\u0935 \\u0938\\u094d\\u091f\\u0940\\u092e\\u0930 \\u0939\\u0940 \\u0924\\u094d\\u092f\\u093e\\u091a\\u0940 \\u0909\\u0926\\u093e\\u0939\\u0930\\u0923\\u0947 \\u0906\\u0939\\u0947\\u0924.\"},{\"q\":\"Explain the importance of water transport in international trade.\",\"a\":\"Water transport allows heavy goods to be carried over long distances between countries.\",\"e\":\"\\u091c\\u0932\\u0935\\u093e\\u0939\\u0924\\u0941\\u0915\\u0940\\u092e\\u0941\\u0933\\u0947 \\u092e\\u094b\\u0920\\u094d\\u092f\\u093e \\u092a\\u094d\\u0930\\u092e\\u093e\\u0923\\u093e\\u0924 \\u0935 \\u091c\\u0921 \\u092e\\u093e\\u0932 \\u090f\\u0915\\u093e \\u0926\\u0947\\u0936\\u093e\\u0924\\u0942\\u0928 \\u0926\\u0941\\u0938\\u0931\\u094d\\u092f\\u093e \\u0926\\u0947\\u0936\\u093e\\u0924 \\u0915\\u092e\\u0940 \\u0916\\u0930\\u094d\\u091a\\u093e\\u0924 \\u0928\\u0947\\u0932\\u093e \\u091c\\u093e\\u090a \\u0936\\u0915\\u0924\\u094b, \\u0924\\u094d\\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0906\\u0902\\u0924\\u0930\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u0940\\u092f \\u0935\\u094d\\u092f\\u093e\\u092a\\u093e\\u0930 \\u0938\\u0941\\u0932\\u092d \\u0939\\u094b\\u0924\\u094b.\"},{\"q\":\"Describe air transport and explain why it is fast.\",\"a\":\"Air transport uses aeroplanes and helicopters and is the fastest means of transport.\",\"e\":\"\\u0939\\u0935\\u093e\\u0908 \\u0935\\u093e\\u0939\\u0924\\u0942\\u0915 \\u0935\\u093f\\u092e\\u093e\\u0928 \\u0935 \\u0939\\u0947\\u0932\\u093f\\u0915\\u0949\\u092a\\u094d\\u091f\\u0930\\u0926\\u094d\\u0935\\u093e\\u0930\\u0947 \\u0915\\u0947\\u0932\\u0940 \\u091c\\u093e\\u0924\\u0947. \\u0924\\u0940 \\u0938\\u0930\\u094d\\u0935\\u093e\\u0924 \\u091c\\u0932\\u0926 \\u0935\\u093e\\u0939\\u0924\\u0942\\u0915 \\u0905\\u0938\\u0932\\u094d\\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0935\\u0947\\u0933\\u0947\\u091a\\u0940 \\u092c\\u091a\\u0924 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Explain why air transport is the most expensive means of transport.\",\"a\":\"Air transport requires high fuel, advanced technology, and maintenance, making it costly.\",\"e\":\"\\u0939\\u0935\\u093e\\u0908 \\u0935\\u093e\\u0939\\u0924\\u0941\\u0915\\u0940\\u0938\\u093e\\u0920\\u0940 \\u092e\\u0939\\u093e\\u0917 \\u0907\\u0902\\u0927\\u0928, \\u092a\\u094d\\u0930\\u0917\\u0924 \\u0924\\u0902\\u0924\\u094d\\u0930\\u091c\\u094d\\u091e\\u093e\\u0928 \\u0935 \\u0926\\u0947\\u0916\\u092d\\u093e\\u0932 \\u0906\\u0935\\u0936\\u094d\\u092f\\u0915 \\u0905\\u0938\\u0932\\u094d\\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0924\\u0940 \\u0938\\u0930\\u094d\\u0935\\u093e\\u0924 \\u092e\\u0939\\u093e\\u0917 \\u0935\\u093e\\u0939\\u0924\\u0942\\u0915 \\u092e\\u093e\\u0928\\u0932\\u0940 \\u091c\\u093e\\u0924\\u0947.\"},{\"q\":\"Explain the meaning of communication.\",\"a\":\"Communication means sharing or exchanging thoughts and feelings with others.\",\"e\":\"\\u0938\\u0902\\u0935\\u093e\\u0926 \\u092e\\u094d\\u0939\\u0923\\u091c\\u0947 \\u0906\\u092a\\u0932\\u0947 \\u0935\\u093f\\u091a\\u093e\\u0930, \\u092d\\u093e\\u0935\\u0928\\u093e \\u0935 \\u092e\\u093e\\u0939\\u093f\\u0924\\u0940 \\u0907\\u0924\\u0930\\u093e\\u0902\\u0936\\u0940 \\u0935\\u093e\\u091f\\u0942\\u0928 \\u0918\\u0947\\u0923\\u0947 \\u0915\\u093f\\u0902\\u0935\\u093e \\u0926\\u0947\\u0935\\u093e\\u0923\\u0918\\u0947\\u0935\\u093e\\u0923 \\u0915\\u0930\\u0923\\u0947 \\u0939\\u094b\\u092f.\"},{\"q\":\"Describe how communication developed from early times to modern days.\",\"a\":\"Communication developed from gestures and signals to writing, postal services, and digital media.\",\"e\":\"\\u092a\\u094d\\u0930\\u093e\\u091a\\u0940\\u0928 \\u0915\\u093e\\u0933\\u093e\\u0924 \\u0938\\u0902\\u0915\\u0947\\u0924 \\u0935 \\u0939\\u093e\\u0935\\u092d\\u093e\\u0935\\u093e\\u0902\\u0926\\u094d\\u0935\\u093e\\u0930\\u0947 \\u0938\\u0902\\u0935\\u093e\\u0926 \\u0938\\u093e\\u0927\\u0932\\u093e \\u091c\\u093e\\u0924 \\u0905\\u0938\\u0947. \\u0928\\u0902\\u0924\\u0930 \\u0932\\u0947\\u0916\\u0928, \\u091f\\u092a\\u093e\\u0932 \\u0938\\u0947\\u0935\\u093e \\u0906\\u0923\\u093f \\u0906\\u0927\\u0941\\u0928\\u093f\\u0915 \\u0915\\u093e\\u0933\\u093e\\u0924 \\u0921\\u093f\\u091c\\u093f\\u091f\\u0932 \\u092e\\u093e\\u0927\\u094d\\u092f\\u092e\\u093e\\u0902\\u091a\\u093e \\u0935\\u093e\\u092a\\u0930 \\u0939\\u094b\\u090a \\u0932\\u093e\\u0917\\u0932\\u093e.\"},{\"q\":\"Explain personal communication with examples.\",\"a\":\"Personal communication is communication with one or a few people, such as letters, phones, and emails.\",\"e\":\"\\u090f\\u0915\\u093e \\u0915\\u093f\\u0902\\u0935\\u093e \\u0915\\u093e\\u0939\\u0940 \\u0932\\u094b\\u0915\\u093e\\u0902\\u0936\\u0940 \\u0939\\u094b\\u0923\\u093e\\u0930\\u093e \\u0938\\u0902\\u0935\\u093e\\u0926 \\u092e\\u094d\\u0939\\u0923\\u091c\\u0947 \\u0935\\u0948\\u092f\\u0915\\u094d\\u0924\\u093f\\u0915 \\u0938\\u0902\\u0935\\u093e\\u0926. \\u092a\\u0924\\u094d\\u0930, \\u0926\\u0942\\u0930\\u0927\\u094d\\u0935\\u0928\\u0940, \\u092e\\u094b\\u092c\\u093e\\u0908\\u0932 \\u0935 \\u0908-\\u092e\\u0947\\u0932 \\u0939\\u0940 \\u0924\\u094d\\u092f\\u093e\\u091a\\u0940 \\u0909\\u0926\\u093e\\u0939\\u0930\\u0923\\u0947 \\u0906\\u0939\\u0947\\u0924.\"},{\"q\":\"Describe the role of the postal service as a means of communication.\",\"a\":\"The postal service is the oldest means of communication used to send letters and parcels.\",\"e\":\"\\u091f\\u092a\\u093e\\u0932 \\u0938\\u0947\\u0935\\u093e \\u0939\\u0940 \\u0938\\u0902\\u0935\\u093e\\u0926\\u093e\\u091a\\u0940 \\u0938\\u0930\\u094d\\u0935\\u093e\\u0924 \\u091c\\u0941\\u0928\\u0940 \\u092a\\u0926\\u094d\\u0927\\u0924 \\u0905\\u0938\\u0942\\u0928 \\u092a\\u0924\\u094d\\u0930\\u0947, \\u092a\\u093e\\u0930\\u094d\\u0938\\u0932 \\u0935 \\u092a\\u0948\\u0938\\u0947 \\u092a\\u093e\\u0920\\u0935\\u0923\\u094d\\u092f\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0924\\u0940 \\u0935\\u093e\\u092a\\u0930\\u0932\\u0940 \\u091c\\u093e\\u0924\\u0947.\"},{\"q\":\"Explain mass communication and its importance.\",\"a\":\"Mass communication is communication with a large number of people at the same time.\",\"e\":\"\\u090f\\u0915\\u093e\\u091a \\u0935\\u0947\\u0933\\u0940 \\u092e\\u094b\\u0920\\u094d\\u092f\\u093e \\u092a\\u094d\\u0930\\u092e\\u093e\\u0923\\u093e\\u0935\\u0930 \\u0932\\u094b\\u0915\\u093e\\u0902\\u092a\\u0930\\u094d\\u092f\\u0902\\u0924 \\u092a\\u094b\\u0939\\u094b\\u091a\\u0923\\u093e\\u0930\\u093e \\u0938\\u0902\\u0935\\u093e\\u0926 \\u092e\\u094d\\u0939\\u0923\\u091c\\u0947 \\u091c\\u0928\\u0938\\u0902\\u0935\\u093e\\u0926 \\u0939\\u094b\\u092f.\"},{\"q\":\"Describe the different means of mass communication.\",\"a\":\"Newspapers, magazines, radio, cinema, and television are means of mass communication.\",\"e\":\"\\u0935\\u0943\\u0924\\u094d\\u0924\\u092a\\u0924\\u094d\\u0930\\u0947, \\u092e\\u093e\\u0938\\u093f\\u0915\\u0947, \\u0930\\u0947\\u0921\\u093f\\u0913, \\u091a\\u093f\\u0924\\u094d\\u0930\\u092a\\u091f \\u0906\\u0923\\u093f \\u0926\\u0942\\u0930\\u0926\\u0930\\u094d\\u0936\\u0928 \\u0939\\u0940 \\u091c\\u0928\\u0938\\u0902\\u0935\\u093e\\u0926\\u093e\\u091a\\u0940 \\u092a\\u094d\\u0930\\u092e\\u0941\\u0916 \\u0938\\u093e\\u0927\\u0928\\u0947 \\u0906\\u0939\\u0947\\u0924.\"}]','TRANSPORT AND COMMUNICATION','2026-01-16 12:07:08'),(28,82,'DIFFERENT OCCUPATIONS','[{\"q\":\"\\ufeffQuestion\",\"a\":\"Answer\",\"e\":\"Explaination in Marathi language\"},{\"q\":\"Explain the meaning of occupation and why people choose different occupations.\",\"a\":\"An occupation is any work done to earn money. People choose different occupations based on their skills, education, and interests.\",\"e\":\"\\u0909\\u092a\\u091c\\u0940\\u0935\\u093f\\u0915\\u0947\\u0938\\u093e\\u0920\\u0940 \\u0915\\u0947\\u0932\\u0947\\u0932\\u0947 \\u0915\\u094b\\u0923\\u0924\\u0947\\u0939\\u0940 \\u0915\\u093e\\u092e \\u092e\\u094d\\u0939\\u0923\\u091c\\u0947 \\u0935\\u094d\\u092f\\u0935\\u0938\\u093e\\u092f \\u0939\\u094b\\u092f. \\u0932\\u094b\\u0915 \\u0906\\u092a\\u0932\\u0947 \\u0936\\u093f\\u0915\\u094d\\u0937\\u0923, \\u0915\\u094c\\u0936\\u0932\\u094d\\u092f\\u0947 \\u0906\\u0923\\u093f \\u0906\\u0935\\u0921\\u0940\\u0928\\u0941\\u0938\\u093e\\u0930 \\u0935\\u0947\\u0917\\u0935\\u0947\\u0917\\u0933\\u0947 \\u0935\\u094d\\u092f\\u0935\\u0938\\u093e\\u092f \\u0928\\u093f\\u0935\\u0921\\u0924\\u093e\\u0924.\"},{\"q\":\"Describe farming as an important occupation in India.\",\"a\":\"Farming involves growing crops and rearing animals and is the main occupation of many people living in villages.\",\"e\":\"\\u0936\\u0947\\u0924\\u0940\\u092e\\u0927\\u094d\\u092f\\u0947 \\u092a\\u093f\\u0915\\u0947 \\u092a\\u093f\\u0915\\u0935\\u0923\\u0947 \\u0935 \\u092a\\u094d\\u0930\\u093e\\u0923\\u0940 \\u092a\\u093e\\u0933\\u0923\\u0947 \\u092f\\u093e \\u0915\\u094d\\u0930\\u093f\\u092f\\u093e \\u092f\\u0947\\u0924\\u093e\\u0924. \\u092d\\u093e\\u0930\\u0924\\u093e\\u0924\\u0940\\u0932 \\u0905\\u0928\\u0947\\u0915 \\u0917\\u093e\\u0935\\u093e\\u0902\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0936\\u0947\\u0924\\u0940 \\u0939\\u093e \\u092e\\u0941\\u0916\\u094d\\u092f \\u0935\\u094d\\u092f\\u0935\\u0938\\u093e\\u092f \\u0906\\u0939\\u0947.\"},{\"q\":\"Explain the different crops grown through farming in India.\",\"a\":\"Farmers grow crops like wheat, rice, sugarcane, tea, coffee, fruits, and vegetables.\",\"e\":\"\\u092d\\u093e\\u0930\\u0924\\u093e\\u0924\\u0940\\u0932 \\u0936\\u0947\\u0924\\u0915\\u0930\\u0940 \\u0917\\u0939\\u0942, \\u0924\\u093e\\u0902\\u0926\\u0942\\u0933, \\u090a\\u0938, \\u091a\\u0939\\u093e, \\u0915\\u0949\\u092b\\u0940 \\u0924\\u0938\\u0947\\u091a \\u092b\\u0933\\u0947 \\u0935 \\u092d\\u093e\\u091c\\u0940\\u092a\\u093e\\u0932\\u093e \\u0905\\u0936\\u0940 \\u0935\\u093f\\u0935\\u093f\\u0927 \\u092a\\u093f\\u0915\\u0947 \\u0918\\u0947\\u0924\\u093e\\u0924.\"},{\"q\":\"Describe dairy farming and its importance.\",\"a\":\"Dairy farming involves rearing animals like cows and buffaloes for milk, meat, and other products.\",\"e\":\"\\u0926\\u0941\\u0917\\u094d\\u0927\\u0935\\u094d\\u092f\\u0935\\u0938\\u093e\\u092f\\u093e\\u0924 \\u0917\\u093e\\u092f\\u0940, \\u092e\\u094d\\u0939\\u0936\\u0940, \\u0936\\u0947\\u0933\\u094d\\u092f\\u093e \\u0907\\u0924\\u094d\\u092f\\u093e\\u0926\\u0940 \\u092a\\u094d\\u0930\\u093e\\u0923\\u0940 \\u092a\\u093e\\u0933\\u0942\\u0928 \\u0926\\u0942\\u0927, \\u092e\\u093e\\u0902\\u0938 \\u0935 \\u0907\\u0924\\u0930 \\u0909\\u0924\\u094d\\u092a\\u093e\\u0926\\u0928\\u0947 \\u092e\\u093f\\u0933\\u0935\\u0932\\u0940 \\u091c\\u093e\\u0924\\u093e\\u0924.\"},{\"q\":\"Explain poultry farming as an occupation.\",\"a\":\"Poultry farming involves rearing birds like hens and ducks to produce eggs and meat.\",\"e\":\"\\u0915\\u0941\\u0915\\u094d\\u0915\\u0941\\u091f\\u092a\\u093e\\u0932\\u0928\\u093e\\u0924 \\u0915\\u094b\\u0902\\u092c\\u0921\\u094d\\u092f\\u093e, \\u092c\\u0926\\u0915\\u0947 \\u0907\\u0924\\u094d\\u092f\\u093e\\u0926\\u0940 \\u092a\\u0915\\u094d\\u0937\\u0940 \\u092a\\u093e\\u0933\\u0942\\u0928 \\u0905\\u0902\\u0921\\u0940 \\u0935 \\u092e\\u093e\\u0902\\u0938 \\u0909\\u0924\\u094d\\u092a\\u093e\\u0926\\u0928 \\u0915\\u0947\\u0932\\u0947 \\u091c\\u093e\\u0924\\u0947.\"},{\"q\":\"Describe fishing as an occupation practised in India.\",\"a\":\"Fishing is the occupation of catching fish and is common in coastal areas and near water bodies.\",\"e\":\"\\u092e\\u093e\\u0938\\u0947\\u092e\\u093e\\u0930\\u0940 \\u092e\\u094d\\u0939\\u0923\\u091c\\u0947 \\u092e\\u093e\\u0938\\u0947 \\u092a\\u0915\\u0921\\u0923\\u094d\\u092f\\u093e\\u091a\\u093e \\u0935\\u094d\\u092f\\u0935\\u0938\\u093e\\u092f \\u0939\\u094b\\u092f. \\u0924\\u094b \\u092a\\u094d\\u0930\\u093e\\u092e\\u0941\\u0916\\u094d\\u092f\\u093e\\u0928\\u0947 \\u0915\\u093f\\u0928\\u093e\\u0930\\u0940 \\u092d\\u093e\\u0917\\u093e\\u0924 \\u0924\\u0938\\u0947\\u091a \\u0928\\u0926\\u094d\\u092f\\u093e, \\u0924\\u0932\\u093e\\u0935\\u093e\\u0902\\u091c\\u0935\\u0933 \\u0915\\u0947\\u0932\\u093e \\u091c\\u093e\\u0924\\u094b.\"},{\"q\":\"Explain the importance of fishing for food and trade.\",\"a\":\"Fishing provides an important source of food and helps in earning money through exports.\",\"e\":\"\\u092e\\u093e\\u0938\\u0947 \\u0939\\u0947 \\u0905\\u0928\\u094d\\u0928\\u093e\\u091a\\u0947 \\u092e\\u0939\\u0924\\u094d\\u0924\\u094d\\u0935\\u093e\\u091a\\u0947 \\u0938\\u094d\\u0930\\u094b\\u0924 \\u0906\\u0939\\u0947\\u0924 \\u0924\\u0938\\u0947\\u091a \\u092e\\u093e\\u0938\\u0947\\u092e\\u093e\\u0930\\u0940\\u092e\\u0941\\u0933\\u0947 \\u0928\\u093f\\u0930\\u094d\\u092f\\u093e\\u0924\\u0940\\u0926\\u094d\\u0935\\u093e\\u0930\\u0947 \\u0909\\u0924\\u094d\\u092a\\u0928\\u094d\\u0928 \\u092e\\u093f\\u0933\\u0924\\u0947.\"},{\"q\":\"Describe forestry and the activities involved in it.\",\"a\":\"Forestry involves collecting wood, gum, honey, rubber, and herbs from forests.\",\"e\":\"\\u0935\\u0928\\u0935\\u094d\\u092f\\u0935\\u0938\\u093e\\u092f\\u093e\\u0924 \\u091c\\u0902\\u0917\\u0932\\u093e\\u0924\\u0942\\u0928 \\u0932\\u093e\\u0915\\u0942\\u0921, \\u0917\\u094b\\u0902\\u0926, \\u092e\\u0927, \\u0930\\u092c\\u0930 \\u0935 \\u0914\\u0937\\u0927\\u0940 \\u0935\\u0928\\u0938\\u094d\\u092a\\u0924\\u0940 \\u0917\\u094b\\u0933\\u093e \\u0915\\u0947\\u0932\\u094d\\u092f\\u093e \\u091c\\u093e\\u0924\\u093e\\u0924.\"},{\"q\":\"Explain why forestry is important for people living near forests.\",\"a\":\"Forestry helps people living near forests earn their livelihood.\",\"e\":\"\\u091c\\u0902\\u0917\\u0932\\u093e\\u091c\\u0935\\u0933 \\u0930\\u093e\\u0939\\u0923\\u093e\\u0931\\u094d\\u092f\\u093e \\u0932\\u094b\\u0915\\u093e\\u0902\\u0938\\u093e\\u0920\\u0940 \\u0935\\u0928\\u0935\\u094d\\u092f\\u0935\\u0938\\u093e\\u092f \\u0939\\u093e \\u0909\\u092a\\u091c\\u0940\\u0935\\u093f\\u0915\\u0947\\u091a\\u093e \\u092e\\u0939\\u0924\\u094d\\u0924\\u094d\\u0935\\u093e\\u091a\\u093e \\u0938\\u094d\\u0930\\u094b\\u0924 \\u0906\\u0939\\u0947.\"},{\"q\":\"Describe mining as an occupation.\",\"a\":\"Mining is the process of digging minerals like coal, iron, and copper from the ground.\",\"e\":\"\\u0916\\u0928\\u093f\\u091c\\u0947 \\u091c\\u092e\\u093f\\u0928\\u0940\\u0924\\u0942\\u0928 \\u0916\\u094b\\u0926\\u0942\\u0928 \\u0915\\u093e\\u0922\\u0923\\u094d\\u092f\\u093e\\u091a\\u094d\\u092f\\u093e \\u092a\\u094d\\u0930\\u0915\\u094d\\u0930\\u093f\\u092f\\u0947\\u0932\\u093e \\u0916\\u093e\\u0923\\u0915\\u093e\\u092e \\u0915\\u093f\\u0902\\u0935\\u093e \\u0916\\u0928\\u0928 \\u0905\\u0938\\u0947 \\u092e\\u094d\\u0939\\u0923\\u0924\\u093e\\u0924.\"},{\"q\":\"Explain the importance of mining in industrial development.\",\"a\":\"Mining provides raw materials needed to make machines, vehicles, and other products.\",\"e\":\"\\u0916\\u0928\\u0928\\u093e\\u0924\\u0942\\u0928 \\u092e\\u093f\\u0933\\u0923\\u093e\\u0930\\u0940 \\u0916\\u0928\\u093f\\u091c\\u0947 \\u0909\\u0926\\u094d\\u092f\\u094b\\u0917\\u093e\\u0902\\u0938\\u093e\\u0920\\u0940 \\u0915\\u091a\\u094d\\u091a\\u093e \\u092e\\u093e\\u0932 \\u092a\\u0941\\u0930\\u0935\\u0924\\u093e\\u0924, \\u091c\\u094d\\u092f\\u093e\\u0924\\u0942\\u0928 \\u092f\\u0902\\u0924\\u094d\\u0930\\u0947 \\u0935 \\u0907\\u0924\\u0930 \\u0935\\u0938\\u094d\\u0924\\u0942 \\u0924\\u092f\\u093e\\u0930 \\u0939\\u094b\\u0924\\u093e\\u0924.\"},{\"q\":\"Describe the occupations found in cities and towns.\",\"a\":\"People in cities work in offices, factories, shops, hospitals, and run businesses.\",\"e\":\"\\u0936\\u0939\\u0930\\u093e\\u0902\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0932\\u094b\\u0915 \\u0915\\u093e\\u0930\\u094d\\u092f\\u093e\\u0932\\u092f\\u0947, \\u0915\\u093e\\u0930\\u0916\\u093e\\u0928\\u0947, \\u0926\\u0941\\u0915\\u093e\\u0928\\u0947, \\u0930\\u0941\\u0917\\u094d\\u0923\\u093e\\u0932\\u092f\\u0947 \\u092f\\u0947\\u0925\\u0947 \\u0915\\u093e\\u092e \\u0915\\u0930\\u0924\\u093e\\u0924 \\u0924\\u0938\\u0947\\u091a \\u0938\\u094d\\u0935\\u0924\\u0903\\u091a\\u093e \\u0935\\u094d\\u092f\\u0935\\u0938\\u093e\\u092f \\u0915\\u0930\\u0924\\u093e\\u0924.\"},{\"q\":\"Explain the role of factories as workplaces.\",\"a\":\"Factories convert raw materials into useful finished products.\",\"e\":\"\\u0915\\u093e\\u0930\\u0916\\u093e\\u0928\\u094d\\u092f\\u093e\\u0902\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0915\\u091a\\u094d\\u091a\\u093e \\u092e\\u093e\\u0932 \\u092a\\u094d\\u0930\\u0915\\u094d\\u0930\\u093f\\u092f\\u093e \\u0915\\u0930\\u0942\\u0928 \\u0909\\u092a\\u092f\\u0941\\u0915\\u094d\\u0924 \\u0935\\u0938\\u094d\\u0924\\u0942\\u0902\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0930\\u0942\\u092a\\u093e\\u0902\\u0924\\u0930 \\u0915\\u0947\\u0932\\u0947 \\u091c\\u093e\\u0924\\u0947.\"},{\"q\":\"Describe skilled occupations with examples.\",\"a\":\"Skilled occupations involve special skills like carpentry, pottery, jewellery making, and electrician work.\",\"e\":\"\\u0915\\u094c\\u0936\\u0932\\u094d\\u092f\\u093e\\u0927\\u093e\\u0930\\u093f\\u0924 \\u0935\\u094d\\u092f\\u0935\\u0938\\u093e\\u092f\\u093e\\u0902\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0938\\u0941\\u0924\\u093e\\u0930\\u0915\\u093e\\u092e, \\u0915\\u0941\\u0902\\u092d\\u093e\\u0930\\u0915\\u093e\\u092e, \\u0926\\u093e\\u0917\\u093f\\u0928\\u0947\\u0928\\u093f\\u0930\\u094d\\u092e\\u093f\\u0924\\u0940 \\u0935 \\u0935\\u093f\\u091c\\u0924\\u0902\\u0924\\u094d\\u0930\\u0940 \\u0915\\u093e\\u092e \\u092f\\u093e\\u0902\\u091a\\u093e \\u0938\\u092e\\u093e\\u0935\\u0947\\u0936 \\u0939\\u094b\\u0924\\u094b.\"},{\"q\":\"Summarise the importance of different occupations in society.\",\"a\":\"Different occupations help meet the needs of society and support economic development.\",\"e\":\"\\u0935\\u0947\\u0917\\u0935\\u0947\\u0917\\u0933\\u0947 \\u0935\\u094d\\u092f\\u0935\\u0938\\u093e\\u092f \\u0938\\u092e\\u093e\\u091c\\u093e\\u091a\\u094d\\u092f\\u093e \\u0917\\u0930\\u091c\\u093e \\u092a\\u0942\\u0930\\u094d\\u0923 \\u0915\\u0930\\u0924\\u093e\\u0924 \\u0906\\u0923\\u093f \\u0906\\u0930\\u094d\\u0925\\u093f\\u0915 \\u0935\\u093f\\u0915\\u093e\\u0938\\u093e\\u0924 \\u092e\\u0939\\u0924\\u094d\\u0924\\u094d\\u0935\\u093e\\u091a\\u0940 \\u092d\\u0942\\u092e\\u093f\\u0915\\u093e \\u092c\\u091c\\u093e\\u0935\\u0924\\u093e\\u0924.\"}]','DIFFERENT OCCUPATIONS','2026-01-16 12:09:36'),(29,83,'OUR ENVIRONMENT','[{\"q\":\"\\ufeffQuestion\",\"a\":\"Answer\",\"e\":\"Explaination in Marathi language\"},{\"q\":\"Explain what is meant by environment and describe its main components.\",\"a\":\"Environment means everything that surrounds us and includes both living and non-living things.\",\"e\":\"\\u092a\\u0930\\u094d\\u092f\\u093e\\u0935\\u0930\\u0923 \\u092e\\u094d\\u0939\\u0923\\u091c\\u0947 \\u0906\\u092a\\u0932\\u094d\\u092f\\u093e \\u0906\\u091c\\u0942\\u092c\\u093e\\u091c\\u0942\\u091a\\u0940 \\u0938\\u0930\\u094d\\u0935 \\u0938\\u091c\\u0940\\u0935 \\u0935 \\u0928\\u093f\\u0930\\u094d\\u091c\\u0940\\u0935 \\u0918\\u091f\\u0915\\u093e\\u0902\\u091a\\u0940 \\u090f\\u0915\\u0924\\u094d\\u0930\\u093f\\u0924 \\u0930\\u091a\\u0928\\u093e \\u0939\\u094b\\u092f. \\u092e\\u093e\\u0923\\u0938\\u0947, \\u092a\\u094d\\u0930\\u093e\\u0923\\u0940, \\u0935\\u0928\\u0938\\u094d\\u092a\\u0924\\u0940 \\u0924\\u0938\\u0947\\u091a \\u0939\\u0935\\u093e, \\u092a\\u093e\\u0923\\u0940, \\u091c\\u092e\\u0940\\u0928 \\u0939\\u0947 \\u092a\\u0930\\u094d\\u092f\\u093e\\u0935\\u0930\\u0923\\u093e\\u091a\\u0947 \\u0918\\u091f\\u0915 \\u0906\\u0939\\u0947\\u0924.\"},{\"q\":\"Describe the difference between living and non-living things in the environment.\",\"a\":\"Living things grow and breathe, while non-living things do not have life.\",\"e\":\"\\u0938\\u091c\\u0940\\u0935 \\u0935\\u0938\\u094d\\u0924\\u0942\\u0902\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0935\\u093e\\u0922, \\u0936\\u094d\\u0935\\u0938\\u0928 \\u0935 \\u0939\\u093e\\u0932\\u091a\\u093e\\u0932 \\u0905\\u0938\\u0924\\u0947, \\u0924\\u0930 \\u0928\\u093f\\u0930\\u094d\\u091c\\u0940\\u0935 \\u0935\\u0938\\u094d\\u0924\\u0942\\u0902\\u092e\\u0927\\u094d\\u092f\\u0947 \\u091c\\u0940\\u0935\\u0928 \\u0928\\u0938\\u0924\\u0947.\"},{\"q\":\"Explain the meaning of pollution and its impact on the environment.\",\"a\":\"Pollution is the dirtying of the environment by harmful substances called pollutants.\",\"e\":\"\\u0939\\u093e\\u0928\\u0940\\u0915\\u093e\\u0930\\u0915 \\u092a\\u0926\\u093e\\u0930\\u094d\\u0925 \\u0935\\u093e\\u0924\\u093e\\u0935\\u0930\\u0923\\u093e\\u0924 \\u092e\\u093f\\u0938\\u0933\\u0932\\u094d\\u092f\\u093e\\u0928\\u0947 \\u092a\\u0930\\u094d\\u092f\\u093e\\u0935\\u0930\\u0923 \\u0926\\u0942\\u0937\\u093f\\u0924 \\u0939\\u094b\\u0924\\u0947, \\u092f\\u093e\\u0932\\u093e\\u091a \\u092a\\u094d\\u0930\\u0926\\u0942\\u0937\\u0923 \\u092e\\u094d\\u0939\\u0923\\u0924\\u093e\\u0924.\"},{\"q\":\"Describe air pollution along with its causes.\",\"a\":\"Air pollution occurs due to smoke from vehicles, factories, burning waste, and firecrackers.\",\"e\":\"\\u0935\\u093e\\u0939\\u0928\\u093e\\u0902\\u091a\\u093e \\u0927\\u0942\\u0930, \\u0915\\u093e\\u0930\\u0916\\u093e\\u0928\\u094d\\u092f\\u093e\\u0902\\u091a\\u093e \\u0927\\u0942\\u0930, \\u0915\\u091a\\u0930\\u093e \\u091c\\u093e\\u0933\\u0923\\u0947 \\u0935 \\u092b\\u091f\\u093e\\u0915\\u0947 \\u092b\\u094b\\u0921\\u0923\\u0947 \\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0935\\u093e\\u092f\\u0942 \\u092a\\u094d\\u0930\\u0926\\u0942\\u0937\\u0923 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Explain the effects of air pollution on human health.\",\"a\":\"Air pollution causes breathing problems, headaches, and allergies.\",\"e\":\"\\u0935\\u093e\\u092f\\u0942 \\u092a\\u094d\\u0930\\u0926\\u0942\\u0937\\u0923\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0936\\u094d\\u0935\\u0938\\u0928\\u093e\\u091a\\u0947 \\u0935\\u093f\\u0915\\u093e\\u0930, \\u0921\\u094b\\u0915\\u0947\\u0926\\u0941\\u0916\\u0940, \\u0921\\u094b\\u0933\\u0947 \\u0935 \\u0928\\u093e\\u0915\\u093e\\u091a\\u0940 \\u091c\\u0933\\u091c\\u0933 \\u0939\\u094b\\u090a \\u0936\\u0915\\u0924\\u0947.\"},{\"q\":\"Describe water pollution and its major causes.\",\"a\":\"Water pollution happens when waste and harmful substances are dumped into water bodies.\",\"e\":\"\\u0928\\u0926\\u094d\\u092f\\u093e, \\u0924\\u0932\\u093e\\u0935 \\u0935 \\u092a\\u093e\\u0923\\u0935\\u0920\\u094d\\u092f\\u093e\\u0924 \\u0915\\u091a\\u0930\\u093e \\u0935 \\u0918\\u093e\\u0924\\u0915 \\u0926\\u094d\\u0930\\u0935\\u094d\\u092f\\u0947 \\u091f\\u093e\\u0915\\u0932\\u094d\\u092f\\u093e\\u0928\\u0947 \\u091c\\u0932\\u092a\\u094d\\u0930\\u0926\\u0942\\u0937\\u0923 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Explain the harmful effects of water pollution.\",\"a\":\"Water pollution causes diseases and harms aquatic plants and animals.\",\"e\":\"\\u091c\\u0932\\u092a\\u094d\\u0930\\u0926\\u0942\\u0937\\u0923\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0905\\u0924\\u093f\\u0938\\u093e\\u0930, \\u0915\\u0949\\u0932\\u0930\\u093e, \\u092a\\u093f\\u0935\\u0933\\u094d\\u092f\\u093e \\u0915\\u093e\\u0935\\u0933\\u0940\\u0938\\u093e\\u0930\\u0916\\u0947 \\u0906\\u091c\\u093e\\u0930 \\u0939\\u094b\\u0924\\u093e\\u0924 \\u0924\\u0938\\u0947\\u091a \\u091c\\u0932\\u091c\\u0940\\u0935\\u093e\\u0902\\u0928\\u093e \\u0928\\u0941\\u0915\\u0938\\u093e\\u0928 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Describe noise pollution and list its causes.\",\"a\":\"Noise pollution is caused by loud sounds from vehicles, machines, and loudspeakers.\",\"e\":\"\\u0905\\u0924\\u093f\\u091c\\u094b\\u0930\\u093e\\u091a\\u093e \\u0906\\u0935\\u093e\\u091c, \\u0935\\u093e\\u0939\\u0928\\u093e\\u0902\\u091a\\u0947 \\u0939\\u0949\\u0930\\u094d\\u0928, \\u092f\\u0902\\u0924\\u094d\\u0930\\u0938\\u093e\\u092e\\u0917\\u094d\\u0930\\u0940 \\u0935 \\u092e\\u094b\\u0920\\u094d\\u092f\\u093e \\u0906\\u0935\\u093e\\u091c\\u093e\\u0924\\u0940\\u0932 \\u0938\\u0902\\u0917\\u0940\\u0924\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0927\\u094d\\u0935\\u0928\\u0940 \\u092a\\u094d\\u0930\\u0926\\u0942\\u0937\\u0923 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Explain the effects of noise pollution on people.\",\"a\":\"Noise pollution causes headache, sleep disturbance, and hearing loss.\",\"e\":\"\\u0927\\u094d\\u0935\\u0928\\u0940 \\u092a\\u094d\\u0930\\u0926\\u0942\\u0937\\u0923\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0921\\u094b\\u0915\\u0947\\u0926\\u0941\\u0916\\u0940, \\u091d\\u094b\\u092a\\u0947\\u091a\\u093e \\u0924\\u094d\\u0930\\u093e\\u0938 \\u0935 \\u0910\\u0915\\u0923\\u094d\\u092f\\u093e\\u091a\\u0940 \\u0915\\u094d\\u0937\\u092e\\u0924\\u093e \\u0915\\u092e\\u0940 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Describe land pollution with suitable examples.\",\"a\":\"Land pollution occurs due to dumping garbage, plastic waste, and chemicals on land.\",\"e\":\"\\u091c\\u092e\\u093f\\u0928\\u0940\\u0935\\u0930 \\u0915\\u091a\\u0930\\u093e, \\u092a\\u094d\\u0932\\u093e\\u0938\\u094d\\u091f\\u093f\\u0915 \\u0935 \\u0930\\u093e\\u0938\\u093e\\u092f\\u0928\\u093f\\u0915 \\u092a\\u0926\\u093e\\u0930\\u094d\\u0925 \\u091f\\u093e\\u0915\\u0932\\u094d\\u092f\\u093e\\u0928\\u0947 \\u092d\\u0942\\u092e\\u0940 \\u092a\\u094d\\u0930\\u0926\\u0942\\u0937\\u0923 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Explain the effects of land pollution on the surroundings.\",\"a\":\"Land pollution causes spread of diseases and spoils natural beauty.\",\"e\":\"\\u092d\\u0942\\u092e\\u0940 \\u092a\\u094d\\u0930\\u0926\\u0942\\u0937\\u0923\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0930\\u094b\\u0917\\u0930\\u093e\\u0908 \\u092a\\u0938\\u0930\\u0924\\u0947 \\u0906\\u0923\\u093f \\u092a\\u0930\\u093f\\u0938\\u0930\\u093e\\u091a\\u0947 \\u0938\\u094c\\u0902\\u0926\\u0930\\u094d\\u092f \\u0928\\u0937\\u094d\\u091f \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Describe the Three R\\u2019s used to save the environment.\",\"a\":\"The Three R\\u2019s are Reduce, Reuse, and Recycle.\",\"e\":\"\\u092a\\u0930\\u094d\\u092f\\u093e\\u0935\\u0930\\u0923 \\u0935\\u093e\\u091a\\u0935\\u0923\\u094d\\u092f\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0915\\u092e\\u0940 \\u0935\\u093e\\u092a\\u0930 (Reduce), \\u092a\\u0941\\u0928\\u094d\\u0939\\u093e \\u0935\\u093e\\u092a\\u0930 (Reuse) \\u0906\\u0923\\u093f \\u092a\\u0941\\u0928\\u0930\\u094d\\u0935\\u093e\\u092a\\u0930\\u093e\\u0924\\u0942\\u0928 \\u0928\\u093f\\u0930\\u094d\\u092e\\u093f\\u0924\\u0940 (Recycle) \\u092f\\u093e \\u0924\\u0940\\u0928 \\u0928\\u093f\\u092f\\u092e\\u093e\\u0902\\u091a\\u093e \\u0905\\u0935\\u0932\\u0902\\u092c \\u0915\\u0947\\u0932\\u093e \\u091c\\u093e\\u0924\\u094b.\"},{\"q\":\"Explain how reducing waste helps the environment.\",\"a\":\"Reducing waste decreases pollution and conserves natural resources.\",\"e\":\"\\u0915\\u091a\\u0930\\u093e \\u0915\\u092e\\u0940 \\u0915\\u0947\\u0932\\u094d\\u092f\\u093e\\u0938 \\u092a\\u094d\\u0930\\u0926\\u0942\\u0937\\u0923 \\u0918\\u091f\\u0924\\u0947 \\u0906\\u0923\\u093f \\u0928\\u0948\\u0938\\u0930\\u094d\\u0917\\u093f\\u0915 \\u0938\\u093e\\u0927\\u0928\\u0938\\u0902\\u092a\\u0924\\u094d\\u0924\\u0940\\u091a\\u0947 \\u0938\\u0902\\u0930\\u0915\\u094d\\u0937\\u0923 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Describe personal actions that help in saving the environment.\",\"a\":\"Planting trees, avoiding plastic, and saving water help protect the environment.\",\"e\":\"\\u091d\\u093e\\u0921\\u0947 \\u0932\\u093e\\u0935\\u0923\\u0947, \\u092a\\u094d\\u0932\\u093e\\u0938\\u094d\\u091f\\u093f\\u0915 \\u091f\\u093e\\u0933\\u0923\\u0947, \\u092a\\u093e\\u0923\\u0940 \\u0935 \\u0935\\u0940\\u091c \\u0935\\u093e\\u091a\\u0935\\u0923\\u0947 \\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u092a\\u0930\\u094d\\u092f\\u093e\\u0935\\u0930\\u0923\\u093e\\u091a\\u0947 \\u0938\\u0902\\u0930\\u0915\\u094d\\u0937\\u0923 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Summarise why protecting the environment is important for future generations.\",\"a\":\"Protecting the environment ensures healthy living and resources for the future.\",\"e\":\"\\u092a\\u0930\\u094d\\u092f\\u093e\\u0935\\u0930\\u0923\\u093e\\u091a\\u0947 \\u0938\\u0902\\u0930\\u0915\\u094d\\u0937\\u0923 \\u0915\\u0947\\u0932\\u094d\\u092f\\u093e\\u0928\\u0947 \\u092d\\u0935\\u093f\\u0937\\u094d\\u092f\\u093e\\u0924\\u0940\\u0932 \\u092a\\u093f\\u0922\\u094d\\u092f\\u093e\\u0902\\u0938\\u093e\\u0920\\u0940 \\u0928\\u093f\\u0930\\u094b\\u0917\\u0940 \\u091c\\u0940\\u0935\\u0928 \\u0935 \\u0938\\u0902\\u0938\\u093e\\u0927\\u0928\\u0947 \\u0909\\u092a\\u0932\\u092c\\u094d\\u0927 \\u0930\\u093e\\u0939\\u0924\\u093e\\u0924.\"}]','OUR ENVIRONMENT','2026-01-16 12:11:45'),(30,132,'a visit to mawlynnong - Revision','[{\"q\":\"\\ufeffQuestion\",\"a\":\"Answer\",\"e\":\"Explaination in Marathi language\"},{\"q\":\"Describe Mawlynnong and explain why it was declared the cleanest village in Asia.\",\"a\":\"Mawlynnong is a small village in Meghalaya known for its exceptional cleanliness, disciplined community life, and beautiful surroundings. In 2003, it was declared the cleanest village in Asia due to the collective efforts of villagers who maintain hygiene daily.\",\"e\":\"\\u092e\\u093e\\u0935\\u0933\\u093f\\u0928\\u094d\\u0928\\u0949\\u0902\\u0917 \\u0939\\u0947 \\u092e\\u0947\\u0918\\u093e\\u0932\\u092f\\u093e\\u0924\\u0940\\u0932 \\u090f\\u0915 \\u091b\\u094b\\u091f\\u0947 \\u092a\\u0923 \\u0905\\u0924\\u094d\\u092f\\u0902\\u0924 \\u0938\\u094d\\u0935\\u091a\\u094d\\u091b \\u0917\\u093e\\u0935 \\u0906\\u0939\\u0947. \\u092f\\u0947\\u0925\\u0947 \\u092a\\u094d\\u0930\\u0924\\u094d\\u092f\\u0947\\u0915 \\u0928\\u093e\\u0917\\u0930\\u093f\\u0915 \\u0938\\u094d\\u0935\\u091a\\u094d\\u091b\\u0924\\u0947\\u091a\\u0940 \\u091c\\u092c\\u093e\\u092c\\u0926\\u093e\\u0930\\u0940 \\u0938\\u094d\\u0935\\u0924\\u0903 \\u0918\\u0947\\u0924\\u094b. \\u0926\\u0930\\u0930\\u094b\\u091c \\u0938\\u093e\\u092b\\u0938\\u092b\\u093e\\u0908 \\u0915\\u0947\\u0932\\u0940 \\u091c\\u093e\\u0924\\u0947 \\u0935 \\u0936\\u093f\\u0938\\u094d\\u0924\\u092c\\u0926\\u094d\\u0927 \\u091c\\u0940\\u0935\\u0928\\u092a\\u0926\\u094d\\u0927\\u0924\\u0940 \\u092a\\u093e\\u0933\\u0932\\u0940 \\u091c\\u093e\\u0924\\u0947. \\u092f\\u093e \\u090f\\u0915\\u0924\\u094d\\u0930\\u093f\\u0924 \\u092a\\u094d\\u0930\\u092f\\u0924\\u094d\\u0928\\u093e\\u0902\\u092e\\u0941\\u0933\\u0947 2003 \\u092e\\u0927\\u094d\\u092f\\u0947 \\u092f\\u093e \\u0917\\u093e\\u0935\\u093e\\u0932\\u093e \\u0906\\u0936\\u093f\\u092f\\u093e\\u0924\\u0940\\u0932 \\u0938\\u0930\\u094d\\u0935\\u093e\\u0924 \\u0938\\u094d\\u0935\\u091a\\u094d\\u091b \\u0917\\u093e\\u0935\\u093e\\u091a\\u093e \\u0926\\u0930\\u094d\\u091c\\u093e \\u092e\\u093f\\u0933\\u093e\\u0932\\u093e.\"},{\"q\":\"Explain the structure and uniqueness of the Living Root Bridges.\",\"a\":\"The Living Root Bridges are natural bridges formed by twisting and weaving the roots of rubber trees across streams. Over decades, Khasi villagers shape these roots to create strong and eco-friendly bridges unique to Meghalaya.\",\"e\":\"\\u0932\\u093f\\u0935\\u094d\\u0939\\u093f\\u0902\\u0917 \\u0930\\u0942\\u091f \\u092c\\u094d\\u0930\\u093f\\u091c \\u0939\\u0947 \\u0930\\u092c\\u0930 \\u0935\\u0943\\u0915\\u094d\\u0937\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u092e\\u0941\\u0933\\u093e\\u0902\\u0928\\u093e \\u0935\\u093e\\u0915\\u0935\\u0942\\u0928 \\u0906\\u0923\\u093f \\u0935\\u093f\\u0923\\u0942\\u0928 \\u0924\\u092f\\u093e\\u0930 \\u0915\\u0947\\u0932\\u0947\\u0932\\u0947 \\u0928\\u0948\\u0938\\u0930\\u094d\\u0917\\u093f\\u0915 \\u092a\\u0942\\u0932 \\u0906\\u0939\\u0947\\u0924. \\u0916\\u093e\\u0938\\u0940 \\u0938\\u092e\\u093e\\u091c\\u093e\\u0924\\u0940\\u0932 \\u0932\\u094b\\u0915 \\u0905\\u0928\\u0947\\u0915 \\u0935\\u0930\\u094d\\u0937\\u0947 \\u092e\\u0947\\u0939\\u0928\\u0924 \\u0918\\u0947\\u090a\\u0928 \\u0939\\u0947 \\u092a\\u0942\\u0932 \\u0924\\u092f\\u093e\\u0930 \\u0915\\u0930\\u0924\\u093e\\u0924. \\u0939\\u0947 \\u092a\\u0930\\u094d\\u092f\\u093e\\u0935\\u0930\\u0923\\u092a\\u0942\\u0930\\u0915 \\u0935 \\u091f\\u093f\\u0915\\u093e\\u090a \\u0905\\u0938\\u0932\\u094d\\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u092e\\u0947\\u0918\\u093e\\u0932\\u092f\\u093e\\u0924 \\u0935\\u093f\\u0936\\u0947\\u0937 \\u092e\\u093e\\u0928\\u0932\\u0947 \\u091c\\u093e\\u0924\\u093e\\u0924.\"},{\"q\":\"Describe the guest house where Janvi stayed.\",\"a\":\"The guest house was made of bamboo and built on stilts, giving it the appearance of a tree house. It had two bedrooms, a living room, and a verandah. There was also a \\u2018machan\\u2019 where Janvi sat and enjoyed the greenery.\",\"e\":\"\\u091c\\u093e\\u0928\\u0935\\u0940 \\u091c\\u094d\\u092f\\u093e \\u0917\\u0947\\u0938\\u094d\\u091f \\u0939\\u093e\\u090a\\u0938\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0930\\u093e\\u0939\\u093f\\u0932\\u0940 \\u0924\\u0947 \\u092c\\u093e\\u0902\\u092c\\u0942\\u092a\\u093e\\u0938\\u0942\\u0928 \\u092c\\u0928\\u0935\\u0932\\u0947\\u0932\\u0947 \\u0939\\u094b\\u0924\\u0947 \\u0906\\u0923\\u093f \\u0924\\u0947 \\u0916\\u093e\\u0902\\u092c\\u093e\\u0902\\u0935\\u0930 \\u0909\\u092d\\u093e\\u0930\\u0932\\u0947 \\u0939\\u094b\\u0924\\u0947. \\u0924\\u094d\\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0924\\u0947 \\u091d\\u093e\\u0921\\u093e\\u0935\\u0930\\u0940\\u0932 \\u0918\\u0930\\u093e\\u0938\\u093e\\u0930\\u0916\\u0947 \\u0935\\u093e\\u091f\\u0924 \\u0939\\u094b\\u0924\\u0947. \\u0924\\u094d\\u092f\\u093e\\u0924 \\u0926\\u094b\\u0928 \\u092c\\u0947\\u0921\\u0930\\u0942\\u092e, \\u090f\\u0915 \\u092c\\u0948\\u0920\\u0915 \\u0916\\u094b\\u0932\\u0940 \\u0906\\u0923\\u093f \\u092a\\u0921\\u0935\\u0940 \\u0939\\u094b\\u0924\\u0940. \\u0924\\u0938\\u0947\\u091a \\u090f\\u0915 \\u2018\\u092e\\u091a\\u093e\\u0928\\u2019 \\u0939\\u094b\\u0924\\u0947 \\u091c\\u093f\\u0925\\u0947 \\u0924\\u0940 \\u092c\\u0938\\u0942\\u0928 \\u0928\\u093f\\u0938\\u0930\\u094d\\u0917\\u093e\\u091a\\u093e \\u0906\\u0928\\u0902\\u0926 \\u0918\\u0947\\u0924 \\u0939\\u094b\\u0924\\u0940.\"},{\"q\":\"How does the Sky View tower add to the uniqueness of Mawlynnong?\",\"a\":\"The Sky View is a tall bamboo viewing tower constructed by villagers. From the top, visitors can see not only the village but also the rice fields of Bangladesh across the border.\",\"e\":\"\\u0938\\u094d\\u0915\\u093e\\u092f \\u0935\\u094d\\u0939\\u094d\\u092f\\u0942 \\u0939\\u093e \\u092c\\u093e\\u0902\\u092c\\u0942\\u092a\\u093e\\u0938\\u0942\\u0928 \\u0924\\u092f\\u093e\\u0930 \\u0915\\u0947\\u0932\\u0947\\u0932\\u093e \\u0909\\u0902\\u091a \\u092e\\u0928\\u094b\\u0930\\u093e \\u0906\\u0939\\u0947. \\u092f\\u0947\\u0925\\u0942\\u0928 \\u092d\\u093e\\u0930\\u0924\\u093e\\u092c\\u0930\\u094b\\u092c\\u0930\\u091a \\u092c\\u093e\\u0902\\u0917\\u0932\\u093e\\u0926\\u0947\\u0936\\u093e\\u0924\\u0940\\u0932 \\u092d\\u093e\\u0924\\u0936\\u0947\\u0924\\u0940\\u0939\\u0940 \\u0926\\u093f\\u0938\\u0924\\u0947. \\u0924\\u094d\\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0917\\u093e\\u0935\\u093e\\u091a\\u0947 \\u092d\\u094c\\u0917\\u094b\\u0932\\u093f\\u0915 \\u0935\\u0948\\u0936\\u093f\\u0937\\u094d\\u091f\\u094d\\u092f \\u0906\\u0923\\u093f \\u092a\\u0930\\u094d\\u092f\\u091f\\u0928 \\u092e\\u0942\\u0932\\u094d\\u092f \\u0935\\u093e\\u0922\\u0924\\u0947.\"},{\"q\":\"Explain the role of children in maintaining cleanliness in Mawlynnong.\",\"a\":\"Children play an active role in keeping the village clean. Before going to school, they sweep the streets and empty dustbins, showing strong civic responsibility from a young age.\",\"e\":\"\\u092e\\u093e\\u0935\\u0933\\u093f\\u0928\\u094d\\u0928\\u0949\\u0902\\u0917\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0932\\u0939\\u093e\\u0928 \\u092e\\u0941\\u0932\\u0947\\u0939\\u0940 \\u0938\\u094d\\u0935\\u091a\\u094d\\u091b\\u0924\\u0947\\u091a\\u0940 \\u091c\\u092c\\u093e\\u092c\\u0926\\u093e\\u0930\\u0940 \\u092a\\u093e\\u0930 \\u092a\\u093e\\u0921\\u0924\\u093e\\u0924. \\u0936\\u093e\\u0933\\u0947\\u0924 \\u091c\\u093e\\u0923\\u094d\\u092f\\u093e\\u092a\\u0942\\u0930\\u094d\\u0935\\u0940 \\u0924\\u0947 \\u0930\\u0938\\u094d\\u0924\\u0947 \\u091d\\u093e\\u0921\\u0924\\u093e\\u0924 \\u0906\\u0923\\u093f \\u0915\\u091a\\u0930\\u093e \\u0915\\u093e\\u0922\\u0924\\u093e\\u0924. \\u0924\\u094d\\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0924\\u094d\\u092f\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e\\u0924 \\u0932\\u0939\\u093e\\u0928\\u092a\\u0923\\u093e\\u092a\\u093e\\u0938\\u0942\\u0928 \\u0938\\u093e\\u092e\\u093e\\u091c\\u093f\\u0915 \\u091c\\u092c\\u093e\\u092c\\u0926\\u093e\\u0930\\u0940\\u091a\\u0940 \\u091c\\u093e\\u0923\\u0940\\u0935 \\u0935\\u093f\\u0915\\u0938\\u093f\\u0924 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Describe Deity Bakordor\\u2019s attitude towards littering.\",\"a\":\"Deity believed in silent responsibility. If someone littered, she would not confront them directly but would quietly pick up the rubbish and dispose of it properly.\",\"e\":\"\\u0921\\u093e\\u092f\\u091f\\u0940 \\u092c\\u093e\\u0915\\u094b\\u0930\\u094d\\u0921\\u094b\\u0930 \\u0939\\u093f\\u091a\\u093e \\u0926\\u0943\\u0937\\u094d\\u091f\\u093f\\u0915\\u094b\\u0928 \\u0936\\u093e\\u0902\\u0924 \\u0906\\u0923\\u093f \\u091c\\u092c\\u093e\\u092c\\u0926\\u093e\\u0930 \\u0939\\u094b\\u0924\\u093e. \\u0915\\u094b\\u0923\\u0940 \\u0915\\u091a\\u0930\\u093e \\u091f\\u093e\\u0915\\u0932\\u094d\\u092f\\u093e\\u0938 \\u0924\\u0940 \\u0924\\u094d\\u092f\\u093e\\u0902\\u0928\\u093e \\u0928 \\u0938\\u093e\\u0902\\u0917\\u0924\\u093e \\u0938\\u094d\\u0935\\u0924\\u0903 \\u0924\\u094b \\u0909\\u091a\\u0932\\u0942\\u0928 \\u0915\\u091a\\u0930\\u093e\\u092a\\u0947\\u091f\\u0940\\u0924 \\u091f\\u093e\\u0915\\u093e\\u092f\\u091a\\u0940. \\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0924\\u093f\\u091a\\u0940 \\u0936\\u093f\\u0938\\u094d\\u0924 \\u0906\\u0923\\u093f \\u0938\\u0902\\u0938\\u094d\\u0915\\u093e\\u0930 \\u0926\\u093f\\u0938\\u0942\\u0928 \\u092f\\u0947\\u0924\\u093e\\u0924.\"},{\"q\":\"Discuss the importance of \\u2018social work\\u2019 assigned on Saturdays.\",\"a\":\"On Saturdays, the village leader assigns extra \\u2018social work\\u2019 to villagers. This ensures collective responsibility and strengthens unity among the people.\",\"e\":\"\\u0936\\u0928\\u093f\\u0935\\u093e\\u0930\\u0940 \\u0917\\u093e\\u0935\\u092a\\u094d\\u0930\\u092e\\u0941\\u0916 \\u0938\\u0930\\u094d\\u0935\\u093e\\u0902\\u0928\\u093e \\u0905\\u0924\\u093f\\u0930\\u093f\\u0915\\u094d\\u0924 \\u2018\\u0938\\u093e\\u092e\\u093e\\u091c\\u093f\\u0915 \\u0915\\u093e\\u092e\\u2019 \\u0926\\u0947\\u0924\\u093e\\u0924. \\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0917\\u093e\\u0935\\u093e\\u0924\\u0940\\u0932 \\u0910\\u0915\\u094d\\u092f \\u0935\\u093e\\u0922\\u0924\\u0947 \\u0906\\u0923\\u093f \\u092a\\u094d\\u0930\\u0924\\u094d\\u092f\\u0947\\u0915 \\u091c\\u0923 \\u0917\\u093e\\u0935\\u093e\\u091a\\u094d\\u092f\\u093e \\u0935\\u093f\\u0915\\u093e\\u0938\\u093e\\u0938\\u093e\\u0920\\u0940 \\u092f\\u094b\\u0917\\u0926\\u093e\\u0928 \\u0926\\u0947\\u0924\\u094b.\"},{\"q\":\"Explain the significance of Mawlynnong\\u2019s bamboo usage.\",\"a\":\"Bamboo is widely used in Mawlynnong for houses, the Sky View tower, and baskets. It reflects sustainable living and eco-friendly practices.\",\"e\":\"\\u092c\\u093e\\u0902\\u092c\\u0942\\u091a\\u093e \\u0935\\u093e\\u092a\\u0930 \\u0918\\u0930\\u093e\\u0902\\u0938\\u093e\\u0920\\u0940, \\u0938\\u094d\\u0915\\u093e\\u092f \\u0935\\u094d\\u0939\\u094d\\u092f\\u0942\\u0938\\u093e\\u0920\\u0940 \\u0906\\u0923\\u093f \\u0915\\u091a\\u0930\\u093e\\u092a\\u0947\\u091f\\u094d\\u092f\\u093e\\u0902\\u0938\\u093e\\u0920\\u0940 \\u0915\\u0947\\u0932\\u093e \\u091c\\u093e\\u0924\\u094b. \\u0939\\u0947 \\u092a\\u0930\\u094d\\u092f\\u093e\\u0935\\u0930\\u0923\\u092a\\u0942\\u0930\\u0915 \\u091c\\u0940\\u0935\\u0928\\u0936\\u0948\\u0932\\u0940\\u091a\\u0947 \\u092a\\u094d\\u0930\\u0924\\u0940\\u0915 \\u0906\\u0939\\u0947 \\u0906\\u0923\\u093f \\u091f\\u093f\\u0915\\u093e\\u090a \\u0935\\u093f\\u0915\\u093e\\u0938\\u093e\\u091a\\u0940 \\u091c\\u093e\\u0923\\u0940\\u0935 \\u0926\\u0930\\u094d\\u0936\\u0935\\u0924\\u0947.\"},{\"q\":\"Describe the natural beauty experienced by Janvi in the village.\",\"a\":\"Janvi experienced greenery, gentle gurgling waterfalls, colourful flowers, and fresh surroundings, which deeply impressed her.\",\"e\":\"\\u091c\\u093e\\u0928\\u0935\\u0940\\u0928\\u0947 \\u0939\\u093f\\u0930\\u0935\\u0940\\u0917\\u093e\\u0930 \\u091d\\u093e\\u0921\\u0947, \\u092e\\u0902\\u0926 \\u0935\\u093e\\u0939\\u0923\\u093e\\u0930\\u093e \\u0927\\u092c\\u0927\\u092c\\u093e, \\u0930\\u0902\\u0917\\u0940\\u092c\\u0947\\u0930\\u0902\\u0917\\u0940 \\u092b\\u0941\\u0932\\u0947 \\u0906\\u0923\\u093f \\u0924\\u093e\\u091c\\u0947 \\u0935\\u093e\\u0924\\u093e\\u0935\\u0930\\u0923 \\u0905\\u0928\\u0941\\u092d\\u0935\\u0932\\u0947. \\u092f\\u093e \\u0928\\u0948\\u0938\\u0930\\u094d\\u0917\\u093f\\u0915 \\u0938\\u094c\\u0902\\u0926\\u0930\\u094d\\u092f\\u093e\\u0928\\u0947 \\u0924\\u0940 \\u0916\\u0942\\u092a \\u092a\\u094d\\u0930\\u092d\\u093e\\u0935\\u093f\\u0924 \\u091d\\u093e\\u0932\\u0940.\"},{\"q\":\"Explain how the lesson promotes environmental awareness.\",\"a\":\"The lesson emphasizes cleanliness, sustainability, recycling practices, and community participation, encouraging readers to respect nature.\",\"e\":\"\\u092f\\u093e \\u0927\\u0921\\u094d\\u092f\\u093e\\u0924 \\u0938\\u094d\\u0935\\u091a\\u094d\\u091b\\u0924\\u093e, \\u092a\\u0930\\u094d\\u092f\\u093e\\u0935\\u0930\\u0923\\u092a\\u0942\\u0930\\u0915 \\u092a\\u0926\\u094d\\u0927\\u0924\\u0940 \\u0906\\u0923\\u093f \\u0938\\u093e\\u092e\\u0942\\u0939\\u093f\\u0915 \\u0938\\u0939\\u092d\\u093e\\u0917 \\u092f\\u093e\\u0902\\u091a\\u0947 \\u092e\\u0939\\u0924\\u094d\\u0924\\u094d\\u0935 \\u0938\\u093e\\u0902\\u0917\\u093f\\u0924\\u0932\\u0947 \\u0906\\u0939\\u0947. \\u0924\\u094d\\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0935\\u093f\\u0926\\u094d\\u092f\\u093e\\u0930\\u094d\\u0925\\u094d\\u092f\\u093e\\u0902\\u092e\\u0927\\u094d\\u092f\\u0947 \\u092a\\u0930\\u094d\\u092f\\u093e\\u0935\\u0930\\u0923\\u093e\\u092c\\u0926\\u094d\\u0926\\u0932 \\u091c\\u093e\\u0917\\u0930\\u0942\\u0915\\u0924\\u093e \\u0928\\u093f\\u0930\\u094d\\u092e\\u093e\\u0923 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Discuss the moral values highlighted through the story.\",\"a\":\"The story highlights responsibility, discipline, community effort, respect for nature, and civic sense.\",\"e\":\"\\u092f\\u093e \\u0915\\u0925\\u0947\\u0924 \\u091c\\u092c\\u093e\\u092c\\u0926\\u093e\\u0930\\u0940, \\u0936\\u093f\\u0938\\u094d\\u0924, \\u0938\\u093e\\u092e\\u0942\\u0939\\u093f\\u0915 \\u092a\\u094d\\u0930\\u092f\\u0924\\u094d\\u0928, \\u0928\\u093f\\u0938\\u0930\\u094d\\u0917\\u093e\\u091a\\u093e \\u0906\\u0926\\u0930 \\u0906\\u0923\\u093f \\u0928\\u093e\\u0917\\u0930\\u093f\\u0915 \\u0915\\u0930\\u094d\\u0924\\u0935\\u094d\\u092f \\u092f\\u093e\\u0902\\u0938\\u093e\\u0930\\u0916\\u0940 \\u0928\\u0948\\u0924\\u093f\\u0915 \\u092e\\u0942\\u0932\\u094d\\u092f\\u0947 \\u0905\\u0927\\u094b\\u0930\\u0947\\u0916\\u093f\\u0924 \\u0915\\u0947\\u0932\\u0940 \\u0906\\u0939\\u0947\\u0924.\"},{\"q\":\"Describe the importance of the Sacred Groves Forest in Meghalaya.\",\"a\":\"The Sacred Groves Forest in Meghalaya is known for rare species of plants and animals and represents ecological preservation.\",\"e\":\"\\u092e\\u0947\\u0918\\u093e\\u0932\\u092f\\u093e\\u0924\\u0940\\u0932 \\u0938\\u0947\\u0915\\u094d\\u0930\\u0947\\u0921 \\u0917\\u094d\\u0930\\u094b\\u0935\\u094d\\u0939\\u094d\\u0938 \\u091c\\u0902\\u0917\\u0932 \\u0926\\u0941\\u0930\\u094d\\u092e\\u093f\\u0933 \\u0935\\u0928\\u0938\\u094d\\u092a\\u0924\\u0940 \\u0906\\u0923\\u093f \\u092a\\u094d\\u0930\\u093e\\u0923\\u094d\\u092f\\u093e\\u0902\\u0938\\u093e\\u0920\\u0940 \\u092a\\u094d\\u0930\\u0938\\u093f\\u0926\\u094d\\u0927 \\u0906\\u0939\\u0947. \\u0939\\u0947 \\u092a\\u0930\\u094d\\u092f\\u093e\\u0935\\u0930\\u0923 \\u0938\\u0902\\u0935\\u0930\\u094d\\u0927\\u0928\\u093e\\u091a\\u0947 \\u0909\\u0924\\u094d\\u0924\\u092e \\u0909\\u0926\\u093e\\u0939\\u0930\\u0923 \\u0906\\u0939\\u0947.\"},{\"q\":\"Explain why Mawlynnong is considered a model village.\",\"a\":\"Mawlynnong is considered a model village because of its cleanliness, organized lifestyle, eco-friendly practices, and collective discipline.\",\"e\":\"\\u0938\\u094d\\u0935\\u091a\\u094d\\u091b\\u0924\\u093e, \\u0936\\u093f\\u0938\\u094d\\u0924\\u092c\\u0926\\u094d\\u0927 \\u091c\\u0940\\u0935\\u0928\\u0936\\u0948\\u0932\\u0940 \\u0906\\u0923\\u093f \\u092a\\u0930\\u094d\\u092f\\u093e\\u0935\\u0930\\u0923\\u092a\\u0942\\u0930\\u0915 \\u092a\\u0926\\u094d\\u0927\\u0924\\u0940 \\u092f\\u093e\\u0902\\u092e\\u0941\\u0933\\u0947 \\u092e\\u093e\\u0935\\u0933\\u093f\\u0928\\u094d\\u0928\\u0949\\u0902\\u0917 \\u0906\\u0926\\u0930\\u094d\\u0936 \\u0917\\u093e\\u0935 \\u092e\\u094d\\u0939\\u0923\\u0942\\u0928 \\u0913\\u0933\\u0916\\u0932\\u0947 \\u091c\\u093e\\u0924\\u0947.\"},{\"q\":\"How does Janvi\\u2019s letter reflect her change in perspective about village life?\",\"a\":\"Initially fond of city life, Janvi learned to appreciate village life after experiencing its cleanliness, peace, and community spirit.\",\"e\":\"\\u0938\\u0941\\u0930\\u0941\\u0935\\u093e\\u0924\\u0940\\u0932\\u093e \\u0936\\u0939\\u0930\\u091c\\u0940\\u0935\\u0928 \\u0906\\u0935\\u0921\\u0923\\u093e\\u0931\\u094d\\u092f\\u093e \\u091c\\u093e\\u0928\\u0935\\u0940\\u0932\\u093e \\u0917\\u093e\\u0935\\u093e\\u0924\\u0940\\u0932 \\u0936\\u093e\\u0902\\u0924\\u0924\\u093e, \\u0938\\u094d\\u0935\\u091a\\u094d\\u091b\\u0924\\u093e \\u0906\\u0923\\u093f \\u0938\\u093e\\u092e\\u0942\\u0939\\u093f\\u0915 \\u092d\\u093e\\u0935\\u0928\\u093e \\u0905\\u0928\\u0941\\u092d\\u0935\\u0942\\u0928 \\u0924\\u093f\\u091a\\u093e \\u0926\\u0943\\u0937\\u094d\\u091f\\u093f\\u0915\\u094b\\u0928 \\u092c\\u0926\\u0932\\u0932\\u093e.\"},{\"q\":\"Summarize the key message of the lesson \\u201cA Visit to Mawlynnong\\u201d.\",\"a\":\"The lesson teaches that cleanliness, unity, and environmental responsibility can transform a village into a model community admired by the world.\",\"e\":\"\\u2018A Visit to Mawlynnong\\u2019 \\u092f\\u093e \\u0927\\u0921\\u094d\\u092f\\u093e\\u091a\\u093e \\u092e\\u0941\\u0916\\u094d\\u092f \\u0938\\u0902\\u0926\\u0947\\u0936 \\u0905\\u0938\\u093e \\u0906\\u0939\\u0947 \\u0915\\u0940 \\u0938\\u094d\\u0935\\u091a\\u094d\\u091b\\u0924\\u093e, \\u090f\\u0915\\u0924\\u093e \\u0906\\u0923\\u093f \\u092a\\u0930\\u094d\\u092f\\u093e\\u0935\\u0930\\u0923\\u093e\\u091a\\u0940 \\u091c\\u092c\\u093e\\u092c\\u0926\\u093e\\u0930\\u0940 \\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0915\\u094b\\u0923\\u0924\\u0947\\u0939\\u0940 \\u0917\\u093e\\u0935 \\u0906\\u0926\\u0930\\u094d\\u0936 \\u092c\\u0928\\u0942 \\u0936\\u0915\\u0924\\u0947.\"}]','long answer and short answer','2026-02-12 16:56:41'),(31,133,'BOOND - Revision','[{\"q\":\"\\ufeffQuestion\",\"a\":\"Answer\",\"e\":\"Explaination in Marathi language\"},{\"q\":\"Explain how the story of \\u2018Boond: To the Mountains and Back\\u2019 describes the water cycle.\",\"a\":\"The story personifies a drop of water named Boond and traces her journey from the ocean to the clouds, then to the mountains as rain, and finally back to the ocean. This sequence represents evaporation, condensation, precipitation, and runoff \\u2014 the four key stages of the water cycle.\",\"e\":\"\\u092f\\u093e \\u0915\\u0925\\u0947\\u092e\\u0927\\u094d\\u092f\\u0947 \\u2018\\u092c\\u0942\\u0902\\u0926\\u2019 \\u092f\\u093e \\u092a\\u093e\\u0935\\u0938\\u093e\\u091a\\u094d\\u092f\\u093e \\u0925\\u0947\\u0902\\u092c\\u093e\\u091a\\u094d\\u092f\\u093e \\u092e\\u093e\\u0927\\u094d\\u092f\\u092e\\u093e\\u0924\\u0942\\u0928 \\u091c\\u0932\\u091a\\u0915\\u094d\\u0930 \\u0938\\u094d\\u092a\\u0937\\u094d\\u091f \\u0915\\u0947\\u0932\\u0947 \\u0906\\u0939\\u0947. \\u0938\\u092e\\u0941\\u0926\\u094d\\u0930\\u093e\\u0924\\u0942\\u0928 \\u092c\\u093e\\u0937\\u094d\\u092a\\u0940\\u092d\\u0935\\u0928 \\u0939\\u094b\\u090a\\u0928 \\u0922\\u0917 \\u0924\\u092f\\u093e\\u0930 \\u0939\\u094b\\u0924\\u093e\\u0924, \\u0928\\u0902\\u0924\\u0930 \\u092a\\u0930\\u094d\\u091c\\u0928\\u094d\\u092f\\u0930\\u0942\\u092a\\u093e\\u0928\\u0947 \\u092a\\u093e\\u0923\\u0940 \\u092a\\u0930\\u094d\\u0935\\u0924\\u093e\\u0902\\u0935\\u0930 \\u092a\\u0921\\u0924\\u0947 \\u0906\\u0923\\u093f \\u0936\\u0947\\u0935\\u091f\\u0940 \\u0935\\u093e\\u0939\\u0942\\u0928 \\u092a\\u0941\\u0928\\u094d\\u0939\\u093e \\u0938\\u092e\\u0941\\u0926\\u094d\\u0930\\u093e\\u0924 \\u091c\\u093e\\u0924\\u0947. \\u0939\\u0940 \\u092a\\u094d\\u0930\\u0915\\u094d\\u0930\\u093f\\u092f\\u093e \\u092e\\u094d\\u0939\\u0923\\u091c\\u0947\\u091a \\u092c\\u093e\\u0937\\u094d\\u092a\\u0940\\u092d\\u0935\\u0928, \\u0938\\u0902\\u0918\\u0928\\u0928, \\u092a\\u0930\\u094d\\u091c\\u0928\\u094d\\u092f \\u0906\\u0923\\u093f \\u092a\\u094d\\u0930\\u0935\\u093e\\u0939 \\u0939\\u0940 \\u091c\\u0932\\u091a\\u0915\\u094d\\u0930\\u093e\\u091a\\u0940 \\u092e\\u0941\\u0916\\u094d\\u092f \\u091f\\u092a\\u094d\\u092a\\u0947 \\u0906\\u0939\\u0947\\u0924.\"},{\"q\":\"Describe Boond\\u2019s journey from Sagar to Badal and explain the scientific process behind it.\",\"a\":\"Boond rises from Sagar due to the Sun\\u2019s heat and reaches Badal, the cloud. Scientifically, this represents evaporation caused by solar energy, where water changes from liquid to vapour and moves upward.\",\"e\":\"\\u092c\\u0942\\u0902\\u0926 \\u0938\\u0942\\u0930\\u094d\\u092f\\u093e\\u091a\\u094d\\u092f\\u093e \\u0909\\u0937\\u094d\\u0923\\u0924\\u0947\\u092e\\u0941\\u0933\\u0947 \\u0938\\u093e\\u0917\\u0930\\u093e\\u0924\\u0942\\u0928 \\u0935\\u0930 \\u091c\\u093e\\u0924\\u0947 \\u0906\\u0923\\u093f \\u092c\\u0926\\u0932\\u092c\\u0930\\u094b\\u092c\\u0930 \\u0906\\u0915\\u093e\\u0936\\u093e\\u0924 \\u092a\\u094b\\u0939\\u094b\\u091a\\u0924\\u0947. \\u0935\\u0948\\u091c\\u094d\\u091e\\u093e\\u0928\\u093f\\u0915 \\u0926\\u0943\\u0937\\u094d\\u091f\\u0940\\u0928\\u0947 \\u0939\\u0940 \\u092a\\u094d\\u0930\\u0915\\u094d\\u0930\\u093f\\u092f\\u093e \\u092c\\u093e\\u0937\\u094d\\u092a\\u0940\\u092d\\u0935\\u0928\\u093e\\u091a\\u0940 \\u0906\\u0939\\u0947. \\u0938\\u0942\\u0930\\u094d\\u092f\\u093e\\u091a\\u094d\\u092f\\u093e \\u0909\\u0937\\u094d\\u0923\\u0924\\u0947\\u092e\\u0941\\u0933\\u0947 \\u092a\\u093e\\u0923\\u0940 \\u0935\\u093e\\u092f\\u0942\\u0930\\u0942\\u092a \\u0927\\u093e\\u0930\\u0923 \\u0915\\u0930\\u0924\\u0947 \\u0906\\u0923\\u093f \\u0935\\u0930 \\u091c\\u093e\\u0924\\u0947.\"},{\"q\":\"Why did Boond jump off Badal and what stage of the water cycle does it represent?\",\"a\":\"Boond jumped off Badal to meet Parbat and Jharna. This represents precipitation, where condensed water droplets fall to the Earth as rain.\",\"e\":\"\\u092c\\u0942\\u0902\\u0926 \\u092c\\u0926\\u0932\\u093e\\u0935\\u0930\\u0942\\u0928 \\u0909\\u0921\\u0940 \\u092e\\u093e\\u0930\\u0924\\u0947 \\u0915\\u093e\\u0930\\u0923 \\u0924\\u0940 \\u092a\\u0930\\u094d\\u0935\\u0924 \\u0906\\u0923\\u093f \\u091d\\u0931\\u094d\\u092f\\u093e\\u0915\\u0921\\u0947 \\u091c\\u093e\\u0924\\u0947. \\u0939\\u0940 \\u092a\\u0930\\u094d\\u091c\\u0928\\u094d\\u092f \\u092a\\u094d\\u0930\\u0915\\u094d\\u0930\\u093f\\u092f\\u093e \\u0926\\u0930\\u094d\\u0936\\u0935\\u0924\\u0947, \\u091c\\u094d\\u092f\\u093e\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0922\\u0917\\u093e\\u0924\\u0940\\u0932 \\u092a\\u093e\\u0923\\u0940 \\u092a\\u0943\\u0925\\u094d\\u0935\\u0940\\u0935\\u0930 \\u092a\\u093e\\u0935\\u0938\\u093e\\u091a\\u094d\\u092f\\u093e \\u0930\\u0942\\u092a\\u093e\\u0924 \\u092a\\u0921\\u0924\\u0947.\"},{\"q\":\"Explain the importance of the Sun in the water cycle as shown in the story.\",\"a\":\"The Sun provides the heat energy required for evaporation. Without the Sun, water would not rise into the atmosphere, and the water cycle would not function.\",\"e\":\"\\u091c\\u0932\\u091a\\u0915\\u094d\\u0930\\u093e\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0938\\u0942\\u0930\\u094d\\u092f\\u093e\\u091a\\u0940 \\u0905\\u0924\\u094d\\u092f\\u0902\\u0924 \\u092e\\u0939\\u0924\\u094d\\u0924\\u094d\\u0935\\u093e\\u091a\\u0940 \\u092d\\u0942\\u092e\\u093f\\u0915\\u093e \\u0906\\u0939\\u0947. \\u0938\\u0942\\u0930\\u094d\\u092f\\u093e\\u091a\\u094d\\u092f\\u093e \\u0909\\u0937\\u094d\\u0923\\u0924\\u0947\\u0936\\u093f\\u0935\\u093e\\u092f \\u092c\\u093e\\u0937\\u094d\\u092a\\u0940\\u092d\\u0935\\u0928 \\u0939\\u094b\\u0923\\u093e\\u0930 \\u0928\\u093e\\u0939\\u0940 \\u0906\\u0923\\u093f \\u092a\\u093e\\u0923\\u0940 \\u0935\\u0930 \\u091c\\u093e\\u090a \\u0936\\u0915\\u0923\\u093e\\u0930 \\u0928\\u093e\\u0939\\u0940. \\u0924\\u094d\\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u091c\\u0932\\u091a\\u0915\\u094d\\u0930 \\u0925\\u093e\\u0902\\u092c\\u0947\\u0932.\"},{\"q\":\"Discuss the environmental message conveyed through the \\u2018Do You Know?\\u2019 facts.\",\"a\":\"The facts highlight that although 70% of Earth is covered with water, only 1% is available for human use. This emphasizes the importance of water conservation.\",\"e\":\"\\u2018Do You Know?\\u2019 \\u092e\\u0927\\u094d\\u092f\\u0947 \\u0926\\u093f\\u0932\\u0947\\u0932\\u094d\\u092f\\u093e \\u092e\\u093e\\u0939\\u093f\\u0924\\u0940\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0938\\u093e\\u0902\\u0917\\u093f\\u0924\\u0932\\u0947 \\u0906\\u0939\\u0947 \\u0915\\u0940 \\u092a\\u0943\\u0925\\u094d\\u0935\\u0940\\u0935\\u0930\\u0940\\u0932 70% \\u092d\\u093e\\u0917 \\u092a\\u093e\\u0923\\u094d\\u092f\\u093e\\u0928\\u0947 \\u091d\\u093e\\u0915\\u0932\\u0947\\u0932\\u093e \\u0905\\u0938\\u0932\\u093e \\u0924\\u0930\\u0940 \\u0924\\u094d\\u092f\\u093e\\u092a\\u0948\\u0915\\u0940 \\u092b\\u0915\\u094d\\u0924 1% \\u092a\\u093e\\u0923\\u0940 \\u092e\\u093e\\u0928\\u0935\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0909\\u092a\\u0932\\u092c\\u094d\\u0927 \\u0906\\u0939\\u0947. \\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u092a\\u093e\\u0923\\u094d\\u092f\\u093e\\u091a\\u0940 \\u092c\\u091a\\u0924 \\u0915\\u0930\\u0923\\u094d\\u092f\\u093e\\u091a\\u0940 \\u0906\\u0935\\u0936\\u094d\\u092f\\u0915\\u0924\\u093e \\u0905\\u0927\\u094b\\u0930\\u0947\\u0916\\u093f\\u0924 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Explain how personification is used in the story to teach scientific concepts.\",\"a\":\"Natural elements such as Boond, Badal, Sagar and Jharna are given human qualities like speaking and playing. This makes the concept of the water cycle easier and more engaging for children.\",\"e\":\"\\u092f\\u093e \\u0915\\u0925\\u0947\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0928\\u093f\\u0938\\u0930\\u094d\\u0917\\u093e\\u0924\\u0940\\u0932 \\u0918\\u091f\\u0915\\u093e\\u0902\\u0928\\u093e \\u092e\\u093e\\u0928\\u0935\\u0940 \\u0917\\u0941\\u0923\\u0927\\u0930\\u094d\\u092e \\u0926\\u093f\\u0932\\u0947 \\u0906\\u0939\\u0947\\u0924. \\u092c\\u0942\\u0902\\u0926 \\u092c\\u094b\\u0932\\u0924\\u0947, \\u0916\\u0947\\u0933\\u0924\\u0947, \\u092d\\u093e\\u0935\\u0928\\u093e \\u0935\\u094d\\u092f\\u0915\\u094d\\u0924 \\u0915\\u0930\\u0924\\u0947. \\u0924\\u094d\\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u091c\\u0932\\u091a\\u0915\\u094d\\u0930\\u093e\\u091a\\u0940 \\u0915\\u0932\\u094d\\u092a\\u0928\\u093e \\u092e\\u0941\\u0932\\u093e\\u0902\\u0928\\u093e \\u0938\\u092e\\u091c\\u0923\\u094d\\u092f\\u093e\\u0938 \\u0938\\u094b\\u092a\\u0940 \\u0935 \\u092e\\u0928\\u094b\\u0930\\u0902\\u091c\\u0915 \\u092c\\u0928\\u0924\\u0947.\"},{\"q\":\"Describe the role of runoff in completing Boond\\u2019s journey.\",\"a\":\"After falling on the mountains, Boond travels through waterfalls and streams back to the ocean. This movement is called runoff and completes the water cycle.\",\"e\":\"\\u092a\\u0930\\u094d\\u0935\\u0924\\u093e\\u0902\\u0935\\u0930 \\u092a\\u0921\\u0932\\u094d\\u092f\\u093e\\u0928\\u0902\\u0924\\u0930 \\u092c\\u0942\\u0902\\u0926 \\u091d\\u0931\\u094d\\u092f\\u093e\\u0902\\u0924\\u0942\\u0928 \\u0906\\u0923\\u093f \\u0928\\u0926\\u094d\\u092f\\u093e\\u0902\\u092e\\u0927\\u0942\\u0928 \\u0935\\u093e\\u0939\\u0924 \\u092a\\u0941\\u0928\\u094d\\u0939\\u093e \\u0938\\u092e\\u0941\\u0926\\u094d\\u0930\\u093e\\u0924 \\u091c\\u093e\\u0924\\u0947. \\u092f\\u093e \\u092a\\u094d\\u0930\\u0915\\u094d\\u0930\\u093f\\u092f\\u0947\\u0938 \\u092a\\u094d\\u0930\\u0935\\u093e\\u0939 (runoff) \\u092e\\u094d\\u0939\\u0923\\u0924\\u093e\\u0924 \\u0906\\u0923\\u093f \\u0924\\u094d\\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u091c\\u0932\\u091a\\u0915\\u094d\\u0930 \\u092a\\u0942\\u0930\\u094d\\u0923 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"How does the narrative style help students understand complex ideas?\",\"a\":\"By presenting scientific processes through a simple story and characters, the narrative style simplifies abstract ideas and makes learning enjoyable.\",\"e\":\"\\u0915\\u0925\\u0928\\u0936\\u0948\\u0932\\u0940\\u092e\\u0941\\u0933\\u0947 \\u091c\\u091f\\u093f\\u0932 \\u0935\\u0948\\u091c\\u094d\\u091e\\u093e\\u0928\\u093f\\u0915 \\u0938\\u0902\\u0915\\u0932\\u094d\\u092a\\u0928\\u093e \\u0938\\u0941\\u0932\\u092d \\u0939\\u094b\\u0924\\u093e\\u0924. \\u092a\\u093e\\u0924\\u094d\\u0930\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u092e\\u093e\\u0927\\u094d\\u092f\\u092e\\u093e\\u0924\\u0942\\u0928 \\u0938\\u093e\\u0902\\u0917\\u093f\\u0924\\u0932\\u0947\\u0932\\u0940 \\u0917\\u094b\\u0937\\u094d\\u091f \\u0935\\u093f\\u0926\\u094d\\u092f\\u093e\\u0930\\u094d\\u0925\\u094d\\u092f\\u093e\\u0902\\u0928\\u093e \\u0938\\u0939\\u091c \\u0938\\u092e\\u091c\\u0924\\u0947 \\u0906\\u0923\\u093f \\u0936\\u093f\\u0915\\u0923\\u0947 \\u0906\\u0928\\u0902\\u0926\\u0926\\u093e\\u092f\\u0940 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Why did Boond feel exhausted when the Sun rose?\",\"a\":\"Boond felt exhausted because the Sun\\u2019s heat made the environment hot, starting evaporation.\",\"e\":\"\\u0938\\u0942\\u0930\\u094d\\u092f \\u0909\\u0917\\u0935\\u0932\\u094d\\u092f\\u093e\\u0935\\u0930 \\u0909\\u0937\\u094d\\u0923\\u0924\\u093e \\u0935\\u093e\\u0922\\u0932\\u0940 \\u0906\\u0923\\u093f \\u092c\\u093e\\u0937\\u094d\\u092a\\u0940\\u092d\\u0935\\u0928 \\u092a\\u094d\\u0930\\u0915\\u094d\\u0930\\u093f\\u092f\\u093e \\u0938\\u0941\\u0930\\u0942 \\u091d\\u093e\\u0932\\u0940, \\u0924\\u094d\\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u092c\\u0942\\u0902\\u0926 \\u0925\\u0915\\u0932\\u0947\\u0932\\u0940 \\u0935\\u093e\\u091f\\u0932\\u0940.\"},{\"q\":\"Why did Badal invite Boond to come up?\",\"a\":\"Badal invited Boond because it was cooler in the cloud.\",\"e\":\"\\u092c\\u0926\\u0932\\u093e\\u0928\\u0947 \\u092c\\u0942\\u0902\\u0926\\u0932\\u093e \\u0935\\u0930 \\u092f\\u0947\\u0923\\u094d\\u092f\\u093e\\u0938\\u093e\\u0920\\u0940 \\u092c\\u094b\\u0932\\u093e\\u0935\\u0932\\u0947 \\u0915\\u093e\\u0930\\u0923 \\u0922\\u0917\\u093e\\u0902\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0935\\u093e\\u0924\\u093e\\u0935\\u0930\\u0923 \\u0925\\u0902\\u0921 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Why is Jharna described as making a lot of noise?\",\"a\":\"Jharna is a waterfall, and waterfalls make noise as water falls from height.\",\"e\":\"\\u091d\\u0930\\u093e \\u0909\\u0902\\u091a\\u093e\\u0935\\u0930\\u0942\\u0928 \\u0916\\u093e\\u0932\\u0940 \\u092a\\u0921\\u0924\\u094b \\u0924\\u094d\\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0906\\u0935\\u093e\\u091c \\u0939\\u094b\\u0924\\u094b. \\u092e\\u094d\\u0939\\u0923\\u0942\\u0928 \\u091d\\u0930\\u093e \\u092e\\u094b\\u0920\\u093e \\u0906\\u0935\\u093e\\u091c \\u0915\\u0930\\u0924\\u094b \\u0905\\u0938\\u0947 \\u0935\\u0930\\u094d\\u0923\\u0928 \\u0906\\u0939\\u0947.\"},{\"q\":\"Why is only 1% of water available for human use significant?\",\"a\":\"It shows that usable water is limited and must be conserved.\",\"e\":\"\\u092b\\u0915\\u094d\\u0924 1% \\u092a\\u093e\\u0923\\u0940 \\u092e\\u093e\\u0928\\u0935\\u093e\\u0938\\u093e\\u0920\\u0940 \\u0909\\u092a\\u0932\\u092c\\u094d\\u0927 \\u0906\\u0939\\u0947, \\u0924\\u094d\\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u092a\\u093e\\u0923\\u0940 \\u091c\\u092a\\u0923\\u0947 \\u0905\\u0924\\u094d\\u092f\\u0902\\u0924 \\u0906\\u0935\\u0936\\u094d\\u092f\\u0915 \\u0906\\u0939\\u0947.\"},{\"q\":\"What is the meaning of \\u2018exhausted\\u2019?\",\"a\":\"Exhausted means very tired.\",\"e\":\"\\u2018Exhausted\\u2019 \\u092e\\u094d\\u0939\\u0923\\u091c\\u0947 \\u0916\\u0942\\u092a \\u0925\\u0915\\u0932\\u0947\\u0932\\u093e.\"},{\"q\":\"How does Boond return to Sagar?\",\"a\":\"Boond returns through flowing water from the mountains back to the ocean.\",\"e\":\"\\u092a\\u0930\\u094d\\u0935\\u0924\\u093e\\u0902\\u0935\\u0930\\u0942\\u0928 \\u0935\\u093e\\u0939\\u0923\\u093e\\u0931\\u094d\\u092f\\u093e \\u092a\\u093e\\u0923\\u094d\\u092f\\u093e\\u092e\\u093e\\u0930\\u094d\\u0917\\u0947 \\u092c\\u0942\\u0902\\u0926 \\u092a\\u0941\\u0928\\u094d\\u0939\\u093e \\u0938\\u092e\\u0941\\u0926\\u094d\\u0930\\u093e\\u0924 \\u091c\\u093e\\u0924\\u0947.\"},{\"q\":\"Why should narrative paragraphs be written in past tense?\",\"a\":\"Because they describe events that have already happened.\",\"e\":\"\\u0915\\u0925\\u0928\\u093e\\u0924\\u094d\\u092e\\u0915 \\u092a\\u0930\\u093f\\u091a\\u094d\\u091b\\u0947\\u0926 \\u092d\\u0942\\u0924\\u0915\\u093e\\u0933\\u093e\\u0924 \\u0932\\u093f\\u0939\\u093f\\u0932\\u0947 \\u091c\\u093e\\u0924\\u093e\\u0924 \\u0915\\u093e\\u0930\\u0923 \\u0924\\u0947 \\u0906\\u0927\\u0940 \\u0918\\u0921\\u0932\\u0947\\u0932\\u094d\\u092f\\u093e \\u0918\\u091f\\u0928\\u093e\\u0902\\u091a\\u0947 \\u0935\\u0930\\u094d\\u0923\\u0928 \\u0915\\u0930\\u0924\\u093e\\u0924.\"}]','BOOND','2026-02-12 17:20:02'),(32,134,'MY BROTHER ON WHEELCHAIR - Revision','[{\"q\":\"\\ufeffQuestion\",\"a\":\"Answer\",\"e\":\"Explaination in Marathi language\"},{\"q\":\"Explain how the poem \\u2018My Brother\\u2019s Wheelchair\\u2019 promotes the idea of inclusion and equality.\",\"a\":\"The poem presents Dhrubo as confident, joyful and independent. Through shared adventures with his sister, it shows that disability does not limit one\\u2019s spirit. The poem promotes inclusion by normalising accessibility and celebrating companionship.\",\"e\":\"\\u092f\\u093e \\u0915\\u0935\\u093f\\u0924\\u0947\\u0924 \\u0927\\u094d\\u0930\\u0941\\u0935\\u094b \\u0906\\u0924\\u094d\\u092e\\u0935\\u093f\\u0936\\u094d\\u0935\\u093e\\u0938\\u092a\\u0942\\u0930\\u094d\\u0923, \\u0906\\u0928\\u0902\\u0926\\u0940 \\u0906\\u0923\\u093f \\u0938\\u094d\\u0935\\u093e\\u0935\\u0932\\u0902\\u092c\\u0940 \\u092e\\u094d\\u0939\\u0923\\u0942\\u0928 \\u0926\\u093e\\u0916\\u0935\\u0932\\u0947 \\u0906\\u0939\\u0947. \\u092c\\u0939\\u093f\\u0923\\u0940\\u0938\\u094b\\u092c\\u0924\\u091a\\u094d\\u092f\\u093e \\u0938\\u093e\\u0939\\u0938\\u093e\\u0902\\u092e\\u0927\\u0942\\u0928 \\u0905\\u092a\\u0902\\u0917\\u0924\\u094d\\u0935 \\u0939\\u0947 \\u092e\\u0930\\u094d\\u092f\\u093e\\u0926\\u093e \\u0928\\u0938\\u0942\\u0928 \\u0935\\u094d\\u092f\\u0915\\u094d\\u0924\\u093f\\u092e\\u0924\\u094d\\u0924\\u094d\\u0935\\u093e\\u091a\\u093e \\u092d\\u093e\\u0917 \\u0906\\u0939\\u0947 \\u0939\\u0947 \\u0938\\u093e\\u0902\\u0917\\u093f\\u0924\\u0932\\u0947 \\u0906\\u0939\\u0947. \\u0915\\u0935\\u093f\\u0924\\u093e \\u0938\\u092e\\u093e\\u0928\\u0924\\u093e \\u0906\\u0923\\u093f \\u0938\\u092e\\u093e\\u0935\\u0947\\u0936\\u0915\\u0924\\u0947\\u091a\\u093e \\u0938\\u0902\\u0926\\u0947\\u0936 \\u0926\\u0947\\u0924\\u0947.\"},{\"q\":\"Describe the relationship between Durva and Dhrubo as shown in the poem.\",\"a\":\"Durva shares a loving and playful bond with Dhrubo. She expresses pride, excitement and admiration for him. Their companionship highlights emotional strength and mutual support.\",\"e\":\"\\u0926\\u0941\\u0930\\u094d\\u0935\\u093e \\u0906\\u0923\\u093f \\u0927\\u094d\\u0930\\u0941\\u0935\\u094b \\u092f\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e\\u0924 \\u092a\\u094d\\u0930\\u0947\\u092e\\u0933 \\u0906\\u0923\\u093f \\u0916\\u0947\\u0933\\u0915\\u0930 \\u0928\\u093e\\u0924\\u0947 \\u0906\\u0939\\u0947. \\u0926\\u0941\\u0930\\u094d\\u0935\\u093e \\u0924\\u094d\\u092f\\u093e\\u091a\\u094d\\u092f\\u093e\\u092c\\u0926\\u094d\\u0926\\u0932 \\u0905\\u092d\\u093f\\u092e\\u093e\\u0928 \\u0906\\u0923\\u093f \\u0906\\u0928\\u0902\\u0926 \\u0935\\u094d\\u092f\\u0915\\u094d\\u0924 \\u0915\\u0930\\u0924\\u0947. \\u0924\\u094d\\u092f\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u0928\\u093e\\u0924\\u094d\\u092f\\u093e\\u0924 \\u092a\\u0930\\u0938\\u094d\\u092a\\u0930 \\u0938\\u0939\\u0915\\u093e\\u0930\\u094d\\u092f \\u0906\\u0923\\u093f \\u092d\\u093e\\u0935\\u0928\\u093f\\u0915 \\u0924\\u093e\\u0915\\u0926 \\u0926\\u093f\\u0938\\u0942\\u0928 \\u092f\\u0947\\u0924\\u0947.\"},{\"q\":\"Discuss how the wheelchair is portrayed as a symbol in the poem.\",\"a\":\"The wheelchair is not shown as a limitation but as a symbol of freedom and individuality. It represents independence, movement and confidence in public spaces.\",\"e\":\"\\u0915\\u0935\\u093f\\u0924\\u0947\\u0924 \\u0935\\u094d\\u0939\\u0940\\u0932\\u091a\\u0947\\u0905\\u0930 \\u0939\\u0940 \\u092e\\u0930\\u094d\\u092f\\u093e\\u0926\\u093e \\u0928\\u0938\\u0942\\u0928 \\u0938\\u094d\\u0935\\u093e\\u0924\\u0902\\u0924\\u094d\\u0930\\u094d\\u092f \\u0906\\u0923\\u093f \\u0935\\u094d\\u092f\\u0915\\u094d\\u0924\\u093f\\u092e\\u0924\\u094d\\u0924\\u094d\\u0935\\u093e\\u091a\\u0947 \\u092a\\u094d\\u0930\\u0924\\u0940\\u0915 \\u092e\\u094d\\u0939\\u0923\\u0942\\u0928 \\u0926\\u093e\\u0916\\u0935\\u0932\\u0940 \\u0906\\u0939\\u0947. \\u0924\\u0940 \\u0938\\u094d\\u0935\\u093e\\u0935\\u0932\\u0902\\u092c\\u0928 \\u0906\\u0923\\u093f \\u0906\\u0924\\u094d\\u092e\\u0935\\u093f\\u0936\\u094d\\u0935\\u093e\\u0938 \\u0926\\u0930\\u094d\\u0936\\u0935\\u0924\\u0947.\"},{\"q\":\"Explain the importance of accessibility features such as ramps and special wheels in the poem.\",\"a\":\"Ramps and special wheels make movement easier and show the importance of inclusive infrastructure. They highlight the need for society to adapt spaces for everyone.\",\"e\":\"\\u0930\\u0945\\u092e\\u094d\\u092a \\u0906\\u0923\\u093f \\u0935\\u093f\\u0936\\u0947\\u0937 \\u091a\\u093e\\u0915\\u0947 \\u0939\\u093e\\u0932\\u091a\\u093e\\u0932\\u0940 \\u0938\\u0941\\u0932\\u092d \\u0915\\u0930\\u0924\\u093e\\u0924. \\u0924\\u094d\\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0938\\u092e\\u093e\\u091c\\u093e\\u0928\\u0947 \\u0938\\u0930\\u094d\\u0935\\u093e\\u0902\\u0938\\u093e\\u0920\\u0940 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e \\u0909\\u092a\\u0932\\u092c\\u094d\\u0927 \\u0915\\u0930\\u0942\\u0928 \\u0926\\u094d\\u092f\\u093e\\u0935\\u094d\\u092f\\u093e\\u0924 \\u0939\\u093e \\u0938\\u0902\\u0926\\u0947\\u0936 \\u0926\\u093f\\u0932\\u093e \\u0906\\u0939\\u0947.\"},{\"q\":\"How does the tone of the poem influence the reader\\u2019s understanding of disability?\",\"a\":\"The joyful and celebratory tone removes fear and negativity associated with disability. It encourages readers to view disability with empathy and positivity.\",\"e\":\"\\u0906\\u0928\\u0902\\u0926\\u0940 \\u0906\\u0923\\u093f \\u0909\\u0924\\u094d\\u0938\\u0935\\u092d\\u093e\\u0935\\u0928\\u0947\\u091a\\u093e \\u0938\\u0942\\u0930 \\u0905\\u092a\\u0902\\u0917\\u0924\\u094d\\u0935\\u093e\\u092c\\u0926\\u094d\\u0926\\u0932\\u091a\\u0940 \\u092d\\u0940\\u0924\\u0940 \\u0906\\u0923\\u093f \\u0928\\u0915\\u093e\\u0930\\u093e\\u0924\\u094d\\u092e\\u0915\\u0924\\u093e \\u0926\\u0942\\u0930 \\u0915\\u0930\\u0924\\u094b. \\u0935\\u093e\\u091a\\u0915\\u093e\\u0902\\u092e\\u0927\\u094d\\u092f\\u0947 \\u0938\\u0939\\u093e\\u0928\\u0941\\u092d\\u0942\\u0924\\u0940 \\u0906\\u0923\\u093f \\u0938\\u0915\\u093e\\u0930\\u093e\\u0924\\u094d\\u092e\\u0915\\u0924\\u093e \\u0928\\u093f\\u0930\\u094d\\u092e\\u093e\\u0923 \\u0939\\u094b\\u0924\\u0947.\"},{\"q\":\"Explain how the poem challenges stereotypes about people with disabilities.\",\"a\":\"Instead of portraying helplessness, the poem highlights confidence, independence and adventure. It challenges the stereotype that disability equals weakness.\",\"e\":\"\\u0915\\u0935\\u093f\\u0924\\u0947\\u0924 \\u0905\\u092a\\u0902\\u0917\\u0924\\u094d\\u0935 \\u092e\\u094d\\u0939\\u0923\\u091c\\u0947 \\u0915\\u092e\\u091c\\u094b\\u0930\\u0940 \\u0905\\u0938\\u093e \\u0938\\u092e\\u091c \\u092e\\u094b\\u0921\\u0942\\u0928 \\u0915\\u093e\\u0922\\u0932\\u093e \\u0906\\u0939\\u0947. \\u0906\\u0924\\u094d\\u092e\\u0935\\u093f\\u0936\\u094d\\u0935\\u093e\\u0938 \\u0906\\u0923\\u093f \\u0938\\u093e\\u0939\\u0938 \\u0926\\u093e\\u0916\\u0935\\u0942\\u0928 \\u0930\\u0942\\u0922\\u0940\\u0935\\u093e\\u0926\\u0940 \\u0935\\u093f\\u091a\\u093e\\u0930\\u093e\\u0902\\u0928\\u093e \\u0906\\u0935\\u094d\\u0939\\u093e\\u0928 \\u0926\\u093f\\u0932\\u0947 \\u0906\\u0939\\u0947.\"},{\"q\":\"Describe the role of family support in empowering Dhrubo.\",\"a\":\"Family members encourage participation, hiking and outdoor activities. Their support strengthens Dhrubo\\u2019s confidence and independence.\",\"e\":\"\\u0915\\u0941\\u091f\\u0941\\u0902\\u092c\\u093e\\u0924\\u0940\\u0932 \\u0938\\u0926\\u0938\\u094d\\u092f \\u0924\\u094d\\u092f\\u093e\\u0932\\u093e \\u092a\\u094d\\u0930\\u094b\\u0924\\u094d\\u0938\\u093e\\u0939\\u0928 \\u0926\\u0947\\u0924\\u093e\\u0924. \\u0924\\u094d\\u092f\\u093e\\u0902\\u091a\\u094d\\u092f\\u093e \\u092a\\u093e\\u0920\\u093f\\u0902\\u092c\\u094d\\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0927\\u094d\\u0930\\u0941\\u0935\\u094b\\u091a\\u093e \\u0906\\u0924\\u094d\\u092e\\u0935\\u093f\\u0936\\u094d\\u0935\\u093e\\u0938 \\u0935\\u093e\\u0922\\u0924\\u094b \\u0906\\u0923\\u093f \\u0924\\u094b \\u0938\\u094d\\u0935\\u093e\\u0935\\u0932\\u0902\\u092c\\u0940 \\u092c\\u0928\\u0924\\u094b.\"},{\"q\":\"Analyse how everyday settings like markets and parks contribute to the poem\\u2019s message.\",\"a\":\"By placing the story in familiar places, the poem normalises disability in daily life. It shows that inclusion belongs in ordinary public spaces.\",\"e\":\"\\u092c\\u093e\\u091c\\u093e\\u0930 \\u0906\\u0923\\u093f \\u0909\\u0926\\u094d\\u092f\\u093e\\u0928 \\u092f\\u093e\\u0902\\u0938\\u093e\\u0930\\u0916\\u094d\\u092f\\u093e \\u0920\\u093f\\u0915\\u093e\\u0923\\u0940 \\u0915\\u0925\\u093e \\u0918\\u0921\\u0935\\u0942\\u0928 \\u0926\\u0948\\u0928\\u0902\\u0926\\u093f\\u0928 \\u091c\\u0940\\u0935\\u0928\\u093e\\u0924 \\u0938\\u092e\\u093e\\u0935\\u0947\\u0936\\u0915\\u0924\\u093e \\u092e\\u0939\\u0924\\u094d\\u0935\\u093e\\u091a\\u0940 \\u0906\\u0939\\u0947 \\u0939\\u0947 \\u0926\\u093e\\u0916\\u0935\\u0932\\u0947 \\u0906\\u0939\\u0947.\"},{\"q\":\"Why is Dhrubo called the \\u2018wheelchair champ\\u2019?\",\"a\":\"He is admired for his confidence, courage and spirited participation in activities.\",\"e\":\"\\u0924\\u094b \\u0906\\u0924\\u094d\\u092e\\u0935\\u093f\\u0936\\u094d\\u0935\\u093e\\u0938\\u092a\\u0942\\u0930\\u094d\\u0923 \\u0906\\u0923\\u093f \\u0927\\u093e\\u0921\\u0938\\u0940 \\u0905\\u0938\\u0932\\u094d\\u092f\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0924\\u094d\\u092f\\u093e\\u0932\\u093e \\u2018\\u0935\\u094d\\u0939\\u0940\\u0932\\u091a\\u0947\\u0905\\u0930 \\u091a\\u0945\\u092e\\u094d\\u092a\\u2019 \\u092e\\u094d\\u0939\\u091f\\u0932\\u0947 \\u0906\\u0939\\u0947.\"},{\"q\":\"Why does Durva enjoy going to the market with her brother?\",\"a\":\"She enjoys the excitement and shared adventure of moving through busy streets.\",\"e\":\"\\u0917\\u0930\\u094d\\u0926\\u0940\\u091a\\u094d\\u092f\\u093e \\u0930\\u0938\\u094d\\u0924\\u094d\\u092f\\u093e\\u0935\\u0930 \\u090f\\u0915\\u0924\\u094d\\u0930 \\u092b\\u093f\\u0930\\u0923\\u094d\\u092f\\u093e\\u091a\\u093e \\u0930\\u094b\\u092e\\u093e\\u0902\\u091a \\u0924\\u093f\\u0932\\u093e \\u0906\\u0935\\u0921\\u0924\\u094b.\"},{\"q\":\"What does shouting \\u2018Wheeeeeeeeeeee!\\u2019 express in the poem?\",\"a\":\"It expresses thrill and happiness during the ride.\",\"e\":\"\\u2018Wheeeeeeeeeeee!\\u2019 \\u0939\\u093e \\u0936\\u092c\\u094d\\u0926 \\u0906\\u0928\\u0902\\u0926 \\u0906\\u0923\\u093f \\u0925\\u0930\\u093e\\u0930 \\u0935\\u094d\\u092f\\u0915\\u094d\\u0924 \\u0915\\u0930\\u0924\\u094b.\"},{\"q\":\"How do bright colours on the wheels reflect Dhrubo\\u2019s personality?\",\"a\":\"They show creativity, confidence and pride in his identity.\",\"e\":\"\\u0924\\u0947 \\u0930\\u0902\\u0917 \\u0924\\u094d\\u092f\\u093e\\u091a\\u094d\\u092f\\u093e \\u0906\\u0924\\u094d\\u092e\\u0935\\u093f\\u0936\\u094d\\u0935\\u093e\\u0938 \\u0906\\u0923\\u093f \\u0938\\u0930\\u094d\\u091c\\u0928\\u0936\\u0940\\u0932\\u0924\\u0947\\u091a\\u0947 \\u092a\\u094d\\u0930\\u0924\\u0940\\u0915 \\u0906\\u0939\\u0947\\u0924.\"},{\"q\":\"Why are ramps necessary in public spaces?\",\"a\":\"They ensure equal access and safe mobility for wheelchair users.\",\"e\":\"\\u0930\\u0945\\u092e\\u094d\\u092a\\u092e\\u0941\\u0933\\u0947 \\u0935\\u094d\\u0939\\u0940\\u0932\\u091a\\u0947\\u0905\\u0930 \\u0935\\u093e\\u092a\\u0930\\u0923\\u093e\\u0931\\u094d\\u092f\\u093e\\u0902\\u0928\\u093e \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0906\\u0923\\u093f \\u0938\\u0941\\u0932\\u092d \\u092a\\u094d\\u0930\\u0935\\u0947\\u0936 \\u092e\\u093f\\u0933\\u0924\\u094b.\"},{\"q\":\"What lesson does the poem teach about friendship?\",\"a\":\"True friendship includes acceptance, respect and shared joy.\",\"e\":\"\\u0916\\u0930\\u0940 \\u092e\\u0948\\u0924\\u094d\\u0930\\u0940 \\u0938\\u094d\\u0935\\u0940\\u0915\\u093e\\u0930 \\u0906\\u0923\\u093f \\u0906\\u0926\\u0930\\u093e\\u0935\\u0930 \\u0906\\u0927\\u093e\\u0930\\u093f\\u0924 \\u0905\\u0938\\u0924\\u0947 \\u0939\\u093e \\u0927\\u0921\\u093e \\u0926\\u093f\\u0932\\u093e \\u0906\\u0939\\u0947.\"},{\"q\":\"Why is first-person narration effective in this poem?\",\"a\":\"It creates emotional closeness and helps readers connect with the narrator\\u2019s feelings.\",\"e\":\"\\u092a\\u0939\\u093f\\u0932\\u094d\\u092f\\u093e \\u092a\\u0941\\u0930\\u0941\\u0937\\u0940 \\u0928\\u093f\\u0935\\u0947\\u0926\\u0928\\u093e\\u092e\\u0941\\u0933\\u0947 \\u0935\\u093e\\u091a\\u0915 \\u0915\\u0925\\u0947\\u0936\\u0940 \\u092d\\u093e\\u0935\\u0928\\u093f\\u0915\\u0930\\u0940\\u0924\\u094d\\u092f\\u093e \\u091c\\u094b\\u0921\\u0932\\u0947 \\u091c\\u093e\\u0924\\u093e\\u0924.\"}]','LONG ANSWER','2026-02-12 18:39:53');
