-- Dumping data for table `vocab_words`
--

LOCK TABLES `vocab_words` WRITE;
/*!40000 ALTER TABLE `vocab_words` DISABLE KEYS */;
INSERT INTO `vocab_words` VALUES (1,'Happy','Feeling or showing pleasure or contentment.','',11,NULL,NULL,'Easy','Moderate',NULL,NULL,NULL,NULL,NULL,1,15,'2026-01-08 06:29:30','2026-02-01 22:38:37','आनंदी, समाधानी.',1,'Beginner','{\"A\":\"Sad\",\"B\":\"Joyful\",\"C\":\"Angry\",\"D\":\"Tired\"}','B'),(2,'Big','Of considerable size, extent, or intensity.','',11,NULL,NULL,'Easy','Moderate',NULL,NULL,NULL,NULL,NULL,1,12,'2026-01-08 06:29:30','2026-01-31 02:51:03','मोठा, विशाल.',1,'Beginner','{\"A\":\"Large\",\"B\":\"Small\",\"C\":\"Tiny\",\"D\":\"Weak\"}','A'),(3,'Fast','Moving or capable of moving at high speed.','',11,NULL,NULL,'Easy','Moderate',NULL,NULL,NULL,NULL,NULL,1,9,'2026-01-08 06:29:30','2026-01-31 02:51:11','वेगवान, जलद.',1,'Beginner','{\"A\":\"Slow\",\"B\":\"Lazy\",\"C\":\"Quick\",\"D\":\"Late\"}','C'),(4,'Beautiful','Pleasing the senses or mind aesthetically.','',11,NULL,NULL,'Easy','Moderate',NULL,NULL,NULL,NULL,NULL,1,6,'2026-01-08 06:29:30','2026-01-31 02:51:19','सुंदर, देखणा.',1,'Beginner','{\"A\":\"Ugly\",\"B\":\"Pretty\",\"C\":\"Dirty\",\"D\":\"Mean\"}','B'),(5,'Start','To cause something to happen or exist.','',11,NULL,NULL,'Easy','Moderate',NULL,NULL,NULL,NULL,NULL,1,6,'2026-01-08 06:29:30','2026-01-31 02:51:25','सुरुवात करणे.',1,'Beginner','{\"A\":\"Stop\",\"B\":\"End\",\"C\":\"Begin\",\"D\":\"Finish\"}','C'),(6,'Rich','Having a great deal of money or assets.','',11,NULL,NULL,'Easy','Moderate',NULL,NULL,NULL,NULL,NULL,1,6,'2026-01-08 06:29:30','2026-01-31 02:51:32','श्रीमंत, धनवान.',1,'Beginner','{\"A\":\"Poor\",\"B\":\"Weak\",\"C\":\"Wealthy\",\"D\":\"Sick\"}','C'),(7,'Smart','Having or showing a quick-witted intelligence.','',11,NULL,NULL,'Easy','Moderate',NULL,NULL,NULL,NULL,NULL,1,6,'2026-01-08 06:29:30','2026-01-31 02:51:38','हुशार, बुद्धिमान.',1,'Beginner','{\"A\":\"Dumb\",\"B\":\"Clever\",\"C\":\"Slow\",\"D\":\"Dull\"}','B'),(8,'Angry','Feeling or showing strong annoyance or hostility.','',11,NULL,NULL,'Easy','Moderate',NULL,NULL,NULL,NULL,